.pulso-main:has(.mon-page) {
  max-width: none;
  padding: 8px;
}

.mon-page .pulso-page-frame-body {
  gap: 10px;
}

.mon-page .pulso-page-frame-body--fill {
  display: flex;
  flex-direction: column;
}

.mon-page .pulso-panel {
  margin-bottom: 0;
}

.mon-workbench {
  flex: 1 1 auto;
  min-height: 0;
  grid-template-columns: minmax(196px, 226px) minmax(0, 1fr);
  border-radius: var(--pulso-radius-panel);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(248, 250, 253, 0.98)),
    var(--pulso-surface);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.82),
    0 16px 44px rgba(0, 36, 87, 0.08);
}

.mon-workbench.pulso-split-view {
  grid-template-columns: minmax(196px, 226px) minmax(0, 1fr);
}

.mon-page .pulso-page-frame-body--fill > .mon-workbench {
  height: 100%;
  min-height: 0;
}

.mon-workbench-rail {
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  align-content: start;
  gap: 8px;
  padding: 8px;
  background:
    linear-gradient(180deg, rgba(248, 250, 253, 0.92), rgba(255, 255, 255, 0.72)),
    var(--pulso-surface-2);
}

.mon-rail-head {
  display: grid;
  gap: 3px;
  padding: 3px 2px 0;
}

.mon-rail-head strong {
  color: var(--pulso-text);
  font-size: 14px;
  line-height: 1.25;
}

.mon-rail-head small {
  color: var(--pulso-text-soft);
  font-size: 10.5px;
  font-weight: 650;
}

.mon-rail-section-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 2px 2px 0;
  color: var(--pulso-text-soft);
}

.mon-rail-section-label span,
.mon-rail-section-label em {
  font-size: 9.5px;
  font-weight: 860;
  letter-spacing: 0.06em;
  line-height: 1.1;
  text-transform: uppercase;
}

.mon-rail-section-label em {
  font-style: normal;
  color: var(--pulso-text-faint);
}

.mon-route-hub {
  flex: 1 1 auto;
  min-height: var(--pulso-operational-min-workbench);
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  align-content: stretch;
  gap: 14px;
  border: 1px solid var(--pulso-border);
  border-radius: var(--pulso-radius-panel);
  background: var(--pulso-surface);
  padding: 18px;
}

.mon-route-hub-head {
  max-width: 820px;
  display: grid;
  gap: 5px;
}

.mon-route-hub-head h2 {
  margin: 0;
  color: var(--pulso-text);
  font-size: 22px;
  line-height: 1.15;
}

.mon-route-hub-head p {
  margin: 0;
  color: var(--pulso-text-soft);
  font-size: 13px;
  line-height: 1.45;
}

.mon-route-grid {
  min-height: var(--pulso-operational-min-list);
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  grid-template-rows: minmax(0, 1fr);
  grid-auto-rows: minmax(0, 1fr);
  gap: 12px;
  align-content: stretch;
  align-items: stretch;
  overflow: auto;
  padding-bottom: 4px;
}

.mon-route-card {
  min-width: 0;
  min-height: 0;
  height: 100%;
  display: grid;
  grid-template-rows: auto auto auto minmax(0, 1fr) auto;
  gap: 12px;
  border: 1px solid var(--pulso-border);
  border-radius: 10px;
  background: color-mix(in srgb, var(--pulso-surface) 92%, var(--pulso-surface-2) 8%);
  padding: 14px;
  box-shadow: var(--pulso-shadow-low);
}

.mon-route-card.is-active-route {
  border-color: color-mix(in srgb, var(--pulso-module-monitoring) 58%, var(--pulso-border));
  background:
    linear-gradient(180deg, rgba(204, 16, 73, 0.035), rgba(255, 255, 255, 0) 34%),
    color-mix(in srgb, var(--pulso-surface) 92%, var(--pulso-surface-2) 8%);
}

.mon-route-card.is-planned {
  opacity: 0.72;
}

.mon-route-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.mon-route-icon {
  width: 36px;
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--pulso-border);
  border-radius: 9px;
  background: #fff;
  color: var(--pulso-module-monitoring);
}

.mon-route-status {
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--pulso-border);
  border-radius: var(--pulso-radius-chip);
  background: var(--pulso-surface-2);
  color: var(--pulso-text-soft);
  padding: 3px 8px;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
}

.mon-route-status.is-ready {
  color: var(--pulso-success-fg);
  border-color: var(--pulso-success-border);
  background: var(--pulso-success-bg);
}

.mon-route-copy {
  min-width: 0;
  display: grid;
  gap: 5px;
}

.mon-route-copy h3 {
  margin: 0;
  color: var(--pulso-text);
  font-size: 17px;
  line-height: 1.16;
}

.mon-route-copy p {
  margin: 0;
  color: var(--pulso-text-soft);
  font-size: 12px;
  line-height: 1.38;
}

.mon-route-tags,
.mon-route-sources {
  gap: 6px;
  align-items: stretch;
}

.mon-route-tags {
  display: flex;
  flex-wrap: wrap;
  align-content: flex-start;
}

.mon-route-sources {
  position: relative;
  display: grid;
  grid-auto-rows: minmax(52px, max-content);
  gap: 9px;
  align-content: space-between;
  align-self: stretch;
  min-height: 0;
  overflow: auto;
  margin-top: 0;
  padding: 8px;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 74%, white);
  border-radius: 9px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.78), rgba(248, 250, 253, 0.7)),
    repeating-linear-gradient(90deg, rgba(15, 23, 42, 0.03) 0, rgba(15, 23, 42, 0.03) 1px, transparent 1px, transparent 42px);
}

.mon-route-sources::before {
  content: "";
  position: absolute;
  top: 24px;
  bottom: 24px;
  left: 25px;
  width: 2px;
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(204, 16, 73, 0.72), rgba(31, 113, 188, 0.62), rgba(20, 141, 88, 0.58));
}

.mon-route-tags span,
.mon-route-sources em {
  min-height: 23px;
  display: inline-flex;
  align-items: center;
  border-radius: var(--pulso-radius-chip);
  padding: 3px 8px;
  font-size: 10.5px;
  line-height: 1.2;
}

.mon-route-tags span {
  color: var(--pulso-primary);
  border: 1px solid var(--pulso-primary-border);
  background: var(--pulso-primary-soft);
  font-weight: 760;
}

.mon-route-sources em {
  position: relative;
  z-index: 1;
  min-width: 0;
  min-height: 48px;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 9px;
  color: var(--pulso-text);
  border: 1px solid color-mix(in srgb, var(--pulso-border) 82%, white);
  border-radius: 7px;
  background: #fff;
  font-style: normal;
  font-weight: 760;
  padding: 7px 9px 7px 39px;
  overflow-wrap: anywhere;
  box-shadow: 0 1px 0 rgba(15, 23, 42, 0.04);
}

.mon-route-sources em::before {
  content: "";
  position: absolute;
  top: 10px;
  bottom: 10px;
  left: 7px;
  width: 4px;
  border-radius: 999px;
  background: var(--route-step-color, var(--pulso-module-monitoring));
}

.mon-route-sources em i {
  position: absolute;
  left: 16px;
  top: 50%;
  transform: translateY(-50%);
  width: 22px;
  height: 22px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid color-mix(in srgb, var(--route-step-color, var(--pulso-module-monitoring)) 36%, var(--pulso-border));
  border-radius: 6px;
  background: color-mix(in srgb, var(--route-step-color, var(--pulso-module-monitoring)) 12%, #fff 88%);
  color: color-mix(in srgb, var(--route-step-color, var(--pulso-module-monitoring)) 82%, #102033 18%);
  font-size: 9px;
  font-style: normal;
  font-weight: 850;
  letter-spacing: 0.02em;
}

.mon-route-sources em span {
  min-width: 0;
  display: block;
  font-size: 12px;
  line-height: 1.2;
}

.mon-route-sources em small {
  display: block;
  margin-top: 3px;
  color: var(--pulso-text-soft);
  font-size: 10.5px;
  line-height: 1.25;
  font-weight: 650;
}

.mon-route-sources em:nth-child(1) { --route-step-color: #cc1049; }
.mon-route-sources em:nth-child(2) { --route-step-color: #1f71bc; }
.mon-route-sources em:nth-child(3) { --route-step-color: #148d58; }
.mon-route-sources em:nth-child(4) { --route-step-color: #a15c00; }

.mon-route-card--territorial .mon-route-sources em:nth-child(1) { --route-step-color: #287c7a; }
.mon-route-card--territorial .mon-route-sources em:nth-child(2) { --route-step-color: #6f65c8; }
.mon-route-card--territorial .mon-route-sources em:nth-child(3) { --route-step-color: #2f7d32; }

.mon-route-card--telefonico .mon-route-sources em:nth-child(1) { --route-step-color: #b5446e; }
.mon-route-card--telefonico .mon-route-sources em:nth-child(2) { --route-step-color: #3b6ea8; }
.mon-route-card--telefonico .mon-route-sources em:nth-child(3) { --route-step-color: #16885f; }

.mon-route-card button {
  margin-top: 0;
  min-height: 34px;
  border: 1px solid var(--pulso-border);
  border-radius: 8px;
  background: #fff;
  color: var(--pulso-text);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  font-size: 12px;
  font-weight: 780;
  cursor: pointer;
}

.mon-route-card button.pulso-primary {
  color: #fff;
  border-color: var(--pulso-module-monitoring);
  background: var(--pulso-module-monitoring);
}

.mon-route-card button:disabled {
  cursor: not-allowed;
}

.mon-workbench-nav {
  display: grid;
  grid-auto-rows: minmax(66px, auto);
  align-content: start;
  gap: 6px;
  min-height: 0;
  overflow: auto;
}

.mon-nav-item {
  --view-accent: var(--pulso-module-monitoring);
  position: relative;
  width: 100%;
  min-height: 50px;
  display: grid;
  grid-template-columns: 26px minmax(0, 1fr) auto;
  align-items: center;
  gap: 7px;
  border: 1px solid var(--pulso-border);
  border-radius: 10px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.9), rgba(248, 250, 253, 0.84)),
    rgba(255, 255, 255, 0.76);
  color: var(--pulso-text);
  padding: 6px;
  text-align: left;
  cursor: pointer;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.72);
  transition:
    background-color 120ms ease,
    border-color 120ms ease,
    color 120ms ease,
    box-shadow 120ms ease;
}

.mon-nav-item::before {
  content: "";
  position: absolute;
  inset: 8px auto 8px 0;
  width: 3px;
  border-radius: 0 999px 999px 0;
  background: color-mix(in srgb, var(--view-accent) 58%, transparent);
  opacity: 0;
}

.mon-nav-item.is-fuentes { --view-accent: #cc1049; }
.mon-nav-item.is-modelo { --view-accent: #0f766e; }
.mon-nav-item.is-avance { --view-accent: #2563eb; }
.mon-nav-item.is-telefonico { --view-accent: #be123c; }
.mon-nav-item.is-calidad { --view-accent: #b45309; }

.mon-nav-item.is-active::before {
  opacity: 1;
}

.mon-nav-item:hover {
  border-color: color-mix(in srgb, var(--view-accent) 28%, var(--pulso-border));
  background: color-mix(in srgb, var(--view-accent) 7%, white);
}

.mon-nav-item:active {
  transform: none;
}

.mon-nav-item.is-active {
  border-color: color-mix(in srgb, var(--view-accent) 52%, var(--pulso-border));
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--view-accent) 9%, #fff), rgba(255, 255, 255, 0.92)),
    color-mix(in srgb, var(--view-accent) 8%, white);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.78),
    0 6px 18px color-mix(in srgb, var(--view-accent) 10%, transparent);
}

.mon-nav-icon,
.mon-workbench-head-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--pulso-border);
  border-radius: 10px;
  background: #fff;
  color: var(--view-accent, var(--pulso-module-monitoring));
}

.mon-nav-icon {
  width: 26px;
  height: 26px;
}

.mon-nav-copy {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.mon-nav-copy strong,
.mon-nav-copy span {
  overflow: visible;
  text-overflow: clip;
  white-space: normal;
  overflow-wrap: anywhere;
}

.mon-nav-copy strong {
  color: var(--pulso-text);
  font-size: 12px;
  line-height: 1.2;
}

.mon-nav-copy span {
  color: var(--pulso-text-soft);
  font-size: 10.5px;
  line-height: 1.25;
}

.mon-nav-current {
  color: var(--pulso-success-fg);
}

.mon-rail-web-publish {
  min-width: 0;
}

.mon-rail-web-publish-trigger {
  width: 100%;
  min-width: 0;
  min-height: 58px;
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  border: 1px solid color-mix(in srgb, var(--pulso-module-monitoring) 28%, var(--pulso-border));
  border-radius: 10px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--pulso-module-monitoring) 6%, #fff), rgba(255, 255, 255, 0.94)),
    #fff;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.76);
  color: inherit;
  cursor: pointer;
  font: inherit;
  padding: 8px;
  text-align: left;
  transition:
    border-color var(--motion-dur-fast) var(--motion-ease-out),
    box-shadow var(--motion-dur-fast) var(--motion-ease-out),
    transform var(--motion-dur-press) var(--motion-ease-out);
}

.mon-rail-web-publish-trigger:hover {
  border-color: color-mix(in srgb, var(--pulso-module-monitoring) 42%, var(--pulso-border));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.82),
    0 8px 18px rgba(190, 18, 60, 0.08);
}

.mon-rail-web-publish-trigger:active {
  transform: scale(0.985);
}

.mon-rail-web-publish-trigger:focus-visible {
  outline: 2px solid transparent;
  box-shadow:
    0 0 0 3px color-mix(in srgb, var(--pulso-module-monitoring) 16%, transparent),
    inset 0 1px 0 rgba(255, 255, 255, 0.82);
}

.mon-rail-web-publish-trigger-icon {
  width: 30px;
  height: 30px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid color-mix(in srgb, var(--pulso-module-monitoring) 24%, var(--pulso-border));
  border-radius: 8px;
  background: color-mix(in srgb, var(--pulso-module-monitoring) 8%, #fff);
  color: var(--pulso-module-monitoring);
}

.mon-rail-web-publish-trigger-copy {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.mon-rail-web-publish-trigger-copy span,
.mon-rail-web-publish-trigger-copy strong,
.mon-rail-web-publish-trigger-copy small {
  min-width: 0;
  overflow: hidden;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-rail-web-publish-trigger-copy span {
  color: var(--pulso-module-monitoring);
  font-size: 9.5px;
  font-weight: 880;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.mon-rail-web-publish-trigger-copy strong {
  color: var(--pulso-text);
  font-size: 12px;
  font-weight: 900;
}

.mon-rail-web-publish-trigger-copy small {
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-weight: 700;
}

.mon-rail-web-publish-trigger-chevron {
  color: var(--pulso-text-soft);
  transition: transform var(--motion-dur-fast) var(--motion-ease-out);
}

.mon-rail-web-publish-trigger[data-state="open"] .mon-rail-web-publish-trigger-chevron {
  transform: rotate(180deg);
}

.mon-rail-web-publish > small {
  display: block;
  margin-top: 5px;
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-weight: 690;
  line-height: 1.25;
}

.mon-rail-web-publish-popover {
  z-index: 80;
  width: min(382px, calc(100vw - 24px));
  display: grid;
  gap: 10px;
  border: 1px solid color-mix(in srgb, var(--pulso-module-monitoring) 24%, var(--pulso-border));
  border-radius: 12px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.97), rgba(249, 250, 252, 0.96)),
    var(--pulso-surface);
  box-shadow: var(--pulso-shadow-popover);
  color: var(--pulso-text);
  padding: 10px;
}

.mon-rail-web-publish-popover-head {
  min-width: 0;
  display: grid;
  gap: 3px;
  padding: 2px 2px 0;
}

.mon-rail-web-publish-popover-head span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--pulso-module-monitoring);
  font-size: 10px;
  font-weight: 880;
  letter-spacing: 0.06em;
  line-height: 1.15;
  text-transform: uppercase;
}

.mon-rail-web-publish-popover-head strong {
  color: var(--pulso-text);
  font-size: 14px;
  font-weight: 900;
  line-height: 1.12;
}

.mon-rail-web-publish-popover-head small {
  color: var(--pulso-text-soft);
  font-size: 11px;
  font-weight: 680;
  line-height: 1.28;
}

.mon-rail-web-publish-popover-body {
  min-width: 0;
  display: grid;
  gap: 8px;
}

.mon-rail-web-publish-arrow {
  fill: color-mix(in srgb, var(--pulso-module-monitoring) 10%, #fff);
  stroke: color-mix(in srgb, var(--pulso-module-monitoring) 24%, var(--pulso-border));
}

.mon-rail-web-publish-item {
  min-width: 0;
  display: grid;
  gap: 8px;
  border: 1px solid color-mix(in srgb, var(--pulso-module-monitoring) 18%, var(--pulso-border));
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.72);
  padding: 9px;
}

.mon-rail-web-publish-item:not(.is-sheets) {
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
}

.mon-rail-web-publish-item.is-internal {
  border-color: color-mix(in srgb, var(--pulso-danger-fg) 22%, var(--pulso-border));
  background: color-mix(in srgb, var(--pulso-danger-bg) 36%, #fff);
}

.mon-rail-web-publish-item.is-sheets {
  border-color: color-mix(in srgb, #2563eb 26%, var(--pulso-border));
  background:
    linear-gradient(180deg, color-mix(in srgb, #2563eb 7%, #fff), rgba(255, 255, 255, 0.88)),
    #fff;
}

.mon-rail-web-publish-item > div:first-child {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.mon-rail-web-publish-item > div:first-child > span {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-module-monitoring);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.08em;
  line-height: 1.15;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.mon-rail-web-publish-item.is-internal > div:first-child > span {
  color: var(--pulso-danger-fg);
}

.mon-rail-web-publish-item.is-sheets > div:first-child > span {
  color: #1d4ed8;
}

.mon-rail-web-publish-item strong,
.mon-rail-web-publish-item small {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.mon-rail-web-publish-item strong {
  color: var(--pulso-text);
  font-size: 11px;
  font-weight: 880;
}

.mon-rail-web-publish-item small {
  color: var(--pulso-text-soft);
  font-size: 9.5px;
  font-weight: 700;
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.mon-rail-web-publish-actions {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 6px;
}

.mon-rail-web-publish-actions.has-open {
  grid-template-columns: 34px minmax(0, 1fr);
}

.mon-rail-web-publish-actions a,
.mon-rail-web-publish-actions button {
  min-width: 0;
  min-height: 30px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid color-mix(in srgb, var(--pulso-module-monitoring) 42%, var(--pulso-border));
  border-radius: 8px;
  background: color-mix(in srgb, var(--pulso-module-monitoring) 9%, #fff);
  color: color-mix(in srgb, var(--pulso-module-monitoring) 82%, var(--pulso-text));
