  opacity: 0.55;
}

.mon-rail-web-publish-sheets {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
}

.mon-rail-web-publish-sheets button,
.mon-rail-web-publish-sheet-links a {
  min-width: 0;
  min-height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid var(--pulso-border);
  border-radius: 8px;
  background: var(--pulso-surface);
  color: var(--pulso-text-soft);
  cursor: pointer;
  font: inherit;
  font-size: 10.5px;
  font-weight: 820;
  padding: 0 8px;
  text-decoration: none;
  white-space: nowrap;
}

.mon-rail-web-publish-sheets button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.mon-rail-web-publish-sheet-links {
  min-width: 0;
  display: grid;
  gap: 5px;
}

.mon-rail-web-publish-sheet-links a {
  min-height: 24px;
  justify-content: flex-start;
  border-color: color-mix(in srgb, #2563eb 18%, var(--pulso-border));
  color: #1d4ed8;
  font-size: 10px;
  padding: 0 7px;
}

.mon-rail-web-publish-error {
  color: var(--pulso-danger-fg);
  font-size: 10px;
  font-style: normal;
  font-weight: 760;
  line-height: 1.25;
}

.mon-rail-phase-switch {
  display: grid;
  gap: 6px;
  padding-top: 8px;
  border-top: 1px solid var(--pulso-border);
}

.mon-rail-phase-switch > span {
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-weight: 820;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.mon-rail-phase-switch > div {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 4px;
  border: 1px solid var(--pulso-border);
  border-radius: 12px;
  background: color-mix(in srgb, var(--pulso-surface-2) 78%, white);
  padding: 4px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.72);
}

.mon-rail-phase-switch button {
  min-width: 0;
  min-height: 42px;
  display: grid;
  align-content: center;
  gap: 2px;
  border: 1px solid transparent;
  border-radius: 9px;
  background: transparent;
  color: var(--pulso-text-soft);
  padding: 6px 7px;
  text-align: left;
  cursor: pointer;
}

.mon-rail-phase-switch button:not(:disabled):hover {
  border-color: color-mix(in srgb, var(--pulso-module-monitoring) 24%, var(--pulso-border));
  background: rgba(255, 255, 255, 0.76);
  color: var(--pulso-text);
}

.mon-rail-phase-switch button.is-active {
  border-color: color-mix(in srgb, var(--pulso-module-monitoring) 40%, var(--pulso-border));
  background: #fff;
  color: var(--pulso-text);
  box-shadow:
    0 1px 2px rgba(15, 23, 42, 0.08),
    0 8px 18px rgba(15, 23, 42, 0.06);
}

.mon-rail-phase-switch strong {
  font-size: 12px;
  font-weight: 900;
  line-height: 1.05;
}

.mon-rail-phase-switch small {
  font-size: 9.5px;
  font-weight: 760;
  line-height: 1.05;
}

.mon-rail-phase-switch em {
  color: var(--pulso-text-muted);
  font-size: 10.5px;
  font-style: normal;
  font-weight: 680;
  line-height: 1.25;
}

.mon-rail-phase-status.is-missing_source {
  color: var(--pulso-warn-fg);
}

.mon-rail-phase-status.is-error {
  color: var(--pulso-danger-fg);
}

.mon-rail-phase-status.is-configured {
  color: var(--pulso-success-fg);
}

.mon-rail-phase-status.is-source_applied_not_synced,
.mon-rail-phase-status.is-dashboard_stale {
  color: var(--pulso-warn-fg);
}

.mon-rail-phase-status.is-source_not_applied {
  color: var(--pulso-text-muted);
}

.mon-rail-phase-status.is-source_synced_with_rows {
  color: var(--pulso-success-fg);
}

.mon-rail-phase-status.is-source_synced_zero_rows {
  color: var(--pulso-text-soft);
}

.mon-rail-phase-status.is-source_snapshot_mismatch,
.mon-rail-phase-status.is-sync_error {
  color: var(--pulso-danger-fg);
}

.mon-rail-status {
  display: grid;
  gap: 6px;
  padding-top: 8px;
  border-top: 1px solid var(--pulso-border);
}

.mon-rail-sync {
  display: grid;
  gap: 2px;
  border: 1px solid var(--pulso-border);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.78);
  padding: 7px 8px;
}

.mon-rail-sync span {
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-weight: 760;
  text-transform: uppercase;
}

.mon-rail-sync strong {
  color: var(--pulso-text);
  font-size: 13px;
  font-weight: 780;
  line-height: 1.2;
}

.mon-rail-sync.is-ready {
  border-color: var(--pulso-success-border);
  background: color-mix(in srgb, var(--pulso-success-bg) 58%, white);
}

@media (max-width: 1320px), (max-height: 720px) {
  .mon-workbench.pulso-split-view {
    grid-template-columns: minmax(184px, 214px) minmax(0, 1fr);
  }

  .mon-workbench-rail {
    gap: 6px;
    padding: 6px;
  }

  .mon-rail-head {
    gap: 2px;
    padding: 2px 1px 0;
  }

  .mon-rail-head strong {
    font-size: 12.5px;
  }

  .mon-rail-head small {
    font-size: 9.5px;
  }

  .mon-rail-section-label {
    gap: 6px;
    padding: 1px 1px 0;
  }

  .mon-rail-section-label span,
  .mon-rail-section-label em {
    font-size: 8.8px;
    letter-spacing: 0.05em;
  }

  .mon-workbench-nav {
    grid-auto-rows: minmax(66px, auto);
    gap: 4px;
  }

  .mon-nav-item {
    min-height: 64px;
    grid-template-columns: 22px minmax(0, 1fr) auto;
    gap: 6px;
    border-radius: 8px;
    padding: 5px;
  }

  .mon-nav-item::before {
    inset: 7px auto 7px 0;
    width: 2px;
  }

  .mon-nav-icon {
    width: 22px;
    height: 22px;
    border-radius: 8px;
  }

  .mon-nav-icon svg {
    width: 13px;
    height: 13px;
  }

  .mon-nav-copy {
    gap: 1px;
  }

  .mon-nav-copy strong {
    font-size: 11px;
    line-height: 1.12;
  }

  .mon-nav-copy span {
    overflow: hidden;
    font-size: 9.5px;
    line-height: 1.15;
    text-overflow: ellipsis;
    white-space: nowrap;
    overflow-wrap: normal;
  }

  .mon-nav-current {
    width: 11px;
    height: 11px;
  }

  .mon-rail-web-publish-trigger {
    min-height: 46px;
    grid-template-columns: 24px minmax(0, 1fr) auto;
    gap: 6px;
    border-radius: 9px;
    padding: 6px;
  }

  .mon-rail-web-publish-trigger-icon {
    width: 24px;
    height: 24px;
    border-radius: 7px;
  }

  .mon-rail-web-publish-trigger-icon svg,
  .mon-rail-web-publish-trigger-chevron {
    width: 12px;
    height: 12px;
  }

  .mon-rail-web-publish-trigger-copy span {
    font-size: 8.8px;
  }

  .mon-rail-web-publish-trigger-copy strong {
    font-size: 11px;
  }

  .mon-rail-web-publish-trigger-copy small {
    font-size: 9.2px;
  }

  .mon-rail-web-publish > small {
    margin-top: 4px;
    font-size: 9.2px;
  }

  .mon-rail-phase-switch {
    gap: 5px;
    padding-top: 6px;
  }

  .mon-rail-phase-switch > span {
    font-size: 9px;
  }

  .mon-rail-phase-switch > div {
    border-radius: 10px;
    padding: 3px;
  }

  .mon-rail-phase-switch button {
    min-height: 34px;
    border-radius: 8px;
    padding: 5px 6px;
  }

  .mon-rail-phase-switch strong {
    font-size: 11px;
  }

  .mon-rail-phase-switch small {
    font-size: 8.8px;
  }

  .mon-rail-phase-switch em {
    font-size: 9.4px;
  }

  .mon-rail-status {
    gap: 5px;
    padding-top: 6px;
  }

  .mon-rail-sync {
    gap: 1px;
    border-radius: 8px;
    padding: 6px 7px;
  }

  .mon-rail-sync span {
    font-size: 8.8px;
  }

  .mon-rail-sync strong {
    font-size: 11.8px;
    line-height: 1.15;
  }
}

@media (max-width: 1080px), (max-height: 640px) {
  .mon-route-grid {
    grid-auto-rows: auto;
  }

  .mon-route-card {
    grid-template-rows: auto auto auto auto auto;
    gap: 6px;
    padding: 9px 10px;
  }

  .mon-route-icon {
    width: 30px;
    height: 30px;
    border-radius: 8px;
  }

  .mon-route-status {
    min-height: 20px;
    padding: 2px 7px;
    font-size: 8.8px;
  }

  .mon-route-copy {
    gap: 3px;
  }

  .mon-route-copy h3 {
    font-size: 15px;
  }

  .mon-route-copy p {
    display: -webkit-box;
    overflow: hidden;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
  }

  .mon-route-sources {
    display: none;
  }

  .mon-route-tags span:nth-child(n+3) {
    display: none;
  }

  .mon-route-card button {
    min-height: 30px;
  }

  .mon-territorial-form-picker {
    min-height: 118px;
  }

  .mon-workbench.pulso-split-view {
    grid-template-columns: minmax(170px, 196px) minmax(0, 1fr);
  }

  .mon-nav-copy span {
    display: none;
  }

  .mon-nav-item {
    min-height: 56px;
  }

  .mon-rail-head small {
    display: none;
  }

  .mon-rail-section-label em {
    display: none;
  }
}

.mon-workbench-main {
  min-width: 0;
  min-height: 0;
  height: 100%;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  overflow: hidden;
  background: var(--pulso-surface);
}

.mon-workbench-main.is-territorial {
  grid-template-rows: auto minmax(0, 1fr);
}

.mon-workbench-main.is-territorial.has-report-status {
  grid-template-rows: auto auto minmax(0, 1fr);
}

.mon-workbench-main.is-territorial .mon-workbench-head {
  grid-template-columns: 38px minmax(0, 1fr) minmax(0, 0.46fr);
}

.mon-workbench-main.is-territorial .mon-workbench-pills {
  max-width: 100%;
}

.mon-workbench-head {
  z-index: 3;
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 11px 12px;
  border-bottom: 1px solid var(--pulso-border);
  background: var(--pulso-surface);
}

.mon-workbench-head-icon {
  width: 36px;
  height: 36px;
}

.mon-workbench-head-copy {
  min-width: 0;
  display: grid;
  gap: 1px;
}

.mon-workbench-head-copy h2 {
  margin: 0;
  color: var(--pulso-text);
  font-size: 15px;
  line-height: 1.2;
}

.mon-workbench-head-copy p {
  margin: 0;
  color: var(--pulso-text-soft);
  font-size: 11.5px;
  line-height: 1.35;
}

.mon-workbench-pills {
