}

.mon-territorial-report-status.is-error {
  background: color-mix(in srgb, var(--pulso-danger-bg) 44%, #fff 56%);
  color: var(--pulso-danger-fg);
}

.mon-territorial-boot {
  width: 100%;
  min-height: max(560px, calc(100vh - 166px));
  height: 100%;
  flex: 1 1 auto;
  display: grid;
  align-items: start;
  justify-items: center;
  padding: clamp(46px, 10vh, 110px) clamp(18px, 4vw, 54px) clamp(28px, 5vh, 62px);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(248, 250, 252, 0.9)),
    var(--pulso-surface);
  border: 1px solid var(--pulso-border);
  border-radius: var(--pulso-radius-lg);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.72),
    0 18px 42px rgba(15, 23, 42, 0.08);
}

.mon-territorial-boot-shell {
  width: min(1060px, 100%);
  display: grid;
  grid-template-columns: minmax(150px, 190px) minmax(250px, 0.92fr) minmax(300px, 1.08fr);
  align-items: center;
  gap: clamp(18px, 3vw, 34px);
}

.mon-territorial-boot-ring-wrap {
  min-width: 0;
  display: grid;
  justify-items: center;
  gap: 12px;
  color: var(--pulso-text-soft);
  font-size: 12px;
  font-weight: 760;
  text-align: center;
}

.mon-territorial-boot-ring {
  --mon-territorial-boot-progress: 28deg;
  width: clamp(128px, 13vw, 168px);
  aspect-ratio: 1;
  border-radius: 999px;
  display: grid;
  place-items: center;
  background:
    conic-gradient(
      from -90deg,
      color-mix(in srgb, var(--pulso-primary) 82%, #0f766e 18%) var(--mon-territorial-boot-progress),
      color-mix(in srgb, var(--pulso-border) 72%, #fff 28%) 0
    );
  box-shadow:
    0 16px 34px rgba(12, 74, 110, 0.16),
    inset 0 0 0 1px rgba(255, 255, 255, 0.72);
}

.mon-territorial-boot-ring > div {
  width: calc(100% - 28px);
