  border-radius: inherit;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 6px;
  background:
    linear-gradient(180deg, #fff, color-mix(in srgb, var(--pulso-surface-2) 76%, #fff 24%));
  color: var(--pulso-primary-strong);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.9),
    0 8px 20px rgba(15, 23, 42, 0.09);
}

.mon-territorial-boot-ring strong {
  font-size: 18px;
  font-weight: 860;
  letter-spacing: 0;
}

.mon-territorial-boot-copy {
  min-width: 0;
  display: grid;
  gap: 10px;
}

.mon-territorial-boot-eyebrow {
  color: var(--pulso-primary-strong);
  font-size: 11px;
  font-weight: 820;
  letter-spacing: 0;
  text-transform: uppercase;
}

.mon-territorial-boot-copy h2 {
  margin: 0;
  color: var(--pulso-text);
  font-size: clamp(24px, 3vw, 36px);
  line-height: 1.08;
  letter-spacing: 0;
}

.mon-territorial-boot-copy p {
  max-width: 52ch;
  margin: 0;
  color: var(--pulso-text-soft);
  font-size: 14px;
  line-height: 1.5;
  font-weight: 650;
}

.mon-territorial-boot-meta {
  min-width: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.mon-territorial-boot-meta span {
  min-height: 28px;
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--pulso-border);
  border-radius: var(--pulso-radius-chip);
  background: color-mix(in srgb, var(--pulso-surface-2) 72%, #fff 28%);
  color: var(--pulso-text-soft);
  font-size: 11px;
  font-weight: 760;
  padding: 5px 10px;
}

.mon-territorial-boot-steps {
