.mon-territorial-boot-step strong {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 13px;
  font-weight: 820;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-territorial-boot-step em {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text-soft);
  font-size: 11.5px;
