.mon-territorial-boot-step.is-ready .mon-territorial-boot-step-icon,
.mon-territorial-boot-step.is-ready small {
  color: var(--pulso-success-fg);
  border-color: color-mix(in srgb, var(--pulso-success-border) 78%, var(--pulso-border) 22%);
