  grid-template-rows: auto minmax(0, 1fr);
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--pulso-module-monitoring) 22%, var(--pulso-border));
  border-radius: 12px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(248, 250, 252, 0.94)),
    var(--pulso-surface);
  box-shadow:
    0 22px 58px rgba(15, 23, 42, 0.2),
    0 0 0 1px rgba(255, 255, 255, 0.68) inset;
  color: var(--pulso-text);
  backdrop-filter: blur(18px) saturate(1.12);
}

.mon-output-suite-minimized {
  position: fixed;
  right: 22px;
  bottom: 22px;
  z-index: 140;
  min-height: 42px;
