  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
}

.mon-workbench-content--fuentes > .mon-stage--sources {
  flex: 1 1 auto;
  min-height: 100%;
  height: 100%;
  overflow-x: clip;
}

.mon-workbench-content--modelo {
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
}

.mon-workbench-content--modelo:has(.mon-territorial-route-workbench) {
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
}

.mon-workbench-content--modelo > .mon-stage--modelo {
  flex: 1 1 auto;
}

.mon-workbench-content:has(.mon-territorial-validation-tabbody--quota) {
