  font-weight: 840;
  line-height: 1.12;
}

.mon-advance-storage > header em,
.mon-advance-section-head em {
  flex: 0 0 auto;
  border: 1px solid var(--pulso-border);
  border-radius: var(--pulso-radius-chip);
  background: var(--pulso-surface-2);
