}

.mon-advance-actor-breakdown {
  grid-area: storage-actors;
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
  align-self: start;
}

.mon-advance-storage > .mon-advance-actor-breakdown {
  gap: 6px;
}

.mon-advance-storage .mon-advance-actor-breakdown span {
  --advance-actor-size: 0%;
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas:
    "label value"
    "bar bar";
  gap: 3px 7px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 88%, #fff);
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(248, 250, 253, 0.78)),
    var(--pulso-surface);
  padding: 7px 8px;
}

.mon-advance-storage .mon-advance-actor-breakdown em,
.mon-advance-storage .mon-advance-actor-breakdown strong {
  min-width: 0;
  overflow: hidden;
  line-height: 1.05;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-advance-storage .mon-advance-actor-breakdown em {
  grid-area: label;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--pulso-text-soft);
  font-size: 9.5px;
  font-style: normal;
  font-weight: 820;
  padding: 0;
  text-transform: uppercase;
}

.mon-advance-storage .mon-advance-actor-breakdown strong {
  grid-area: value;
  color: var(--pulso-text);
  font-size: 12px;
  font-weight: 860;
}

.mon-advance-storage .mon-advance-actor-breakdown i {
  grid-area: bar;
  height: 6px;
  border-radius: var(--pulso-radius-chip);
  background:
    linear-gradient(90deg, #5e7fa5 var(--advance-actor-size), color-mix(in srgb, var(--pulso-border) 72%, #fff 28%) var(--advance-actor-size));
}

.mon-advance-storage-bar {
  min-width: 0;
  height: 42px;
  display: flex;
  gap: 0;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 88%, #fff);
  border-radius: 8px;
  background: #eef2f7;
  box-shadow:
    inset 0 1px 2px rgba(15, 23, 42, 0.08),
    0 1px 0 rgba(255, 255, 255, 0.82);
  padding: 3px;
}

.mon-advance-storage-chart {
  grid-area: storage-chart;
  min-width: 0;
  position: relative;
  display: grid;
  gap: 7px;
  align-self: stretch;
  padding-bottom: 2px;
}

.mon-advance-storage-bar i {
  position: relative;
  flex: 0 0 var(--advance-storage-size);
  min-width: 6px;
  display: block;
  border-radius: 0;
  cursor: help;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.26),
    inset -1px 0 0 rgba(255, 255, 255, 0.52);
  transition:
    filter 140ms ease,
    box-shadow 140ms ease,
    opacity 140ms ease;
}

.mon-advance-storage-bar i:hover,
.mon-advance-storage-bar i:focus-visible {
  filter: saturate(1.08) brightness(1.04);
  outline: none;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.34),
    inset -1px 0 0 rgba(255, 255, 255, 0.58),
    inset 0 0 0 1px rgba(255, 255, 255, 0.68),
    0 0 0 1px rgba(15, 23, 42, 0.14);
}

.mon-advance-storage-bar i:first-child {
  border-top-left-radius: 5px;
  border-bottom-left-radius: 5px;
}

.mon-advance-storage-bar i:last-child {
  border-top-right-radius: 5px;
  border-bottom-right-radius: 5px;
}

.mon-advance-storage-bar i.is-completed {
  background: linear-gradient(180deg, #2fb673, #168a55);
}

.mon-advance-storage-bar i.is-partial {
  background: linear-gradient(180deg, #e0a329, #b97611);
}

.mon-advance-storage-bar i.is-refusals {
  background: linear-gradient(180deg, #c74872, #a61d4f);
}

.mon-advance-storage-bar i.is-phone {
  background: linear-gradient(180deg, #1798b8, #0a6b8f);
}

.mon-advance-storage-bar i.is-pending,
.mon-advance-storage-bar i.is-empty {
  background: linear-gradient(180deg, #d8e0ea, #aab7c8);
}

.mon-advance-target-marker {
  position: absolute;
  z-index: 2;
  top: 0;
  left: clamp(46px, var(--advance-target), calc(100% - 46px));
  min-height: 22px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  transform: translateX(-50%);
  border: 1px solid color-mix(in srgb, var(--pulso-warn-accent) 36%, var(--pulso-border));
  border-radius: var(--pulso-radius-chip);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.96), color-mix(in srgb, var(--pulso-warn-bg) 66%, #fff));
  color: var(--pulso-warn-fg);
  box-shadow:
    0 5px 14px rgba(146, 88, 0, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.88);
  padding: 3px 8px;
  pointer-events: none;
  white-space: nowrap;
}

.mon-advance-target-marker::after {
  content: "";
  position: absolute;
  top: 21px;
  left: 50%;
  width: 2px;
  height: 34px;
  transform: translateX(-50%);
  border-radius: var(--pulso-radius-chip);
  background: linear-gradient(180deg, var(--pulso-warn-accent), rgba(217, 119, 6, 0));
}

.mon-advance-target-marker em,
.mon-advance-target-marker strong {
  font-style: normal;
  line-height: 1;
}

.mon-advance-target-marker em {
  font-size: 9px;
  font-weight: 860;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.mon-advance-target-marker strong {
  color: var(--pulso-warn-fg);
  font-size: 11px;
  font-weight: 880;
}

.mon-advance-target-note {
  min-width: 0;
