  border: 1px solid color-mix(in srgb, var(--pulso-border) 86%, #fff);
  border-radius: 8px;
  background: color-mix(in srgb, #fff 86%, var(--pulso-surface-2));
  color: var(--pulso-text-soft);
  font-size: 10.5px;
  font-weight: 780;
  line-height: 1.15;
  padding: 4px 8px;
  text-align: center;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-advance-target-note span.is-gap {
  border-color: color-mix(in srgb, var(--pulso-warn-accent) 34%, var(--pulso-border));
  background: color-mix(in srgb, var(--pulso-warn-bg) 52%, #fff);
  color: var(--pulso-warn-fg);
}

.mon-advance-target-note span.is-surplus {
  border-color: color-mix(in srgb, var(--pulso-success-fg) 28%, var(--pulso-border));
  background: color-mix(in srgb, var(--pulso-success-bg) 50%, #fff);
  color: var(--pulso-success-fg);
}

.mon-advance-goal-strip {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(168px, 1fr));
  gap: 7px;
}

.mon-advance-goal-card {
  --advance-goal-accent: var(--pulso-accent-green);
  --advance-goal-pct: 0%;
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas:
    "label value"
