  background:
    linear-gradient(90deg, var(--advance-goal-accent) var(--advance-goal-pct), color-mix(in srgb, var(--pulso-border) 72%, #fff 28%) var(--advance-goal-pct));
}

.mon-advance-goal-card small {
  grid-area: hint;
