.mon-territorial-geo-virtual-list {
  position: relative;
  min-width: 0;
}

.mon-territorial-geo-virtual-item {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  min-width: 0;
  display: grid;
  gap: 4px;
  padding-bottom: 5px;
}

.mon-territorial-geo-district-group {
  min-width: 0;
  display: grid;
  gap: 5px;
}

.mon-territorial-geo-district-group:has(.mon-territorial-geo-district-trigger.is-expanded) {
  gap: 7px;
  padding-bottom: 10px;
}

.mon-territorial-geo-district-section {
  min-width: 0;
  display: grid;
  gap: 7px;
}

.mon-territorial-geo-district-section + .mon-territorial-geo-district-section {
  margin-top: 3px;
  padding-top: 8px;
  border-top: 1px solid color-mix(in srgb, var(--pulso-border) 76%, #fff);
}

.mon-territorial-geo-district-section.is-outside_frame {
  border-top-color: color-mix(in srgb, #b42318 20%, var(--pulso-border));
}

.mon-territorial-geo-district-section.is-without_gps {
  border-top-color: color-mix(in srgb, #667085 26%, var(--pulso-border));
}

.mon-territorial-geo-district-heading {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: var(--pulso-text-soft);
  font-size: 9.5px;
  font-weight: 850;
  text-transform: uppercase;
}

.mon-territorial-geo-district-section.is-outside_frame .mon-territorial-geo-district-heading strong {
  color: #991b1b;
}

.mon-territorial-geo-district-section.is-without_gps .mon-territorial-geo-district-heading strong {
  color: #475467;
}

.mon-territorial-geo-district-heading strong,
.mon-territorial-geo-district-heading span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-territorial-geo-district-heading span {
  flex: 0 0 auto;
  max-width: 58%;
}

.mon-territorial-geo-district-trigger {
  width: 100%;
  min-width: 0;
  min-height: 58px;
  display: grid;
  grid-template-columns: 26px minmax(0, 1fr);
  align-items: stretch;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 82%, #fff);
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(248, 250, 252, 0.84)),
    #fff;
  color: var(--pulso-text);
  contain: layout paint;
  overflow: hidden;
  transition:
    border-color var(--motion-dur-fast) var(--motion-ease-standard),
    box-shadow var(--motion-dur-fast) var(--motion-ease-standard);
}

.mon-territorial-geo-district-trigger:hover {
  border-color: color-mix(in srgb, var(--pulso-primary-border) 48%, var(--pulso-border));
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.05);
}

.mon-territorial-geo-district-trigger.is-selected {
  border-color: color-mix(in srgb, #7c3aed 34%, var(--pulso-border));
  background:
    linear-gradient(180deg, color-mix(in srgb, #7c3aed 5%, #fff), rgba(255, 255, 255, 0.94)),
    #fff;
  box-shadow:
    inset 2px 0 0 color-mix(in srgb, #7c3aed 64%, #fff),
    0 8px 18px rgba(15, 23, 42, 0.055);
}

.mon-territorial-geo-district-trigger.is-expanded {
  border-color: color-mix(in srgb, #0e7490 36%, var(--pulso-border));
}

.mon-territorial-geo-district-expander,
.mon-territorial-geo-district-main {
  min-width: 0;
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  font: inherit;
}

.mon-territorial-geo-district-expander {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--pulso-text-soft);
  padding: 0;
  transition:
    background var(--motion-dur-fast) var(--motion-ease-standard),
    color var(--motion-dur-fast) var(--motion-ease-standard);
}

.mon-territorial-geo-district-expander:hover {
  background: color-mix(in srgb, var(--pulso-primary-soft) 44%, transparent);
  color: #7c3aed;
}

.mon-territorial-geo-district-expander svg {
  transition: transform var(--motion-dur-fast) var(--motion-ease-standard);
}

.mon-territorial-geo-district-expander svg.is-expanded {
  transform: rotate(180deg);
}

.mon-territorial-geo-district-main {
  width: 100%;
  display: grid;
  grid-template-columns: minmax(170px, 1.18fr) minmax(142px, 0.74fr) minmax(126px, 0.58fr) max-content;
  grid-template-areas: "main risk owner metrics";
  align-items: center;
  gap: 8px;
  padding: 8px 10px 8px 0;
  text-align: left;
}

.mon-territorial-geo-district-main:hover .mon-territorial-geo-district-count {
  border-color: color-mix(in srgb, var(--pulso-primary-border) 54%, var(--pulso-border));
}

.mon-territorial-geo-district-copy {
  grid-area: main;
  min-width: 0;
  display: grid;
  gap: 2px;
}

.mon-territorial-geo-district-copy strong,
.mon-territorial-geo-district-copy em,
.mon-territorial-geo-district-count,
.mon-territorial-geo-district-owner,
.mon-territorial-geo-district-metrics,
.mon-territorial-geo-district-risk {
  min-width: 0;
  overflow: visible;
  text-overflow: clip;
}

.mon-territorial-geo-district-copy strong {
  color: var(--pulso-text);
  font-size: 11.5px;
  font-weight: 900;
  line-height: 1.16;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  overflow-wrap: anywhere;
  text-overflow: ellipsis;
}

.mon-territorial-geo-district-copy em,
.mon-territorial-geo-district-owner {
  color: var(--pulso-text-soft);
  font-size: 9px;
  font-weight: 740;
}

.mon-territorial-geo-district-copy em {
  display: -webkit-box;
  overflow: hidden;
  font-style: normal;
  line-height: 1.15;
  white-space: normal;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
}

.mon-territorial-geo-district-count {
  min-height: 21px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid color-mix(in srgb, #0e7490 24%, var(--pulso-border));
  border-radius: var(--pulso-radius-chip);
  background:
    linear-gradient(180deg, rgba(236, 253, 245, 0.92), rgba(240, 249, 255, 0.78)),
    #fff;
  color: #164e63;
  font-size: 8.8px;
  font-weight: 900;
  line-height: 1;
  padding: 0 6px;
  white-space: nowrap;
}

.mon-territorial-geo-district-count.is-selected-ump {
  border-color: color-mix(in srgb, #0e7490 34%, var(--pulso-border));
  background: color-mix(in srgb, #0e7490 8%, #fff);
  color: #155e75;
}

.mon-territorial-geo-district-risk {
  --geo-risk-color: #667085;
  grid-area: risk;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
  border: 1px solid color-mix(in srgb, var(--geo-risk-color) 18%, var(--pulso-border));
  border-radius: 7px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--geo-risk-color) 5%, #fff), rgba(255, 255, 255, 0.9)),
    #fff;
  padding: 5px 6px;
}

.mon-territorial-geo-district-risk > span {
  min-width: 0;
}

.mon-territorial-geo-district-risk > span:first-child {
  flex: 0 0 auto;
  display: grid;
  gap: 1px;
}

.mon-territorial-geo-district-risk > span:last-child {
  min-width: 0;
  flex: 1 1 82px;
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  justify-content: flex-start;
  overflow: visible;
}

.mon-territorial-geo-district-risk strong {
  color: color-mix(in srgb, var(--geo-risk-color) 82%, var(--pulso-text));
  font-size: 10.2px;
  font-weight: 920;
  line-height: 1;
  white-space: nowrap;
}

.mon-territorial-geo-district-risk em {
  color: var(--pulso-text-soft);
  font-size: 7.6px;
  font-style: normal;
  font-weight: 820;
  letter-spacing: 0;
  line-height: 1.1;
  text-transform: uppercase;
  white-space: nowrap;
}

.mon-territorial-geo-district-risk small {
  min-height: 17px;
  max-width: none;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  border: 1px solid color-mix(in srgb, currentColor 18%, var(--pulso-border));
  border-radius: var(--pulso-radius-chip);
  background: rgba(255, 255, 255, 0.72);
  font-size: 7.8px;
  font-weight: 880;
  line-height: 1;
  padding: 0 5px;
  white-space: nowrap;
}

.mon-territorial-geo-district-risk.is-ready {
  --geo-risk-color: #168a55;
}

.mon-territorial-geo-district-risk.is-warning {
  --geo-risk-color: #b7791f;
}

.mon-territorial-geo-district-risk.is-danger {
  --geo-risk-color: #b42318;
}

.mon-territorial-geo-district-risk.is-muted {
  --geo-risk-color: #667085;
}

.mon-territorial-geo-district-risk small.is-ready {
  color: #168a55;
}

.mon-territorial-geo-district-risk small.is-warning {
  color: #9a6700;
}

.mon-territorial-geo-district-risk small.is-danger {
  color: #991b1b;
}

.mon-territorial-geo-district-risk small.is-muted {
  color: #667085;
}

.mon-territorial-geo-district-owner {
  grid-area: owner;
  justify-self: start;
  max-width: 100%;
  display: -webkit-box;
  overflow: hidden;
  line-height: 1.16;
  text-align: left;
  white-space: normal;
  overflow-wrap: anywhere;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.mon-territorial-geo-district-metrics {
  grid-area: metrics;
  justify-self: end;
  min-width: max-content;
  display: inline-flex;
  flex-wrap: nowrap;
  align-items: center;
  justify-content: flex-end;
  gap: 5px;
}

.mon-territorial-geo-district-metrics > .mon-territorial-route-badge {
  justify-self: end;
  min-height: 21px;
  max-width: none;
  margin-top: 0;
  overflow: visible;
  padding-inline: 6px;
  text-overflow: clip;
  white-space: nowrap;
}

.mon-territorial-geo-district-cases {
  display: grid;
  gap: 6px;
  overflow: hidden;
  will-change: height, opacity;
  padding-bottom: 2px;
}

.mon-territorial-geo-district-cases.has-child-context {
  padding-left: 28px;
}

.mon-territorial-geo-district-cases.is-selected-ump {
  position: relative;
}

.mon-territorial-geo-district-cases.is-selected-ump::before {
  content: "";
  position: absolute;
  top: 2px;
  bottom: 2px;
  left: 12px;
  width: 2px;
  border-radius: 999px;
  background: linear-gradient(180deg, color-mix(in srgb, #0e7490 76%, #fff), color-mix(in srgb, #168a55 72%, #fff));
}

.mon-territorial-geo-child-context {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  border: 1px solid color-mix(in srgb, #0e7490 26%, var(--pulso-border));
  border-radius: 8px;
  background:
    linear-gradient(180deg, color-mix(in srgb, #0e7490 7%, #fff), rgba(255, 255, 255, 0.92)),
    #fff;
  color: #155e75;
  font-size: 9px;
  font-weight: 850;
  padding: 6px 8px;
}

.mon-territorial-geo-child-context span,
.mon-territorial-geo-child-context strong {
  min-width: 0;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-territorial-geo-child-context strong {
  flex: 0 0 auto;
  color: #334155;
  font-size: 8.5px;
  text-transform: uppercase;
}

.mon-territorial-geo-replacement-strip {
  min-width: 0;
  max-height: 66px;
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  overflow: auto;
  padding: 0 0 2px 28px;
  scrollbar-gutter: stable;
}

.mon-territorial-geo-replacement-strip .mon-territorial-route-badge {
  max-width: min(100%, 230px);
}

.mon-territorial-geo-replacement-strip button.mon-territorial-route-badge {
  margin-top: 0;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    border-color var(--motion-dur-fast) var(--motion-ease-standard),
    background var(--motion-dur-fast) var(--motion-ease-standard),
    box-shadow var(--motion-dur-fast) var(--motion-ease-standard),
    transform var(--motion-dur-press) var(--motion-ease-standard);
}

.mon-territorial-geo-replacement-strip button.mon-territorial-route-badge:hover,
.mon-territorial-geo-replacement-strip button.mon-territorial-route-badge.is-inspected {
  border-color: color-mix(in srgb, var(--pulso-warn-border) 84%, var(--pulso-primary-border));
  background: color-mix(in srgb, var(--pulso-warn-bg) 38%, #fff);
  box-shadow: 0 6px 14px rgba(180, 83, 9, 0.09);
}

.mon-territorial-geo-replacement-strip button.mon-territorial-route-badge:focus-visible {
  outline: none;
  box-shadow:
    0 0 0 3px color-mix(in srgb, var(--pulso-warn-accent) 16%, transparent),
    0 6px 14px rgba(180, 83, 9, 0.08);
}

.mon-territorial-geo-replacement-detail {
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 7px;
  margin-left: 28px;
  border: 1px solid color-mix(in srgb, var(--pulso-warn-border) 58%, var(--pulso-border));
  border-radius: 10px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--pulso-warn-bg) 28%, #fff), rgba(255, 255, 255, 0.92)),
    #fff;
  padding: 8px;
}

.mon-territorial-geo-replacement-detail > .mon-territorial-route-badge {
  margin-top: 0;
}

.mon-territorial-geo-replacement-detail > strong {
  min-width: 0;
  overflow: hidden;
  align-self: center;
  color: var(--pulso-text);
  font-size: 11px;
  font-weight: 900;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-territorial-geo-replacement-detail dl {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 5px;
  margin: 0;
}

.mon-territorial-geo-replacement-detail dl div {
  min-width: 0;
  display: grid;
  gap: 1px;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 74%, #fff);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.72);
  padding: 5px 6px;
}

.mon-territorial-geo-replacement-detail dt {
  color: var(--pulso-text-soft);
  font-size: 8px;
  font-weight: 880;
  text-transform: uppercase;
}

.mon-territorial-geo-replacement-detail dd {
  min-width: 0;
  margin: 0;
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 9.5px;
  font-weight: 790;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-territorial-geo-block-preview {
  justify-self: start;
  border: 0;
  background: transparent;
  color: var(--pulso-text-soft);
  cursor: pointer;
  font-size: 9.5px;
  font-weight: 760;
  padding: 0 0 0 28px;
  text-align: left;
}

.mon-territorial-geo-block-preview:hover {
  color: var(--pulso-primary-strong);
  text-decoration: underline;
}

.mon-territorial-geo-case-row {
  --geo-row-color: #667085;
  appearance: none;
  font: inherit;
  width: 100%;
  min-width: 0;
  min-height: 54px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) minmax(72px, 0.36fr) minmax(88px, 0.42fr) auto;
  align-items: center;
  gap: 8px;
  border: 1px solid color-mix(in srgb, var(--geo-row-color) 12%, var(--pulso-border));
  border-radius: 9px;
  background: #fff;
  color: var(--pulso-text);
  cursor: pointer;
  padding: 8px;
  text-align: left;
  transition:
    border-color var(--motion-dur-fast) var(--motion-ease-standard),
    background var(--motion-dur-fast) var(--motion-ease-standard),
    box-shadow var(--motion-dur-fast) var(--motion-ease-standard),
    transform var(--motion-dur-press) var(--motion-ease-standard);
}

.mon-territorial-geo-case-row.is-static {
  min-height: 72px;
  grid-template-columns: 14px minmax(82px, 0.56fr) minmax(190px, 1.35fr) minmax(150px, 1fr) 96px;
  grid-template-areas: "dot main person place action";
  gap: 8px 12px;
  transform: none;
}

.mon-territorial-geo-case-row:hover,
.mon-territorial-geo-case-row.is-selected {
  border-color: color-mix(in srgb, var(--geo-row-color) 42%, var(--pulso-border));
  background: color-mix(in srgb, var(--geo-row-color) 5%, #fff);
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.055);
}

.mon-territorial-geo-case-row.is-static:not(:disabled):hover {
  border-color: color-mix(in srgb, var(--geo-row-color) 48%, var(--pulso-border));
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--geo-row-color) 6%, #fff), #fff),
    #fff;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.82),
    0 8px 18px rgba(15, 23, 42, 0.06);
}

.mon-territorial-geo-case-row:disabled {
  cursor: default;
}

.mon-territorial-geo-case-row:focus-visible {
  outline: none;
  box-shadow:
    0 0 0 3px color-mix(in srgb, var(--geo-row-color) 14%, transparent),
    0 8px 18px rgba(15, 23, 42, 0.055);
}

.mon-territorial-geo-case-row.is-selected {
  box-shadow:
    inset 3px 0 0 var(--geo-row-color),
    0 8px 18px rgba(15, 23, 42, 0.055);
}

.mon-territorial-geo-case-row.is-no-gps {
  opacity: 0.78;
}

.mon-territorial-geo-case-row .mon-territorial-band {
  justify-self: end;
}

.mon-territorial-geo-case-dot {
  grid-area: dot;
  justify-self: center;
  width: 9px;
  height: 9px;
  border: 2px solid #fff;
  border-radius: 50%;
  background: var(--geo-row-color);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--geo-row-color) 38%, transparent);
}

.mon-territorial-geo-case-dot.is-geo_ok,
.mon-territorial-geo-case-row:has(.mon-territorial-geo-case-dot.is-geo_ok) { --geo-row-color: #168a55; }
.mon-territorial-geo-case-dot.is-geo_cerca,
.mon-territorial-geo-case-row:has(.mon-territorial-geo-case-dot.is-geo_cerca) { --geo-row-color: #0e7490; }
.mon-territorial-geo-case-dot.is-geo_revision,
.mon-territorial-geo-case-row:has(.mon-territorial-geo-case-dot.is-geo_revision) { --geo-row-color: #b7791f; }
.mon-territorial-geo-case-dot.is-geo_no_defendible,
.mon-territorial-geo-case-row:has(.mon-territorial-geo-case-dot.is-geo_no_defendible) { --geo-row-color: #b42318; }
.mon-territorial-geo-case-dot.is-geo_sin_cruce,
.mon-territorial-geo-case-row:has(.mon-territorial-geo-case-dot.is-geo_sin_cruce) { --geo-row-color: #9a5b00; }
.mon-territorial-geo-case-dot.is-geo_sin_gps,
.mon-territorial-geo-case-row:has(.mon-territorial-geo-case-dot.is-geo_sin_gps) { --geo-row-color: #667085; }
.mon-territorial-geo-case-dot.is-en_zona,
.mon-territorial-geo-case-row.is-en_zona { --geo-row-color: #168a55; }
.mon-territorial-geo-case-dot.is-en_distrito,
.mon-territorial-geo-case-row.is-en_distrito { --geo-row-color: #b7791f; }
.mon-territorial-geo-case-dot.is-fuera_distrito,
.mon-territorial-geo-case-row.is-fuera_distrito { --geo-row-color: #b42318; }
.mon-territorial-geo-case-dot.is-sin_cruce,
.mon-territorial-geo-case-row.is-sin_cruce { --geo-row-color: #9a5b00; }
.mon-territorial-geo-case-dot.is-sin_gps,
.mon-territorial-geo-case-row.is-sin_gps { --geo-row-color: #667085; }

.mon-territorial-geo-case-main,
.mon-territorial-geo-case-meta,
.mon-territorial-geo-case-place {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.mon-territorial-geo-case-row.is-static .mon-territorial-geo-case-main {
  grid-area: main;
  align-self: center;
}

.mon-territorial-geo-case-row.is-static .mon-territorial-geo-case-meta {
  grid-area: person;
  align-self: center;
}

.mon-territorial-geo-case-row.is-static .mon-territorial-geo-case-place {
  grid-area: place;
  align-self: center;
}

.mon-territorial-geo-case-main strong,
.mon-territorial-geo-case-main em,
.mon-territorial-geo-case-meta b,
.mon-territorial-geo-case-meta small,
.mon-territorial-geo-case-place b,
.mon-territorial-geo-case-place small,
.mon-territorial-geo-case-date {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-territorial-geo-case-main strong {
  font-size: 10.6px;
  font-weight: 880;
}

