  grid-template-rows: auto minmax(0, 1fr);
  gap: 12px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--pulso-primary-border) 36%, var(--pulso-border));
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), color-mix(in srgb, var(--pulso-surface-2) 46%, #fff)),
    var(--pulso-surface);
  padding: 10px;
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.06);
}

.mon-territorial-quota-commandbar {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(180px, 0.24fr) minmax(260px, 0.34fr) minmax(420px, 1fr);
  align-items: center;
  gap: 8px;
  border: 1px solid color-mix(in srgb, var(--pulso-primary-border) 34%, var(--pulso-border));
  border-radius: 8px;
  background: color-mix(in srgb, var(--pulso-surface) 92%, var(--pulso-surface-2));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.72),
    0 1px 2px rgba(15, 23, 42, 0.04);
  padding: 8px;
}

.mon-territorial-quota-command-title {
  min-width: 0;
  display: grid;
  gap: 1px;
  padding-left: 2px;
}

.mon-territorial-quota-command-title span {
  min-width: 0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  overflow: hidden;
  color: var(--pulso-primary);
  font-size: 10px;
  font-weight: 860;
  letter-spacing: 0;
  line-height: 1.1;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.mon-territorial-quota-command-title strong {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 14px;
  font-weight: 860;
  letter-spacing: 0;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-territorial-quota-search {
  min-width: 0;
  min-height: 34px;
  display: grid;
  grid-template-columns: 16px minmax(0, 1fr);
  align-items: center;
  gap: 7px;
  border: 1px solid color-mix(in srgb, var(--pulso-primary-border) 28%, var(--pulso-border));
  border-radius: 8px;
  background: #fff;
  color: var(--pulso-text-soft);
  padding: 0 10px;
  transition:
    border-color var(--motion-dur-fast) var(--motion-ease-out),
    box-shadow var(--motion-dur-fast) var(--motion-ease-out);
}

.mon-territorial-quota-search:focus-within {
  border-color: color-mix(in srgb, var(--pulso-primary) 58%, var(--pulso-border));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--pulso-primary) 12%, transparent);
}

.mon-territorial-quota-search input {
  width: 100%;
  min-width: 0;
  border: 0;
  background: transparent;
  color: var(--pulso-text);
  font: inherit;
  font-size: 12px;
  font-weight: 720;
  outline: 0;
}

.mon-territorial-quota-search input::placeholder {
  color: var(--pulso-text-faint);
}

.mon-territorial-quota-command-actions {
  min-width: 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 6px;
}

.mon-territorial-quota-command-actions [role="tablist"] {
  min-width: 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 5px;
}

.mon-territorial-quota-command-actions button {
  min-width: 0;
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid var(--pulso-border);
  border-radius: 8px;
  background: #fff;
  color: var(--pulso-text-soft);
  cursor: pointer;
  font: inherit;
  font-size: 10.5px;
  font-weight: 800;
  padding: 6px 8px;
  transition:
    background var(--motion-dur-fast) var(--motion-ease-out),
    border-color var(--motion-dur-fast) var(--motion-ease-out),
    color var(--motion-dur-fast) var(--motion-ease-out),
    transform var(--motion-dur-press) var(--motion-ease-out);
  white-space: nowrap;
}

.mon-territorial-quota-command-actions button:hover,
.mon-territorial-quota-command-actions button.is-active {
  border-color: color-mix(in srgb, var(--pulso-primary) 48%, var(--pulso-border));
  background: color-mix(in srgb, var(--pulso-primary-soft) 54%, #fff);
  color: var(--pulso-primary);
}

.mon-territorial-quota-command-actions button:active {
  transform: scale(0.98);
}

.mon-territorial-quota-command-actions button strong {
