  font-size: 11px;
  font-weight: 880;
  text-align: right;
}

.mon-territorial-quota-replacement-toggle {
  min-width: 0;
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-self: start;
  gap: 6px;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 88%, #fff);
  border-radius: 8px;
  background: color-mix(in srgb, var(--pulso-surface-2) 70%, #fff);
  color: var(--pulso-text-soft);
  cursor: pointer;
  font-size: 10.5px;
  font-weight: 800;
  padding: 6px 8px;
  transition:
    background var(--motion-dur-fast) var(--motion-ease-out),
    border-color var(--motion-dur-fast) var(--motion-ease-out),
    color var(--motion-dur-fast) var(--motion-ease-out);
  white-space: nowrap;
}

.mon-territorial-quota-replacement-toggle input {
  width: 13px;
  height: 13px;
  margin: 0;
  accent-color: var(--pulso-primary);
}

.mon-territorial-quota-replacement-toggle.is-active {
  border-color: color-mix(in srgb, var(--pulso-primary) 42%, var(--pulso-border));
  background: color-mix(in srgb, var(--pulso-primary-soft) 42%, #fff);
  color: var(--pulso-primary);
}

.mon-territorial-quota-replacement-toggle strong {
  min-width: 18px;
  color: currentColor;
  font-size: 11px;
  font-weight: 880;
  text-align: right;
}

.mon-territorial-quota-clear {
  color: var(--pulso-primary);
}

.mon-territorial-quota-block-list {
  min-width: 0;
  min-height: clamp(720px, calc(100vh - 250px), 1120px);
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(520px, 1fr));
  align-content: start;
  gap: 12px;
  overflow: auto;
  padding-right: 2px;
  padding-bottom: 12px;
  scrollbar-gutter: stable;
}

@media (max-width: 1500px) {
  .mon-territorial-quota-consistency {
    gap: 9px;
    padding: 8px;
  }

  .mon-territorial-quota-commandbar {
    grid-template-columns: minmax(190px, auto) minmax(0, 1fr);
    grid-template-areas:
      "title search"
      "actions actions";
    gap: 7px;
    padding: 7px;
  }

  .mon-territorial-quota-command-title {
    grid-area: title;
  }

  .mon-territorial-quota-search {
    grid-area: search;
  }

  .mon-territorial-quota-command-actions {
    grid-area: actions;
    flex-wrap: nowrap;
    justify-content: flex-end;
  }

  .mon-territorial-quota-command-actions [role="tablist"] {
    flex-wrap: nowrap;
  }

  .mon-territorial-quota-block-list {
    grid-template-columns: repeat(auto-fill, minmax(500px, 1fr));
