  .mon-territorial-quota-block-card > header strong {
    font-size: 15px;
  }

  .mon-territorial-quota-block-card > header b {
    min-height: 24px;
    padding: 4px 8px;
  }

  .mon-territorial-quota-block-meta {
    gap: 5px;
  }

  .mon-territorial-quota-block-meta span {
    padding: 5px 7px;
  }

  .mon-territorial-quota-total-meter {
    height: 6px;
  }

  .mon-territorial-quota-margins {
    grid-template-columns: repeat(2, minmax(190px, 1fr));
    gap: 6px;
  }

  .mon-territorial-quota-margin-group {
    gap: 6px;
    padding: 7px;
  }

  .mon-territorial-quota-margin-group > div {
    gap: 4px;
  }

  .mon-territorial-quota-margin-row {
    gap: 2px 6px;
  }

  .mon-territorial-quota-observed {
    gap: 6px;
    padding: 7px;
  }

  .mon-territorial-quota-layer-strip {
    gap: 5px;
  }

  .mon-territorial-quota-layer-strip > span {
    gap: 2px;
