  }

  .mon-territorial-quota-layer-strip strong {
    font-size: 13px;
  }

  .mon-territorial-quota-layer-strip em {
    font-size: 8.2px;
  }

  .mon-territorial-quota-observed th,
  .mon-territorial-quota-observed td {
    padding: 5px 6px;
  }

  .mon-territorial-quota-observed > p {
    display: none;
  }
}

