  .mon-territorial-validation-tabs {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .mon-territorial-quota-commandbar {
    grid-template-columns: 1fr;
    grid-template-areas:
      "title"
      "search"
      "actions";
  }

  .mon-territorial-quota-command-actions,
  .mon-territorial-quota-command-actions [role="tablist"] {
    justify-content: flex-end;
  }

  .mon-territorial-quota-search {
    max-width: none;
  }

  .mon-territorial-quota-block-list {
    min-height: clamp(620px, calc(100vh - 300px), 1040px);
