}

.mon-operational-suggestion__chips i.is-choice em {
  grid-column: 2;
}

.mon-operational-adjustments__detail {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 0;
  height: 100%;
  overflow: hidden;
}

.mon-operational-adjustments__detail-body {
  min-height: 0;
