  background:
    linear-gradient(180deg, color-mix(in srgb, var(--op-surplus-soft) 82%, #fff), #fff),
    #fff;
}

.mon-operational-decision-spine article.is-pending {
  border-color: var(--op-pending-border);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--op-pending-soft) 86%, #fff), #fff),
    #fff;
}

.mon-operational-decision-spine article span,
.mon-operational-decision-facts em {
  color: var(--pulso-text-muted);
  font-size: 0.62rem;
  font-weight: 920;
  letter-spacing: 0.07em;
  line-height: 1;
  text-transform: uppercase;
}

.mon-operational-decision-spine article.is-surplus span,
.mon-operational-decision-spine article.is-surplus strong {
  color: var(--op-surplus);
}

.mon-operational-decision-spine article.is-pending span,
.mon-operational-decision-spine article.is-pending strong {
  color: var(--pulso-warn-fg);
}

.mon-operational-decision-spine article strong,
.mon-operational-decision-spine article em,
.mon-operational-decision-facts strong,
.mon-operational-decision-facts em {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-operational-decision-spine article strong {
  color: var(--pulso-text);
  font-size: 0.98rem;
  font-weight: 930;
  line-height: 1.18;
}

.mon-operational-decision-spine article em {
  color: color-mix(in srgb, var(--pulso-text-muted) 82%, var(--pulso-text));
  font-size: 0.7rem;
  font-style: normal;
  font-weight: 760;
  line-height: 1.2;
}

.mon-operational-decision-spine__flow {
  min-width: 0;
  min-height: 82px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 3px;
  border: 1px solid color-mix(in srgb, var(--op-surplus) 28%, var(--op-pending-border));
  border-radius: 14px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--op-surplus-soft) 72%, #fff), color-mix(in srgb, var(--op-pending-soft) 72%, #fff)),
    #fff;
  color: color-mix(in srgb, var(--op-surplus) 58%, var(--pulso-warn-fg));
  text-align: center;
  padding: 8px 6px;
}

.mon-operational-decision-spine__flow strong,
.mon-operational-decision-spine__flow em {
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-operational-decision-spine__flow strong {
  color: currentColor;
  font-size: 0.72rem;
  font-weight: 930;
  line-height: 1.05;
}

.mon-operational-decision-spine__flow em {
  color: color-mix(in srgb, currentColor 72%, var(--pulso-text-muted));
  font-size: 0.56rem;
  font-style: normal;
  font-weight: 860;
  line-height: 1;
}

.mon-operational-decision-facts {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 0.72fr) minmax(0, 0.84fr) minmax(0, 1.38fr) minmax(0, 1.14fr);
  gap: 7px;
}

.mon-operational-decision-facts span {
  min-width: 0;
  min-height: 50px;
  display: grid;
  align-content: center;
  gap: 3px;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 88%, #fff);
  border-radius: 12px;
  background: color-mix(in srgb, var(--pulso-muted-surface) 72%, #fff);
  padding: 8px 10px;
}

.mon-operational-decision-facts span.is-complete {
  border-color: var(--op-complete-border);
  background: var(--op-complete-soft);
}

.mon-operational-decision-facts span.is-surplus {
  border-color: var(--op-surplus-border);
  background: var(--op-surplus-soft);
}

.mon-operational-decision-facts span.is-pending {
  border-color: var(--op-pending-border);
  background: var(--op-pending-soft);
}

.mon-operational-decision-facts span.is-cell,
.mon-operational-decision-facts span.is-activity {
  align-content: start;
}

.mon-operational-decision-facts strong {
  color: var(--pulso-text);
  font-size: 0.86rem;
  font-weight: 920;
  line-height: 1.1;
}

.mon-operational-decision-facts span.is-complete strong {
  color: var(--op-complete);
}

.mon-operational-decision-facts span.is-surplus strong {
  color: var(--op-surplus);
}

.mon-operational-decision-facts span.is-pending strong {
  color: var(--pulso-warn-fg);
}

.mon-operational-decision-facts span.is-cell strong,
.mon-operational-decision-facts span.is-activity strong {
  display: -webkit-box;
  overflow: hidden;
  line-height: 1.08;
  text-overflow: ellipsis;
  white-space: normal;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.mon-operational-guardrails {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
}

.mon-operational-guardrails span {
  min-width: 0;
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid var(--pulso-border);
  border-radius: 999px;
  background: #fff;
  color: var(--pulso-text-muted);
  font-size: 0.68rem;
  font-weight: 900;
  line-height: 1.1;
  overflow: hidden;
  padding: 6px 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-operational-guardrails span.is-complete {
  border-color: var(--op-complete-border);
  background: var(--op-complete-soft);
  color: var(--op-complete);
}

.mon-operational-guardrails span.is-pending {
  border-color: var(--op-pending-border);
  background: var(--op-pending-soft);
  color: var(--pulso-warn-fg);
}

.mon-operational-guardrails span.is-surplus {
  border-color: var(--op-surplus-border);
  background: var(--op-surplus-soft);
  color: var(--op-surplus);
}

.mon-operational-adjustments__detail dl {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin: 0;
  padding: 0;
}

.mon-operational-adjustments__detail dl div {
  min-width: 0;
  display: grid;
  gap: 3px;
  padding: 10px 11px;
  border: 1px solid var(--pulso-border);
  border-radius: 12px;
  background: var(--pulso-muted-surface);
}

.mon-operational-adjustments__detail dl div.is-surplus {
  border-color: var(--op-surplus-border);
  background: var(--op-surplus-soft);
}

.mon-operational-adjustments__detail dl div.is-pending {
  border-color: var(--op-pending-border);
  background: var(--op-pending-soft);
}

.mon-operational-adjustments__detail dl div.is-distance {
  border-color: color-mix(in srgb, var(--op-surplus) 24%, var(--pulso-warn-border));
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--op-surplus) 8%, #fff), color-mix(in srgb, var(--pulso-warn-bg) 58%, #fff));
}

.mon-operational-adjustments__detail dl div.is-surplus dt,
.mon-operational-adjustments__detail dl div.is-surplus dd {
  color: var(--op-surplus);
}

.mon-operational-adjustments__detail dl div.is-pending dt,
.mon-operational-adjustments__detail dl div.is-pending dd {
  color: var(--pulso-warn-fg);
}

.mon-operational-adjustments__detail dt {
  color: var(--pulso-text-muted);
  font-size: 0.68rem;
  font-weight: 900;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.mon-operational-adjustments__detail dd {
  min-width: 0;
  margin: 0;
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 0.86rem;
  font-weight: 760;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-operational-adjustments__detail dd svg {
  flex: 0 0 auto;
}

.mon-operational-adjustments__detail dl div.is-distance dd {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: color-mix(in srgb, var(--op-surplus) 58%, var(--pulso-warn-fg));
}

.mon-operational-package-ledger {
  min-width: 0;
  display: grid;
  gap: 7px;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 86%, #fff);
