  border: 0;
}

.mon-operational-package-ledger header span {
  color: var(--pulso-text-muted);
  font-size: 0.66rem;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.mon-operational-package-ledger header strong {
  color: var(--pulso-text);
  font-size: 0.78rem;
  font-weight: 900;
  white-space: nowrap;
}

.mon-operational-package-ledger > div {
  display: grid;
  gap: 6px;
}

.mon-operational-package-ledger article {
  min-width: 0;
