  align-items: center;
  border: 1px solid color-mix(in srgb, var(--op-surplus) 14%, var(--pulso-border));
  border-radius: 11px;
  background: color-mix(in srgb, var(--op-surplus-soft) 58%, #fff);
  padding: 7px 8px;
}

.mon-operational-package-ledger article span {
  grid-row: span 2;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 28px;
  border-radius: 9px;
  background: #fff;
  color: var(--op-surplus);
  font-size: 0.82rem;
  font-weight: 930;
}

.mon-operational-package-ledger article strong,
.mon-operational-package-ledger article em {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-operational-package-ledger article strong {
  color: var(--pulso-text);
  font-size: 0.78rem;
  font-weight: 880;
}

.mon-operational-package-ledger article em {
  color: var(--pulso-text-muted);
  font-size: 0.68rem;
  font-style: normal;
  font-weight: 760;
}

.mon-operational-adjustments__note {
  display: grid;
  grid-template-rows: auto minmax(82px, auto);
  gap: 7px;
  min-height: 0;
  padding: 0;
}

.mon-operational-adjustments__note span {
  color: var(--pulso-text-muted);
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.mon-operational-adjustments__note textarea {
  width: 100%;
  min-height: 82px;
  height: 100%;
  resize: vertical;
  border: 1px solid var(--pulso-border-strong);
  border-radius: 14px;
  padding: 10px 11px;
  color: var(--pulso-text);
  background: #ffffff;
  font: inherit;
  line-height: 1.38;
  outline: none;
}

.mon-operational-adjustments__note textarea:focus-visible {
  border-color: color-mix(in srgb, var(--pulso-accent) 46%, var(--pulso-border));
