  padding: 11px 13px 13px;
}

.mon-operational-adjustments__detail footer button,
.mon-operational-applied button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 34px;
  border: 1px solid color-mix(in srgb, var(--pulso-accent) 38%, var(--pulso-border));
  border-radius: 12px;
  background: var(--pulso-accent);
  color: #fff;
  font-weight: 850;
  cursor: pointer;
}

.mon-operational-adjustments__detail footer button.mon-operational-apply-button {
  border-color: color-mix(in srgb, var(--op-complete) 38%, var(--op-complete-border));
