  opacity: 0.52;
}

.mon-operational-adjustments__detail footer small {
  color: var(--pulso-text-muted);
  font-size: 0.78rem;
  line-height: 1.35;
}

.mon-operational-adjustments__applied {
  grid-column: 1 / -1;
