  grid-template-rows: auto minmax(0, 1fr);
  overflow: hidden;
}

.mon-operational-adjustments__applied > header {
  display: grid;
  grid-template-columns: minmax(154px, 0.24fr) minmax(0, 1fr);
  align-items: center;
}

.mon-operational-adjustments__applied > header .mon-operational-adjustments__panel-tools {
  flex-wrap: nowrap;
}

.mon-operational-adjustments__applied > header .mon-operational-adjustments__search {
