  max-width: none;
}

.mon-operational-adjustments__applied > header .mon-operational-applied-audit {
  flex: 0 0 auto;
  flex-wrap: nowrap;
}

.mon-operational-adjustments__applied-list {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.mon-operational-applied {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 9px;
  min-width: 0;
  min-height: 88px;
  padding: 10px;
