  border-radius: 14px;
  background: #ffffff;
}

.mon-operational-applied.is-active {
  border-color: color-mix(in srgb, var(--pulso-success-border) 74%, var(--pulso-border));
  background: color-mix(in srgb, var(--pulso-success-bg) 66%, #fff);
}

.mon-operational-applied.is-reverted {
  opacity: 0.72;
}

.mon-operational-applied__state {
  min-width: 68px;
  min-height: 26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid color-mix(in srgb, currentColor 28%, transparent);
  border-radius: 999px;
  color: var(--pulso-success-fg);
  font-size: 0.64rem;
  font-weight: 930;
  letter-spacing: 0.045em;
  line-height: 1;
  padding: 4px 8px;
  text-transform: uppercase;
  white-space: nowrap;
}

.mon-operational-applied.is-reverted .mon-operational-applied__state {
  color: var(--pulso-text-muted);
}

.mon-operational-applied__ledger {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(0, 0.9fr) minmax(0, 1fr);
  align-items: center;
  gap: 8px;
}

.mon-operational-applied__cell {
  min-width: 0;
  display: grid;
  align-content: center;
  gap: 1px;
}

.mon-operational-applied__cell + .mon-operational-applied__cell {
  border-left: 1px solid color-mix(in srgb, var(--pulso-border-strong) 34%, transparent);
  padding-left: 8px;
}

.mon-operational-applied__cell small {
  color: var(--pulso-text-faint);
  font-size: 0.55rem;
  font-weight: 920;
  letter-spacing: 0.05em;
  line-height: 1;
  text-transform: uppercase;
}

.mon-operational-applied__cell strong {
  color: var(--pulso-text);
  font-size: 0.78rem;
  font-weight: 930;
  line-height: 1.15;
}

.mon-operational-applied__cell em {
  color: var(--pulso-text-muted);
  font-size: 0.68rem;
  font-weight: 760;
  line-height: 1.15;
}

.mon-operational-applied small {
  color: var(--pulso-text-faint);
  font-size: 0.68rem;
  font-weight: 760;
}

.mon-operational-applied button {
  flex: 0 0 auto;
  min-height: 30px;
  padding: 0 10px;
  border-color: color-mix(in srgb, var(--pulso-border-strong) 60%, var(--pulso-border));
  background: #ffffff;
  color: var(--pulso-accent);
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.06);
}

.mon-operational-applied__tag {
  flex: 0 0 auto;
  padding: 6px 9px;
  border-radius: 999px;
  background: var(--pulso-muted-surface);
  color: var(--pulso-text-muted);
  font-size: 0.72rem;
  font-weight: 860;
}

.mon-operational-adjustments__empty {
  display: grid;
  justify-items: center;
  gap: 7px;
  padding: 42px 18px;
  border: 1px dashed var(--pulso-border-strong);
  border-radius: 18px;
  background: color-mix(in srgb, var(--pulso-muted-surface) 84%, #fff);
  color: var(--pulso-text-muted);
  text-align: center;
}

.mon-operational-adjustments__empty.is-compact {
  margin: 12px;
  padding: 26px 14px;
