  font-size: 0.75rem;
  font-style: normal;
}

.mon-operational-adjustments__empty button {
  min-height: 30px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid color-mix(in srgb, var(--pulso-accent) 24%, var(--pulso-border));
  border-radius: 999px;
  background: #fff;
  color: var(--pulso-accent);
  cursor: pointer;
  font: inherit;
  font-size: 0.76rem;
  font-weight: 850;
  padding: 0 12px;
}

.mon-operational-adjustments__empty button:hover,
.mon-operational-adjustments__empty button:focus-visible {
  border-color: color-mix(in srgb, var(--pulso-accent) 42%, var(--pulso-border));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--pulso-accent) 10%, transparent);
  outline: none;
}

@media (max-width: 1500px) {
  .mon-operational-adjustments {
    gap: 9px;
    height: clamp(610px, calc(100dvh - 208px), 960px);
  }

  .mon-operational-adjustments__header {
    align-items: center;
    gap: 12px;
    border-radius: 14px;
    padding: 9px 13px;
  }

  .mon-operational-adjustments__header > div:first-child {
    gap: 2px;
  }

  .mon-operational-adjustments__header span,
  .mon-operational-adjustments__suggestions header span,
  .mon-operational-adjustments__applied header span,
  .mon-operational-adjustments__detail header span {
    font-size: 0.66rem;
    letter-spacing: 0.06em;
  }

  .mon-operational-adjustments__header strong {
    font-size: 1.08rem;
  }

  .mon-operational-adjustments__header p {
    font-size: 0.74rem;
    line-height: 1.25;
  }

  .mon-operational-adjustments__status {
    gap: 6px;
  }

  .mon-operational-adjustments__status span,
  .mon-operational-reset-button {
    min-height: 28px;
    padding: 5px 9px;
    font-size: 0.7rem;
  }

  .mon-operational-adjustments__metrics {
    gap: 8px;
  }

  .mon-operational-adjustments__metrics span {
    min-height: 46px;
    border-radius: 12px;
    padding: 7px 10px;
