    flex-basis: 176px;
    min-width: 150px;
  }

  .mon-operational-applied-segment {
    min-height: 28px;
  }

  .mon-operational-applied-segment button {
    min-height: 20px;
    padding: 3px 6px;
  }

  .mon-operational-applied-audit span {
    min-width: 62px;
    min-height: 24px;
    padding: 4px 7px;
  }

  .mon-operational-applied {
