  }

  .mon-operational-applied-audit {
    justify-content: flex-start;
  }
}

button.mon-territorial-ump-audit-scrim {
  appearance: none;
  position: fixed;
  z-index: 96;
  inset: 72px 0 0 0;
  display: block;
  border: 0;
  border-radius: 0;
  background: rgba(15, 23, 42, 0.08) !important;
  backdrop-filter: blur(1px);
  cursor: default;
  padding: 0;
}

.mon-territorial-ump-audit {
  position: fixed;
  z-index: 97;
  top: 84px;
  right: 16px;
  bottom: 16px;
  width: min(560px, calc(100vw - 340px));
  max-width: calc(100vw - 32px);
  min-width: 420px;
  min-height: 0;
  display: grid;
  grid-template-rows: auto auto minmax(180px, 0.92fr) minmax(210px, 1.08fr);
  gap: 11px;
  border: 1px solid color-mix(in srgb, var(--pulso-border-strong) 76%, #fff);
  border-radius: 16px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.96)),
    #fff;
  box-shadow: var(--pulso-shadow-popover);
  overflow: hidden;
  padding: 12px;
  animation: mon-territorial-ump-audit-in var(--motion-dur-panel) var(--motion-ease-drawer);
}

@keyframes mon-territorial-ump-audit-in {
  from {
    opacity: 0;
    transform: translate3d(18px, 0, 0) scale(0.985);
  }
  to {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
  }
}

.mon-territorial-ump-audit-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: 8px;
}

.mon-territorial-ump-audit-header > div {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.mon-territorial-ump-audit-header span,
.mon-territorial-ump-audit-header label span,
.mon-territorial-ump-audit-section > header span,
.mon-territorial-ump-audit-note-field span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-weight: 880;
  letter-spacing: 0;
  text-transform: uppercase;
}

.mon-territorial-ump-audit-header strong {
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 18px;
  font-weight: 920;
  line-height: 1.08;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-territorial-ump-audit-header em {
