  font-size: 21px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.mon-actor-grid {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 12px;
}

.mon-actor-grid--phone-quota {
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  align-items: start;
}

.mon-phone-quota-lane-workbench {
  gap: 10px;
}

.mon-phone-quota-lane-board {
  --phone-quota-lane-accent: #0a6b8f;
  min-width: 0;
  display: grid;
  gap: 10px;
}

.mon-phone-quota-lane-brief {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(330px, 0.72fr) minmax(520px, 1fr);
  align-items: stretch;
  gap: 10px;
  border: 1px solid color-mix(in srgb, var(--phone-quota-lane-accent) 20%, var(--pulso-border));
  border-radius: 11px;
  background:
    linear-gradient(135deg, color-mix(in srgb, #e7f8fb 54%, #fff), rgba(255, 255, 255, 0.96) 54%),
    var(--pulso-surface);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.82);
  padding: 10px;
}

.mon-phone-quota-lane-brief > div:first-child {
  min-width: 0;
  display: grid;
  align-content: center;
  gap: 3px;
}

.mon-phone-quota-lane-brief span,
.mon-phone-quota-lane-kpis em,
.mon-phone-quota-lane-title span,
.mon-phone-quota-lane-metrics em,
.mon-phone-quota-lane-spark em {
  color: var(--pulso-text-soft);
  font-size: 9.5px;
  font-style: normal;
  font-weight: 850;
  letter-spacing: 0.05em;
  line-height: 1.1;
  text-transform: uppercase;
}

.mon-phone-quota-lane-brief > div:first-child > span {
  color: var(--phone-quota-lane-accent);
}

.mon-phone-quota-lane-brief strong {
  color: var(--pulso-text);
  font-size: 20px;
  font-weight: 880;
  line-height: 1.04;
}

.mon-phone-quota-lane-brief p {
  max-width: 76ch;
  margin: 0;
  color: var(--pulso-text-soft);
  font-size: 12px;
  font-weight: 700;
  line-height: 1.32;
}

.mon-phone-quota-lane-kpis {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 7px;
}

.mon-phone-quota-lane-kpis span {
  --phone-quota-lane-kpi: var(--phone-quota-lane-accent);
  min-width: 0;
  display: grid;
  align-content: center;
  gap: 2px;
  border: 1px solid color-mix(in srgb, var(--phone-quota-lane-kpi) 16%, var(--pulso-border));
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.8);
  padding: 7px 8px;
}

.mon-phone-quota-lane-kpis span.is-ready {
  --phone-quota-lane-kpi: var(--pulso-success-fg);
}

.mon-phone-quota-lane-kpis span.is-warning {
  --phone-quota-lane-kpi: var(--pulso-warn-accent);
}

.mon-phone-quota-lane-kpis em,
.mon-phone-quota-lane-kpis strong {
  min-width: 0;
  overflow: hidden;
  line-height: 1.05;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-phone-quota-lane-kpis strong {
  color: var(--pulso-text);
  font-size: 16px;
  font-weight: 880;
}

.mon-phone-quota-lane-list {
  min-width: 0;
  display: grid;
  gap: 7px;
}

.mon-phone-quota-lane {
  --phone-quota-lane-row: var(--phone-quota-lane-accent);
  --phone-quota-lane-pct: 0%;
  --phone-quota-lane-target: 0%;
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(190px, 0.5fr) minmax(310px, 1fr) minmax(230px, 0.58fr) minmax(150px, 0.36fr);
  align-items: stretch;
  gap: 8px;
  border: 1px solid color-mix(in srgb, var(--phone-quota-lane-row) 18%, var(--pulso-border));
  border-radius: 10px;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--phone-quota-lane-row) 6%, #fff), rgba(255, 255, 255, 0.94)),
    var(--pulso-surface);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.78);
  padding: 8px;
}

.mon-phone-quota-lane.is-complete {
  --phone-quota-lane-row: var(--pulso-success-fg);
}

.mon-phone-quota-lane.is-steady {
  --phone-quota-lane-row: #b59b18;
}

.mon-phone-quota-lane.is-low {
  --phone-quota-lane-row: var(--pulso-warn-accent);
}

.mon-phone-quota-lane-title,
.mon-phone-quota-lane-progress,
.mon-phone-quota-lane-metrics,
.mon-phone-quota-lane-spark {
  min-width: 0;
}

.mon-phone-quota-lane-title {
  display: grid;
  align-content: center;
  gap: 3px;
}

.mon-phone-quota-lane-title strong,
.mon-phone-quota-lane-title em,
.mon-phone-quota-lane-progress strong,
.mon-phone-quota-lane-progress span,
.mon-phone-quota-lane-progress small,
.mon-phone-quota-lane-metrics em,
.mon-phone-quota-lane-metrics strong,
.mon-phone-quota-lane-spark strong,
.mon-phone-quota-lane-spark small {
  min-width: 0;
  overflow: hidden;
  line-height: 1.08;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-phone-quota-lane-title strong {
  color: var(--pulso-text);
  font-size: 14px;
  font-weight: 870;
}

.mon-phone-quota-lane-title em {
  justify-self: start;
  border: 1px solid color-mix(in srgb, var(--phone-quota-lane-row) 24%, var(--pulso-border));
  border-radius: var(--pulso-radius-chip);
  background: color-mix(in srgb, var(--phone-quota-lane-row) 7%, #fff);
  color: color-mix(in srgb, var(--phone-quota-lane-row) 76%, var(--pulso-text));
  font-size: 10px;
  font-style: normal;
  font-weight: 820;
  padding: 4px 7px;
}

.mon-phone-quota-lane-progress {
  display: grid;
  align-content: center;
  gap: 5px;
}

.mon-phone-quota-lane-progress > div {
  min-width: 0;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.mon-phone-quota-lane-progress strong {
  color: var(--pulso-text);
  font-size: 17px;
  font-weight: 880;
}

.mon-phone-quota-lane-progress span,
.mon-phone-quota-lane-progress small,
.mon-phone-quota-lane-spark small {
  color: var(--pulso-text-soft);
  font-size: 10.5px;
  font-weight: 740;
}

.mon-phone-quota-lane-progress > i {
  position: relative;
  height: 12px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--phone-quota-lane-row) 12%, var(--pulso-border));
  border-radius: var(--pulso-radius-chip);
  background: color-mix(in srgb, var(--pulso-border) 70%, #fff 30%);
  box-shadow: inset 0 1px 1px rgba(15, 23, 42, 0.08);
}

.mon-phone-quota-lane-progress > i::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: var(--phone-quota-lane-pct);
  border-radius: inherit;
  background: linear-gradient(90deg, color-mix(in srgb, var(--phone-quota-lane-row) 82%, #fff 18%), var(--phone-quota-lane-row));
}

.mon-phone-quota-lane-progress > i b {
  position: absolute;
  top: -3px;
  left: var(--phone-quota-lane-target);
  width: 2px;
  height: 18px;
  border-radius: var(--pulso-radius-chip);
  background: rgba(15, 23, 42, 0.46);
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.66);
}

.mon-phone-quota-lane-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 5px;
}

.mon-phone-quota-lane-metrics span {
  --phone-quota-lane-metric: var(--phone-quota-lane-row);
  min-width: 0;
  display: grid;
  align-content: center;
  gap: 2px;
  border: 1px solid color-mix(in srgb, var(--phone-quota-lane-metric) 14%, var(--pulso-border));
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.72);
  padding: 6px 7px;
}

.mon-phone-quota-lane-metrics span.is-ready {
  --phone-quota-lane-metric: var(--pulso-success-fg);
}

.mon-phone-quota-lane-metrics span.is-warning {
  --phone-quota-lane-metric: var(--pulso-warn-accent);
}

.mon-phone-quota-lane-metrics strong {
  color: var(--pulso-text);
  font-size: 14px;
  font-weight: 870;
}

.mon-phone-quota-lane-spark {
  display: grid;
  align-content: center;
  gap: 4px;
  border: 1px solid color-mix(in srgb, var(--phone-quota-lane-row) 12%, var(--pulso-border));
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.68);
  padding: 6px 7px;
}

.mon-phone-quota-lane-spark span {
  min-width: 0;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 6px;
}

.mon-phone-quota-lane-spark strong {
  color: var(--pulso-text);
  font-size: 11px;
  font-weight: 830;
}

.mon-phone-quota-lane-spark > div {
  min-width: 0;
  min-height: 22px;
  display: flex;
  align-items: end;
  gap: 3px;
}

.mon-phone-quota-lane-spark > div i {
  flex: 1 1 0;
  min-width: 5px;
  height: var(--phone-quota-lane-day);
  min-height: 4px;
  border-radius: 4px 4px 2px 2px;
  background: var(--phone-quota-lane-row);
}

.mon-phone-quota-lane-spark > div em {
  align-self: center;
  width: 100%;
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-weight: 760;
  text-align: center;
}

.mon-actor-card {
  --actor-accent: var(--pulso-module-monitoring);
  --actor-accent-soft: var(--pulso-module-monitoring-soft);
  --actor-accent-shadow: rgba(15, 23, 42, 0.1);
  --actor-dial: 0deg;
  --actor-complete: 0%;
  --actor-partial: 0%;
  --actor-refusal: 0%;
  --actor-target: 0%;
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(250px, 0.3fr) minmax(560px, 1fr);
  grid-template-areas:
    "actor-head actor-chart"
    "actor-body actor-chart"
    "actor-mechanisms actor-mechanisms";
  align-content: start;
  gap: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--actor-accent) 24%, var(--pulso-border));
  border-radius: 12px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--actor-accent-soft) 30%, #fff 70%), rgba(255, 255, 255, 0.96) 42%),
    var(--pulso-surface);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.82),
    0 10px 24px rgba(15, 23, 42, 0.06);
  padding: 12px;
}

.mon-actor-card.is-phone-quota {
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas:
    "actor-head"
    "actor-body"
    "actor-chart";
  gap: 9px;
}

.mon-actor-card.is-phone-quota > .mon-advance-daily-mini {
  min-height: 0;
}

.mon-actor-card.is-phone-quota > .mon-phone-quota-series-note {
  grid-area: actor-chart;
}

.mon-actor-card.is-phone-quota .mon-actor-card-head strong {
  font-size: 16px;
  white-space: normal;
}

.mon-actor-card.is-phone-quota .mon-actor-radar {
  min-height: 180px;
}

.mon-actor-card.is-phone-quota .mon-actor-pipeline .is-partial {
  background: #0a6b8f;
}

.mon-actor-card.is-phone-quota .mon-actor-pipeline .is-refusal {
  display: none;
}

.mon-phone-quota-series-note {
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: start;
  gap: 8px;
  border: 1px solid color-mix(in srgb, #0a6b8f 20%, var(--pulso-border));
  border-radius: 10px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.94), color-mix(in srgb, #e7f8fb 54%, #fff));
  color: var(--pulso-text);
  padding: 9px 10px;
}

.mon-phone-quota-series-note svg {
  margin-top: 1px;
  color: #0a6b8f;
}

.mon-phone-quota-series-note div {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.mon-phone-quota-series-note strong,
.mon-phone-quota-series-note span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.mon-phone-quota-series-note strong {
  font-size: 12px;
  font-weight: 820;
  color: #0a3246;
}

.mon-phone-quota-series-note span {
  font-size: 11px;
  font-weight: 650;
  line-height: 1.35;
  color: var(--pulso-text-soft);
}

.mon-actor-card > .mon-actor-card-head {
  grid-area: actor-head;
}

.mon-actor-card > .mon-actor-card-body {
  grid-area: actor-body;
}

.mon-actor-card > .mon-advance-daily-mini {
  grid-area: actor-chart;
  align-self: start;
}

.mon-actor-card > .mon-actor-mechanisms {
  grid-area: actor-mechanisms;
}

.mon-actor-card.is-complete {
  --actor-accent: var(--pulso-accent-green);
  --actor-accent-soft: rgba(22, 163, 74, 0.12);
  --actor-accent-shadow: rgba(22, 163, 74, 0.16);
}

.mon-actor-card.is-steady {
  --actor-accent: #b59b18;
  --actor-accent-soft: rgba(181, 155, 24, 0.13);
  --actor-accent-shadow: rgba(181, 155, 24, 0.15);
}

.mon-actor-card.is-low {
  --actor-accent: #b83255;
  --actor-accent-soft: rgba(184, 50, 85, 0.12);
  --actor-accent-shadow: rgba(184, 50, 85, 0.14);
}

.mon-actor-card.is-muted {
  --actor-accent: var(--pulso-accent-cyan);
  --actor-accent-soft: rgba(14, 165, 183, 0.11);
}

.mon-actor-card-head {
  min-width: 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.mon-actor-card-head > div {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.mon-actor-card-head span {
  color: var(--pulso-text-soft);
  font-size: 9.5px;
  font-weight: 820;
  line-height: 1.1;
  text-transform: uppercase;
}

.mon-actor-card-head strong {
  color: var(--pulso-text);
  font-size: 17px;
  font-weight: 840;
  line-height: 1.15;
}

.mon-actor-card-head em {
  flex: 0 0 auto;
  max-width: 160px;
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid color-mix(in srgb, var(--actor-accent) 34%, var(--pulso-border));
  border-radius: var(--pulso-radius-chip);
  background: color-mix(in srgb, #fff 82%, var(--actor-accent-soft) 18%);
  color: var(--actor-accent);
  font-size: 10px;
  font-style: normal;
  font-weight: 820;
  line-height: 1.1;
  padding: 3px 8px;
  text-align: center;
}

.mon-actor-card-body {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 8px;
  align-items: start;
}

.mon-actor-radar {
  min-width: 0;
  display: grid;
  gap: 8px;
  align-content: center;
  border: 1px solid color-mix(in srgb, var(--actor-accent) 18%, var(--pulso-border));
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.68);
  padding: 10px;
}

.mon-actor-dial {
  width: 104px;
  aspect-ratio: 1;
  justify-self: center;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background:
    radial-gradient(circle at center, #fff 0 59%, transparent 60%),
    conic-gradient(
      color-mix(in srgb, var(--actor-accent) 80%, #fff 20%) 0deg,
      var(--actor-accent) var(--actor-dial),
      var(--pulso-surface-3) 0
    );
  box-shadow:
    inset 0 0 0 1px var(--pulso-border),
    0 12px 26px rgba(15, 23, 42, 0.08),
    0 0 0 4px color-mix(in srgb, var(--actor-accent-soft) 42%, transparent);
}

.mon-actor-dial > * {
  grid-area: 1 / 1;
}

.mon-actor-dial strong {
  color: var(--pulso-text);
  font-size: 21px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.mon-actor-dial span {
  align-self: end;
  margin-bottom: 25px;
  color: var(--pulso-text-soft);
  font-size: 8.5px;
  font-weight: 820;
  text-transform: uppercase;
}

.mon-actor-pipeline-wrap {
  position: relative;
  min-width: 0;
}

.mon-actor-pipeline-wrap.has-target {
  padding-top: 14px;
}

.mon-actor-pipeline {
  height: 13px;
  display: flex;
  border: 1px solid var(--pulso-border);
  border-radius: var(--pulso-radius-chip);
  background: var(--pulso-surface-3);
  overflow: hidden;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.78),
    0 1px 2px rgba(15, 23, 42, 0.05);
}

.mon-actor-target {
  --actor-target-border: #5b6f8f;
  --actor-target-line: rgba(15, 23, 42, 0.48);
  position: absolute;
  z-index: 3;
  top: 4px;
  left: var(--actor-target);
  width: 12px;
  height: 9px;
  transform: translateX(-50%);
  pointer-events: none;
}

.mon-actor-target.is-reached {
  --actor-target-border: #6d5f86;
}

.mon-actor-target.is-open {
  --actor-target-border: #5b6f8f;
}

.mon-actor-target::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  width: 6px;
  height: 6px;
  border: 1px solid var(--actor-target-border);
  border-radius: 2px;
  background: #243044;
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.78),
    0 1px 3px rgba(15, 23, 42, 0.14);
  transform: translateX(-50%) rotate(45deg);
}

.mon-actor-target::after {
  content: "";
  position: absolute;
  top: 7px;
  left: 50%;
  width: 1px;
  height: 20px;
  border-radius: var(--pulso-radius-chip);
  background: var(--actor-target-line);
  box-shadow:
    -1px 0 0 rgba(255, 255, 255, 0.32),
    1px 0 0 rgba(255, 255, 255, 0.24);
  transform: translateX(-50%);
}

.mon-actor-pipeline span {
  display: block;
  height: 100%;
}

.mon-actor-pipeline .is-complete {
  width: var(--actor-complete);
  background: linear-gradient(
    90deg,
    #116b43,
    #168a55 54%,
    #20a96b
  );
  box-shadow: inset -1px 0 0 rgba(255, 255, 255, 0.32);
}

.mon-actor-pipeline .is-partial {
  width: max(0%, calc(var(--actor-partial) - var(--actor-complete)));
  background: var(--pulso-warn-accent);
}

.mon-actor-pipeline .is-refusal {
  width: max(0%, calc(var(--actor-refusal) - var(--actor-partial)));
  background: var(--pulso-module-monitoring);
}

.mon-actor-pipeline .is-pending {
  flex: 1 1 auto;
  background: color-mix(in srgb, var(--pulso-border) 68%, #fff 32%);
}

.mon-actor-radar p {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin: 0;
  color: var(--pulso-text-soft);
  font-size: 10.5px;
  line-height: 1.2;
}

.mon-actor-radar p strong {
  color: var(--pulso-text);
  font-size: 11px;
}

.mon-actor-flow {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.mon-actor-flow-node {
  min-width: 0;
  display: grid;
  gap: 5px;
  border: 1px solid var(--pulso-border);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.74);
  padding: 10px;
}

.mon-actor-flow-node.is-target {
  border-color: color-mix(in srgb, var(--pulso-warn-border) 70%, var(--pulso-border));
}

.mon-actor-flow-node.is-ready {
  border-color: color-mix(in srgb, var(--pulso-success-border) 66%, var(--pulso-border));
}

.mon-actor-flow-node.is-warning {
  border-color: color-mix(in srgb, var(--pulso-module-monitoring-border) 70%, var(--pulso-border));
}

.mon-actor-flow-node em {
  color: var(--pulso-text-soft);
  font-size: 9px;
  font-style: normal;
  font-weight: 820;
  line-height: 1.1;
  text-transform: uppercase;
}

.mon-actor-flow-node strong {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 19px;
  font-weight: 860;
  line-height: 1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-actor-mechanisms {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: start;
  gap: 8px;
  border-top: 1px solid color-mix(in srgb, var(--pulso-border) 78%, transparent);
