.mon-help-text {
  margin: 0;
  color: var(--pulso-text-soft);
  font-size: 12px;
  line-height: 1.5;
}

.mon-segmented {
  display: inline-flex;
  gap: 4px;
  padding: 3px;
  border: 1px solid var(--pulso-border);
  border-radius: 8px;
  background: var(--pulso-surface);
}

.mon-segmented button {
  min-height: 28px;
  border-color: transparent;
  background: transparent;
  color: var(--pulso-text-soft);
}

.mon-segmented button.is-active {
  border-color: var(--pulso-border);
  background: white;
  color: var(--pulso-text);
}

.mon-manual {
  margin-top: 10px;
}

.mon-manual h4 {
  margin: 0 0 6px;
  color: var(--pulso-text);
  font-size: 13px;
}

.mon-manual ol {
  margin: 0;
  padding-left: 18px;
  color: var(--pulso-text-soft);
  font-size: 12px;
  line-height: 1.5;
}

.mon-manual li + li {
  margin-top: 4px;
}

.mon-chip-block,
.mon-goals {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 12px;
}

.mon-model-panel .mon-goals {
  max-height: 220px;
  overflow: auto;
  padding-right: 2px;
}

.mon-chip-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  max-height: 92px;
  overflow: auto;
  padding: 2px;
}

.mon-chip-list button {
  min-height: 26px;
  padding: 4px 8px;
  font-size: 11px;
  color: var(--pulso-text-soft);
}

.mon-chip-list button.is-active {
  color: var(--pulso-primary);
  border-color: var(--pulso-primary-border);
  background: var(--pulso-primary-soft);
}

.mon-goals-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}

.mon-goal-row {
  display: grid;
  grid-template-columns: minmax(130px, 1fr) minmax(120px, 1fr) 96px 34px;
  gap: 6px;
  align-items: end;
}

.mon-goal-row--head {
  align-items: center;
  margin-top: 2px;
}

.mon-goal-row--head span {
  padding-inline: 2px;
}

.mon-goal-row button {
  min-width: 34px;
  padding: 0;
}

.mon-kpi-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(130px, 1fr));
  gap: 8px;
}

.mon-kpi {
  --kpi-accent: var(--pulso-border-strong);
  border: 1px solid var(--pulso-border);
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.88), rgba(247, 250, 253, 0.9)),
    var(--pulso-surface);
  padding: 9px 10px;
  min-height: 72px;
  display: grid;
  grid-template-rows: auto auto auto;
  gap: 6px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.74);
}

.mon-kpi.is-ready {
  --kpi-accent: var(--pulso-success-fg);
  border-color: color-mix(in srgb, var(--pulso-success-border) 42%, var(--pulso-border) 58%);
}

.mon-kpi.is-warning {
  --kpi-accent: var(--pulso-warn-accent);
  border-color: color-mix(in srgb, var(--pulso-warn-border) 58%, var(--pulso-border) 42%);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.9), color-mix(in srgb, var(--pulso-warn-bg) 26%, #fff 74%)),
    var(--pulso-surface);
}

.mon-kpi span {
  display: block;
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-weight: 750;
  text-transform: uppercase;
}

.mon-kpi strong {
  display: block;
  margin-top: 4px;
  color: var(--pulso-text);
  font-size: 18px;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.mon-kpi-track {
  height: 6px;
  overflow: hidden;
  border-radius: var(--pulso-radius-chip);
  background: color-mix(in srgb, var(--pulso-surface-3) 86%, #fff 14%);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--pulso-border) 76%, transparent);
}

.mon-kpi-track i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--kpi-accent);
}

.mon-kpi-signal {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  align-items: end;
  gap: 4px;
  height: 12px;
}

.mon-kpi-signal i {
  display: block;
  border-radius: var(--pulso-radius-chip);
  background: color-mix(in srgb, var(--kpi-accent) 42%, var(--pulso-border-strong) 58%);
}

.mon-kpi-signal i:nth-child(1) {
  height: 5px;
}

.mon-kpi-signal i:nth-child(2) {
  height: 9px;
}

.mon-kpi-signal i:nth-child(3) {
  height: 12px;
}

.mon-kpi em {
  display: block;
  color: var(--pulso-text-soft);
  font-size: 9.5px;
  font-style: normal;
  font-weight: 700;
  line-height: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.mon-dashboard-panel .pulso-panel {
  padding: 14px 16px;
}

.mon-dashboard-panel .pulso-panel-header {
  margin-bottom: 12px;
  align-items: center;
}

.mon-gs-report-panel {
  display: grid;
  gap: 10px;
  padding: 12px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.94), rgba(248, 250, 253, 0.92)),
    var(--pulso-surface);
}

.mon-gs-report-panel > .pulso-panel-header {
  margin-bottom: 0;
  align-items: center;
}

.mon-gs-report-meta {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  flex-wrap: wrap;
}

.mon-gs-report-meta span {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  border: 1px solid var(--pulso-border);
  border-radius: 999px;
  padding: 0 9px;
  background: color-mix(in srgb, var(--pulso-surface) 90%, white 10%);
  color: var(--pulso-text-soft);
  font-size: 10.5px;
  font-weight: 760;
  white-space: nowrap;
}

.mon-gs-report-brief {
  --mon-report-accent: var(--pulso-module-monitoring);
  --mon-report-accent-soft: var(--pulso-module-monitoring-soft);
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 0.52fr);
  gap: 10px;
  align-items: stretch;
  border: 1px solid color-mix(in srgb, var(--mon-report-accent) 24%, var(--pulso-border));
  border-radius: 10px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--mon-report-accent-soft) 44%, #fff 56%), rgba(255, 255, 255, 0.94) 42%),
    #fff;
  padding: 10px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.76);
}

.mon-gs-report-brief.is-phone {
  --mon-report-accent: var(--pulso-accent-cyan);
  --mon-report-accent-soft: rgba(14, 165, 183, 0.12);
}

.mon-gs-report-brief.is-survey {
  --mon-report-accent: var(--pulso-accent-green);
  --mon-report-accent-soft: rgba(22, 163, 74, 0.12);
}

.mon-gs-report-brief.is-risk {
  --mon-report-accent: var(--pulso-danger-fg);
  --mon-report-accent-soft: var(--pulso-danger-bg);
}

.mon-gs-report-brief.is-report {
  --mon-report-accent: var(--pulso-primary);
  --mon-report-accent-soft: var(--pulso-primary-soft);
}

.mon-gs-report-brief-main {
  min-width: 0;
  display: grid;
  align-content: center;
  gap: 4px;
}

.mon-gs-report-chip {
  justify-self: start;
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1px solid color-mix(in srgb, var(--mon-report-accent) 32%, var(--pulso-border));
  border-radius: var(--pulso-radius-chip);
  background: color-mix(in srgb, #fff 80%, var(--mon-report-accent-soft) 20%);
  color: var(--mon-report-accent);
  font-size: 10.5px;
  font-weight: 780;
  padding: 2px 8px;
}

.mon-gs-report-brief-main strong {
  color: var(--pulso-text);
  font-size: 16px;
  line-height: 1.18;
}

.mon-gs-report-brief-main p {
  max-width: 760px;
  margin: 0;
  color: var(--pulso-text-soft);
  font-size: 12px;
  line-height: 1.38;
}

.mon-gs-report-brief-stats {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
}

.mon-gs-report-brief-stats span {
  min-width: 0;
  display: grid;
  gap: 3px;
  align-content: center;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 78%, transparent);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.74);
  padding: 8px;
}

.mon-gs-report-brief-stats em {
  color: var(--pulso-text-soft);
  font-size: 9.5px;
  font-style: normal;
  font-weight: 820;
  line-height: 1.1;
  text-transform: uppercase;
}

.mon-gs-report-brief-stats strong {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 16px;
  font-weight: 840;
  line-height: 1.05;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-gs-report-tabs {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 5px;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 82%, transparent);
  border-radius: 10px;
  padding: 5px;
  background: color-mix(in srgb, var(--pulso-surface-2) 68%, white 32%);
}

.mon-gs-report-tabs button {
  min-width: 0;
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--pulso-text-soft);
  font-size: 11.5px;
  font-weight: 760;
  cursor: pointer;
  transition:
    background-color 140ms ease,
    border-color 140ms ease,
    color 140ms ease,
    transform 120ms ease;
}

.mon-gs-report-tabs button:hover {
  background: color-mix(in srgb, white 82%, var(--pulso-primary-soft) 18%);
  color: var(--pulso-text);
}

.mon-gs-report-tabs button.is-active {
  border-color: var(--pulso-primary-border);
  background: white;
  color: var(--pulso-primary);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.78),
    0 1px 2px rgba(15, 23, 42, 0.07);
}

@media (hover: hover) and (pointer: fine) {
  .mon-gs-report-tabs button:hover {
    transform: translateY(-1px);
  }
}

.mon-gs-report-tabs span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-gs-report-body {
  display: grid;
  gap: 10px;
  min-width: 0;
}

.mon-gs-report-body > p {
  margin: 0;
  color: var(--pulso-text-soft);
  font-size: 12px;
  line-height: 1.35;
}

.mon-gs-report-blocks {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 520px), 1fr));
  gap: 10px;
  min-width: 0;
}

.mon-gs-report-block {
  --mon-block-accent: var(--pulso-module-monitoring);
  --mon-block-soft: var(--pulso-module-monitoring-soft);
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  border: 1px solid color-mix(in srgb, var(--mon-block-accent) 18%, var(--pulso-border));
  border-radius: 10px;
  padding: 9px;
  background:
    linear-gradient(180deg, color-mix(in srgb, white 88%, var(--mon-block-soft) 12%), white);
  box-shadow: var(--pulso-shadow-low);
}

.mon-gs-report-block.is-phone {
  --mon-block-accent: var(--pulso-accent-cyan);
  --mon-block-soft: rgba(14, 165, 183, 0.1);
}

.mon-gs-report-block.is-survey {
  --mon-block-accent: var(--pulso-accent-green);
  --mon-block-soft: rgba(22, 163, 74, 0.1);
}

.mon-gs-report-block.is-risk {
  --mon-block-accent: var(--pulso-danger-fg);
  --mon-block-soft: var(--pulso-danger-bg);
}

.mon-gs-report-block.is-trend {
  --mon-block-accent: var(--pulso-primary);
  --mon-block-soft: var(--pulso-primary-soft);
}

.mon-gs-report-block header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.mon-gs-report-block header > div {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.mon-gs-report-block header strong {
  min-width: 0;
  color: var(--pulso-text);
  overflow: hidden;
  font-size: 12.5px;
  font-weight: 780;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-gs-report-block header small {
  color: var(--pulso-text-soft);
  font-size: 10.5px;
  font-weight: 650;
  line-height: 1.2;
}

.mon-gs-block-metric {
  flex: 0 0 auto;
  min-width: 72px;
  display: grid;
  gap: 1px;
  justify-items: end;
  border: 1px solid color-mix(in srgb, var(--mon-block-accent) 28%, var(--pulso-border));
  border-radius: 8px;
  background: color-mix(in srgb, #fff 74%, var(--mon-block-soft) 26%);
  padding: 5px 7px;
}

.mon-gs-block-metric em {
  max-width: 92px;
  overflow: hidden;
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-style: normal;
  font-weight: 760;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-gs-block-metric strong {
  color: var(--mon-block-accent);
  font-size: 13px;
  font-weight: 840;
  line-height: 1.05;
}

.mon-gs-report-table-wrap {
  max-height: 282px;
  overflow: auto;
  scrollbar-gutter: stable;
  border: 1px solid var(--pulso-border);
  border-radius: 8px;
  background: white;
}

.mon-gs-report-table {
  width: 100%;
  min-width: 620px;
  border-collapse: collapse;
  font-size: 11px;
}

.mon-gs-report-table th,
.mon-gs-report-table td {
  border-bottom: 1px solid color-mix(in srgb, var(--pulso-border) 82%, transparent);
  padding: 6px 8px;
  text-align: left;
  vertical-align: top;
}

.mon-gs-report-table th {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.96), color-mix(in srgb, var(--pulso-surface) 92%, white 8%));
  color: var(--pulso-text-soft);
  font-size: 9px;
  font-weight: 820;
  text-transform: uppercase;
  white-space: nowrap;
}

.mon-gs-report-table tbody tr:nth-child(even) {
  background: color-mix(in srgb, var(--pulso-surface-2) 42%, #fff 58%);
}

.mon-gs-report-table td {
  max-width: 180px;
  color: var(--pulso-text);
  overflow-wrap: anywhere;
}

.mon-gs-report-table th:first-child,
.mon-gs-report-table td:first-child {
  min-width: 96px;
}

.mon-gs-report-block em {
  color: var(--pulso-text-soft);
  font-size: 11px;
  font-style: normal;
}

.mon-stage--quality {
  gap: 12px;
  min-height: 0;
}

.mon-quality-command {
  --quality-command-accent: var(--pulso-primary);
  display: grid;
  gap: 10px;
  border: 1px solid color-mix(in srgb, var(--quality-command-accent) 14%, var(--pulso-border));
  border-radius: 14px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 253, 0.94)),
    var(--pulso-surface);
  padding: 12px;
  box-shadow: var(--pulso-shadow-low);
}

.mon-quality-command.is-conciliacion {
  --quality-command-accent: var(--pulso-accent-cyan);
}

.mon-quality-command.is-reglas {
  --quality-command-accent: var(--pulso-warn-accent);
}

.mon-quality-command.is-equipo {
  --quality-command-accent: var(--pulso-accent-green);
}

.mon-quality-command-head {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(300px, 0.92fr) minmax(0, 1fr);
  gap: 12px;
  align-items: stretch;
}

.mon-quality-command-title {
  min-width: 0;
  display: grid;
  align-content: center;
  gap: 5px;
  border: 1px solid color-mix(in srgb, var(--quality-command-accent) 16%, var(--pulso-border));
  border-radius: 12px;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--quality-command-accent) 8%, transparent), transparent 62%),
    color-mix(in srgb, var(--pulso-surface-2) 58%, #fff 42%);
  padding: 11px 12px;
}

.mon-quality-command-title span {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-weight: 820;
  letter-spacing: 0.08em;
  line-height: 1.08;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.mon-quality-command-title strong {
  min-width: 0;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 18px;
  font-weight: 870;
  letter-spacing: 0;
  line-height: 1.08;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-quality-command-title svg {
  flex: 0 0 auto;
  color: var(--quality-command-accent);
}

.mon-quality-command-title p {
  max-width: 760px;
  margin: 0;
  color: var(--pulso-text-soft);
  font-size: 12px;
  font-weight: 620;
  line-height: 1.34;
}

.mon-quality-command-metrics {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.mon-quality-command-metrics > span {
  --quality-metric-accent: var(--pulso-primary);
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  column-gap: 7px;
  row-gap: 3px;
  align-content: center;
  border: 1px solid color-mix(in srgb, var(--quality-metric-accent) 20%, var(--pulso-border));
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.82);
  padding: 9px;
}

.mon-quality-command-metrics > span.is-warning {
  --quality-metric-accent: var(--pulso-warn-accent);
}

.mon-quality-command-metrics > span.is-ready {
  --quality-metric-accent: var(--pulso-success-fg);
}

.mon-quality-command-metrics > span.is-base {
  --quality-metric-accent: var(--pulso-primary);
}

.mon-quality-command-metrics svg {
  grid-row: 1 / span 3;
  align-self: start;
  color: var(--quality-metric-accent);
  margin-top: 1px;
}

.mon-quality-command-metrics em,
.mon-quality-command-metrics small {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text-soft);
  font-size: 9.5px;
  font-style: normal;
  font-weight: 820;
  letter-spacing: 0.06em;
  line-height: 1.05;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.mon-quality-command-metrics strong {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 18px;
  font-weight: 870;
  line-height: 1.02;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-quality-command-metrics small {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0;
  line-height: 1.15;
  text-transform: none;
  white-space: normal;
}

.mon-quality-mode-tabs {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  border: 1px solid var(--pulso-border);
  border-radius: 12px;
  background: color-mix(in srgb, var(--pulso-surface-2) 62%, #fff 38%);
  padding: 5px;
}

.mon-quality-mode-tabs button {
  min-width: 0;
  min-height: 46px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  border: 1px solid transparent;
  border-radius: 9px;
  background: transparent;
  color: var(--pulso-text-soft);
  cursor: pointer;
  padding: 7px 9px;
  text-align: left;
  transition: background 160ms ease, border-color 160ms ease, box-shadow 160ms ease, color 160ms ease;
}

.mon-quality-mode-tabs button:hover,
.mon-quality-mode-tabs button.is-active {
  border-color: color-mix(in srgb, var(--quality-command-accent) 22%, var(--pulso-border));
  background: rgba(255, 255, 255, 0.86);
  box-shadow: var(--pulso-shadow-low);
  color: var(--pulso-text);
}

.mon-quality-mode-tabs button.is-active {
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--quality-command-accent) 18%, transparent),
    var(--pulso-shadow-low);
}

.mon-quality-mode-tabs svg {
  color: var(--quality-command-accent);
}

.mon-quality-mode-tabs span {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.mon-quality-mode-tabs strong,
.mon-quality-mode-tabs small,
