  min-width: 0;
  display: grid;
  grid-template-columns: 104px minmax(0, 1.2fr) minmax(190px, 0.55fr) minmax(0, 1fr);
  gap: 8px;
  align-items: stretch;
  border: 1px solid color-mix(in srgb, var(--trace-accent) 20%, var(--pulso-border));
  border-radius: 9px;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--trace-soft) 46%, transparent) 0 3px, transparent 3px),
    #fff;
  padding: 8px 9px 8px 11px;
  box-shadow: var(--pulso-shadow-low);
}

.mon-reconciliation-row.is-ok {
  --trace-accent: var(--pulso-success-fg);
  --trace-soft: var(--pulso-success-bg);
}

.mon-reconciliation-row.is-warning {
  --trace-accent: var(--pulso-warn-accent);
  --trace-soft: var(--pulso-warn-bg);
}

.mon-reconciliation-row.is-danger {
  --trace-accent: var(--pulso-danger-fg);
  --trace-soft: var(--pulso-danger-bg);
}

.mon-reconciliation-status,
.mon-reconciliation-key,
.mon-reconciliation-side {
  min-width: 0;
  border: 1px solid color-mix(in srgb, var(--trace-accent) 16%, var(--pulso-border));
  border-radius: 8px;
  background: color-mix(in srgb, #fff 84%, var(--trace-soft) 16%);
  padding: 7px;
}

.mon-reconciliation-status {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  color: var(--trace-accent);
  font-size: 11px;
  font-weight: 820;
  line-height: 1.1;
  text-align: center;
}

.mon-reconciliation-status svg,
.mon-reconciliation-key svg {
  flex: 0 0 auto;
}

.mon-reconciliation-side {
  display: grid;
  align-content: start;
  gap: 4px;
}

.mon-reconciliation-side em {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text-soft);
  font-size: 9.5px;
  font-style: normal;
  font-weight: 820;
  letter-spacing: 0.06em;
  line-height: 1.1;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.mon-reconciliation-side strong,
.mon-reconciliation-key strong {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 12px;
  font-weight: 820;
  line-height: 1.16;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-reconciliation-side span,
.mon-reconciliation-key span {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text-soft);
  font-size: 10.5px;
  font-weight: 650;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-reconciliation-side code {
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--pulso-border);
  border-radius: var(--pulso-radius-chip);
  background: rgba(255, 255, 255, 0.72);
  color: var(--pulso-text);
  font-family: inherit;
  font-size: 10.5px;
  font-weight: 740;
  line-height: 1.2;
  padding: 4px 6px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-reconciliation-key {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-content: center;
  align-items: center;
  column-gap: 7px;
  row-gap: 3px;
  color: var(--trace-accent);
}

.mon-reconciliation-key span {
  grid-column: 2;
}

.mon-reconciliation-more {
  border: 1px dashed color-mix(in srgb, var(--reconciliation-accent) 28%, var(--pulso-border));
  border-radius: 9px;
  background: color-mix(in srgb, var(--reconciliation-soft) 44%, white 56%);
  color: var(--pulso-text-soft);
  font-size: 11.5px;
  font-weight: 720;
  padding: 9px 10px;
  text-align: center;
}

.mon-report-cell {
  min-width: 0;
}

.mon-report-cell--number {
  font-variant-numeric: tabular-nums;
  font-weight: 720;
}

.mon-report-cell--state {
  min-height: 22px;
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--pulso-border);
  border-radius: var(--pulso-radius-chip);
  background: var(--pulso-surface-2);
  color: var(--pulso-text-soft);
  font-size: 10.5px;
  font-weight: 760;
  line-height: 1.15;
  padding: 2px 7px;
  white-space: nowrap;
}

.mon-report-cell--state.is-good {
  border-color: var(--pulso-success-border);
  background: var(--pulso-success-bg);
  color: var(--pulso-success-fg);
}

.mon-report-cell--state.is-warn {
  border-color: var(--pulso-warn-border);
  background: var(--pulso-warn-bg);
  color: var(--pulso-warn-fg);
}

.mon-report-cell--state.is-risk {
  border-color: var(--pulso-danger-border);
  background: var(--pulso-danger-bg);
  color: var(--pulso-danger-fg);
}

.mon-report-cell--percent {
  min-width: 86px;
  display: grid;
  grid-template-columns: minmax(36px, 1fr) auto;
  gap: 7px;
  align-items: center;
  color: var(--pulso-text);
  font-variant-numeric: tabular-nums;
  font-weight: 760;
}

.mon-report-cell--percent i {
  height: 6px;
  border-radius: var(--pulso-radius-chip);
  background:
    linear-gradient(90deg, var(--mon-block-accent) var(--mon-report-pct), color-mix(in srgb, var(--pulso-border) 72%, #fff 28%) var(--mon-report-pct));
  box-shadow: inset 0 0 0 1px rgba(15, 23, 42, 0.04);
}

.mon-report-cell--percent.is-swept i {
  background:
    linear-gradient(90deg, var(--pulso-module-monitoring) var(--mon-report-pct), color-mix(in srgb, var(--pulso-border) 72%, #fff 28%) var(--mon-report-pct));
}

.mon-report-cell--percent.is-unswept i {
  background:
    linear-gradient(90deg, #94a3b8 var(--mon-report-pct), color-mix(in srgb, var(--pulso-border) 72%, #fff 28%) var(--mon-report-pct));
}

.mon-report-cell--percent.is-total i {
  background:
    linear-gradient(90deg, #64748b var(--mon-report-pct), color-mix(in srgb, var(--pulso-border) 72%, #fff 28%) var(--mon-report-pct));
}

.mon-gs-report-overflow {
  color: var(--pulso-text-soft);
  font-size: 10.5px;
  line-height: 1.3;
}

.mon-phone-panel {
  --phone-accent: var(--pulso-module-monitoring);
  --phone-accent-soft: var(--pulso-module-monitoring-soft);
  display: grid;
  gap: 10px;
  padding: 12px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(248, 250, 253, 0.94)),
    var(--pulso-surface);
}

.mon-phone-panel > .pulso-panel-header {
  margin-bottom: 0;
  align-items: center;
}

.mon-phone-meta {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  flex-wrap: wrap;
}

.mon-phone-meta span {
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--pulso-border);
  border-radius: var(--pulso-radius-chip);
  background: color-mix(in srgb, var(--pulso-surface) 92%, white 8%);
  color: var(--pulso-text-soft);
  font-size: 10.5px;
  font-weight: 760;
  padding: 0 9px;
}

.mon-phone-hero {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(260px, 0.75fr) minmax(0, 1.25fr);
  gap: 10px;
  align-items: stretch;
  border: 1px solid color-mix(in srgb, var(--phone-accent) 22%, var(--pulso-border));
  border-radius: 12px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--phone-accent-soft) 48%, #fff 52%), rgba(255, 255, 255, 0.95) 48%),
    #fff;
  padding: 10px;
}

.mon-phone-hero-copy {
  min-width: 0;
  display: grid;
  align-content: center;
  gap: 4px;
}

.mon-phone-hero-copy span {
  width: fit-content;
  border: 1px solid color-mix(in srgb, var(--phone-accent) 28%, var(--pulso-border));
  border-radius: var(--pulso-radius-chip);
  background: rgba(255, 255, 255, 0.76);
  color: var(--phone-accent);
  font-size: 10px;
  font-weight: 820;
  line-height: 1;
  padding: 4px 8px;
  text-transform: uppercase;
}

.mon-phone-hero-copy strong {
  color: var(--pulso-text);
  font-size: 20px;
  font-weight: 860;
  line-height: 1.1;
}

.mon-phone-hero-copy p {
  margin: 0;
  max-width: 560px;
  color: var(--pulso-text-soft);
  font-size: 12px;
  line-height: 1.35;
}

.mon-phone-kpis {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 7px;
}

.mon-phone-metric {
  --metric-accent: var(--pulso-border-strong);
  min-width: 0;
  display: grid;
  gap: 3px;
  align-content: center;
  border: 1px solid color-mix(in srgb, var(--metric-accent) 24%, var(--pulso-border));
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.76);
  padding: 8px;
}

.mon-phone-metric.is-ready,
.mon-phone-metric.is-success {
  --metric-accent: var(--pulso-success-fg);
}

.mon-phone-metric.is-swept {
  --metric-accent: var(--phone-accent);
}

.mon-phone-metric.is-warning {
  --metric-accent: var(--pulso-warn-accent);
}

.mon-phone-metric.is-risk {
  --metric-accent: var(--pulso-danger-fg);
}

.mon-phone-metric em {
  color: var(--pulso-text-soft);
  font-size: 9.5px;
  font-style: normal;
  font-weight: 820;
  line-height: 1.1;
  text-transform: uppercase;
}

.mon-phone-metric strong {
  color: var(--pulso-text);
  font-size: 21px;
  font-weight: 880;
  line-height: 1;
}

.mon-phone-metric small {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-weight: 680;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-phone-tabbody,
.mon-phone-layout {
  min-width: 0;
  display: grid;
  gap: 10px;
}

.mon-phone-layout--alerts {
  grid-template-columns: minmax(0, 1fr);
  grid-auto-flow: row;
  align-items: stretch;
}

.mon-phone-layout--alerts > * {
  min-width: 0;
  grid-column: 1 / -1;
}

.mon-phone-layout--responsables {
  align-content: start;
  gap: 12px;
}

.mon-phone-overview-grid {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(320px, 0.82fr);
  align-items: start;
  align-content: start;
  gap: 10px;
}

.mon-phone-supervision {
  grid-template-columns: minmax(0, 1.08fr) minmax(320px, 0.72fr);
  align-items: start;
}

.mon-phone-pending-grid {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 0.82fr) minmax(0, 1.18fr);
  align-items: start;
  gap: 10px;
}

.mon-phone-ops-card--pending .mon-phone-bars {
  grid-template-columns: 1fr;
  gap: 5px;
}

.mon-phone-ops-card--pending .mon-phone-bar-row,
.mon-phone-ops-card--pending .mon-phone-unassigned {
  padding: 7px 8px;
}

.mon-phone-pending-panel,
.mon-phone-pending-list {
  min-width: 0;
  display: grid;
  gap: 7px;
}

.mon-phone-pending-summary {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 5px;
}

.mon-phone-pending-summary span {
  min-width: 0;
  display: grid;
  gap: 2px;
  border: 1px solid color-mix(in srgb, var(--pulso-warn-accent) 22%, var(--pulso-border));
  border-radius: 9px;
  background: color-mix(in srgb, var(--pulso-warn-accent) 6%, #fff);
  padding: 7px 8px;
}

.mon-phone-pending-summary strong {
  color: var(--pulso-text);
  font-size: 16px;
  font-weight: 880;
  line-height: 1;
}

.mon-phone-pending-summary em {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text-soft);
  font-size: 9.8px;
  font-style: normal;
  font-weight: 760;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-phone-pending-list {
  max-height: 470px;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding-right: 3px;
  scrollbar-gutter: stable;
}

.mon-phone-ops-card--pending-workbench {
  --phone-editorial-ink: #243044;
  --phone-mustard-ink: #5f3a07;
  --phone-mustard-text: #7a4f12;
  --phone-mustard-muted: #8b7657;
  gap: 10px;
}

.mon-phone-pending-workbench-summary {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
}

.mon-phone-pending-workbench-summary span {
  --pending-summary-accent: var(--phone-accent);
  min-width: 0;
  display: grid;
  gap: 3px;
  border: 1px solid color-mix(in srgb, var(--pending-summary-accent) 18%, var(--pulso-border));
  border-radius: 10px;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--pending-summary-accent) 6%, transparent), transparent 54%),
    rgba(255, 255, 255, 0.84);
  padding: 8px;
}

.mon-phone-pending-workbench-summary span.is-warning {
  --pending-summary-accent: var(--pulso-warn-accent);
}

.mon-phone-pending-workbench-summary span.is-ok {
  --pending-summary-accent: var(--pulso-success-fg);
}

.mon-phone-pending-workbench-summary strong {
  color: var(--phone-mustard-ink);
  font-size: 18px;
  font-weight: 880;
  line-height: 1;
}

.mon-phone-pending-workbench-summary em {
  min-width: 0;
  color: var(--phone-mustard-muted);
  font-size: 10px;
  font-style: normal;
  font-weight: 780;
  line-height: 1.1;
  white-space: normal;
}

.mon-phone-attempt-scale {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 6px;
}

.mon-phone-attempt-scale span,
.mon-phone-attempt-inline-counts span {
  --attempt-bucket-color: #f7d99a;
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 5px;
  border: 1px solid color-mix(in srgb, var(--attempt-bucket-color) 34%, var(--pulso-border));
  border-radius: 8px;
  background: color-mix(in srgb, var(--attempt-bucket-color) 8%, #fff);
  padding: 5px 6px;
}

.mon-phone-attempt-scale span::before {
  width: 8px;
  height: 8px;
  content: "";
  border-radius: 999px;
  background: var(--attempt-bucket-color);
}

.mon-phone-attempt-scale strong,
.mon-phone-attempt-scale em,
.mon-phone-attempt-inline-counts em,
.mon-phone-attempt-inline-counts strong {
  min-width: 0;
  overflow: hidden;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-phone-attempt-scale strong {
  color: var(--phone-mustard-text);
  font-size: 9.8px;
  font-weight: 820;
}

.mon-phone-attempt-scale em {
  justify-self: end;
  color: var(--phone-mustard-ink);
  font-size: 10.5px;
  font-style: normal;
  font-weight: 880;
}

.mon-phone-pending-workbench-list {
  min-width: 0;
  display: grid;
  gap: 8px;
  max-height: none;
  overflow: visible;
  padding-right: 0;
}

.mon-phone-pending-person {
  --pending-person-accent: var(--pulso-warn-accent);
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(220px, 0.34fr) minmax(0, 0.66fr);
  grid-template-areas:
    "head head"
    "pending attempts"
    "cases cases"
    "foot foot";
  gap: 9px 12px;
  border: 1px solid color-mix(in srgb, var(--pending-person-accent) 18%, var(--pulso-border));
  border-radius: 12px;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--pending-person-accent) 5%, transparent), transparent 58%),
    rgba(255, 255, 255, 0.84);
  padding: 10px;
}

.mon-phone-pending-person.is-clear {
  --pending-person-accent: #8a96a8;
}

.mon-phone-pending-person > header {
  grid-area: head;
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: 10px;
}

.mon-phone-pending-person > header > div {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.mon-phone-pending-person > header strong {
  min-width: 0;
  overflow: visible;
  color: var(--phone-editorial-ink);
  font-size: 14px;
  font-weight: 880;
  line-height: 1.1;
  text-overflow: clip;
  white-space: normal;
}

.mon-phone-pending-person > header em {
  color: var(--phone-mustard-muted);
  font-size: 10.5px;
  font-style: normal;
  font-weight: 760;
  line-height: 1.15;
}

.mon-phone-pending-person > header > span {
  min-width: 96px;
  display: grid;
  justify-items: end;
  gap: 2px;
  border: 1px solid color-mix(in srgb, var(--pending-person-accent) 24%, var(--pulso-border));
  border-radius: 9px;
  background: color-mix(in srgb, var(--pending-person-accent) 7%, #fff);
  padding: 6px 8px;
}

.mon-phone-pending-person > header > span.is-ok {
  --pending-person-accent: #8a96a8;
}

.mon-phone-pending-person > header > span strong {
  color: var(--phone-mustard-ink);
  font-size: 17px;
  line-height: 1;
}

.mon-phone-pending-person > header > span em {
  color: var(--phone-mustard-text);
  font-size: 9.5px;
  font-weight: 800;
  line-height: 1.08;
  text-align: right;
}

.mon-phone-pending-track-block,
.mon-phone-attempt-track-block {
  min-width: 0;
  display: grid;
  align-content: start;
  gap: 6px;
}

.mon-phone-pending-track-block {
  grid-area: pending;
}

.mon-phone-attempt-track-block {
  grid-area: attempts;
}

.mon-phone-track-labels {
  min-width: 0;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.mon-phone-track-labels span {
  min-width: 0;
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
}

.mon-phone-track-labels span:last-child {
  justify-content: flex-end;
}

.mon-phone-track-labels strong {
  color: var(--phone-mustard-ink);
  font-size: 12px;
  font-weight: 880;
  line-height: 1;
}

.mon-phone-track-labels em {
  min-width: 0;
  color: var(--phone-mustard-muted);
  font-size: 9.8px;
  font-style: normal;
  font-weight: 740;
  line-height: 1.1;
  white-space: nowrap;
}

.mon-phone-pending-track,
.mon-phone-attempt-track {
  min-width: 0;
  height: 18px;
  display: flex;
  gap: 0;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 88%, #fff);
  border-radius: 8px;
  background: #edf1f6;
  box-shadow:
    inset 0 1px 2px rgba(15, 23, 42, 0.08),
    0 1px 0 rgba(255, 255, 255, 0.86);
  padding: 3px;
}

.mon-phone-pending-track i,
.mon-phone-attempt-track i {
  flex: 0 0 var(--phone-segment);
  min-width: 5px;
  display: block;
  border-radius: 0;
  cursor: help;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.32),
    inset -1px 0 0 rgba(255, 255, 255, 0.58);
  transition:
    filter 140ms ease,
    box-shadow 140ms ease;
}

.mon-phone-pending-track i:first-child,
.mon-phone-attempt-track i:first-child {
  border-top-left-radius: 5px;
  border-bottom-left-radius: 5px;
}

.mon-phone-pending-track i:last-child,
.mon-phone-attempt-track i:last-child {
  border-top-right-radius: 5px;
  border-bottom-right-radius: 5px;
}

.mon-phone-pending-track i:hover,
.mon-phone-pending-track i:focus-visible,
.mon-phone-attempt-track i:hover,
.mon-phone-attempt-track i:focus-visible {
  filter: saturate(1.08) brightness(1.04);
  outline: none;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.34),
    inset -1px 0 0 rgba(255, 255, 255, 0.58),
    inset 0 0 0 1px rgba(255, 255, 255, 0.68),
    0 0 0 1px rgba(15, 23, 42, 0.14);
}

.mon-phone-pending-track i.is-swept {
  background: #cbd5e1;
}

.mon-phone-pending-track i.is-pending {
  background: linear-gradient(180deg, #f1bd49, #c9840c);
}

.mon-phone-pending-track i.is-empty,
.mon-phone-attempt-track i.is-empty {
  background: #d8e0ea;
}

.mon-phone-attempt-scale span.is-bucket-1,
.mon-phone-attempt-inline-counts span.is-bucket-1,
.mon-phone-attempt-track i.is-bucket-1 {
  --attempt-bucket-color: #f8e5bd;
  background-color: var(--attempt-bucket-color);
}

