}

.mon-phone-attempt-legend span.is-bucket-3,
.mon-phone-attempt-bucket-grid span.is-bucket-3 {
  --attempt-bucket-color: #c9840c;
}

.mon-phone-attempt-legend span.is-bucket-4,
.mon-phone-attempt-bucket-grid span.is-bucket-4 {
  --attempt-bucket-color: #a86308;
}

.mon-phone-attempt-legend span.is-bucket-5,
.mon-phone-attempt-bucket-grid span.is-bucket-5 {
  --attempt-bucket-color: #117e64;
}

.mon-phone-attempt-legend span.is-bucket-6,
.mon-phone-attempt-bucket-grid span.is-bucket-6 {
  --attempt-bucket-color: #0f8a61;
}

.mon-phone-attempt-legend i {
