  background: var(--attempt-bucket-color);
}

.mon-phone-attempt-legend strong,
.mon-phone-attempt-legend em {
  min-width: 0;
  overflow: hidden;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-phone-attempt-legend strong {
  color: var(--pulso-text);
  font-size: 10.5px;
  font-weight: 850;
}

.mon-phone-attempt-legend em {
