.mon-phone-attempt-buckets i.is-bucket-1 {
  background: #f3c266;
}

.mon-phone-attempt-buckets i.is-bucket-2 {
  background: #e3a42b;
}

.mon-phone-attempt-buckets i.is-bucket-3 {
  background: #c9840c;
}

.mon-phone-attempt-buckets i.is-bucket-4 {
  background: #a86308;
}

.mon-phone-attempt-buckets i.is-bucket-5 {
  background: #117e64;
}

.mon-phone-attempt-buckets i.is-bucket-6 {
  background: #0f8a61;
}

.mon-phone-attempt-bucket-grid {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 5px;
}

.mon-phone-attempt-bucket-grid span {
  --attempt-bucket-color: #cbd5e1;
  min-width: 0;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 5px;
  border: 1px solid color-mix(in srgb, var(--attempt-bucket-color) 22%, var(--pulso-border));
