  background: color-mix(in srgb, var(--attempt-bucket-color) 5%, #fff);
  padding: 5px 6px;
}

.mon-phone-attempt-bucket-grid em,
.mon-phone-attempt-bucket-grid strong {
  min-width: 0;
  overflow: hidden;
  line-height: 1.05;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-phone-attempt-bucket-grid em {
  color: var(--pulso-text-soft);
  font-size: 9.5px;
  font-style: normal;
  font-weight: 820;
}

.mon-phone-attempt-bucket-grid strong {
  color: var(--pulso-text);
  font-size: 12px;
  font-weight: 880;
}

.mon-phone-attempt-list footer {
  min-width: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.mon-phone-attempt-list footer span {
  min-height: 22px;
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--pulso-border);
  border-radius: var(--pulso-radius-chip);
  background: color-mix(in srgb, #fff 86%, var(--pulso-surface-2));
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-weight: 760;
  line-height: 1.1;
  padding: 3px 7px;
}

.mon-phone-attempt-list footer span.is-high {
  border-color: color-mix(in srgb, #0f8a61 22%, var(--pulso-border));
  background: color-mix(in srgb, #0f8a61 7%, #fff);
