}

.mon-phone-attempt-list footer span.is-medium {
  border-color: color-mix(in srgb, #b97611 24%, var(--pulso-border));
  background: color-mix(in srgb, #b97611 7%, #fff);
  color: #8a570a;
}

.mon-phone-attempt-list footer span.is-low {
