}

.mon-phone-status-owner-list {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.mon-phone-status-owner-stack {
  min-width: 0;
  height: 12px;
  display: flex;
  overflow: hidden;
  border-radius: var(--pulso-radius-chip);
  background: color-mix(in srgb, var(--pulso-border) 72%, #fff 28%);
  box-shadow: inset 0 0 0 1px rgba(15, 23, 42, 0.06);
}

.mon-phone-status-owner-stack i {
  flex: 0 0 var(--phone-status-owner-size);
  min-width: 5px;
  background: var(--phone-status-owner-color);
  box-shadow: inset -1px 0 0 rgba(255, 255, 255, 0.48);
}

.mon-phone-status-owner-list footer i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--phone-status-owner-color);
}

.mon-phone-storage-legend {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.mon-phone-status-legend {
  grid-template-columns: repeat(auto-fit, minmax(154px, 1fr));
  gap: 7px;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding-right: 3px;
  scrollbar-gutter: stable;
}

.mon-phone-storage-legend span {
  --storage-dot: var(--pulso-text-soft);
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  grid-template-areas:
    "dot label"
    "value value"
    "hint hint";
  align-content: start;
  gap: 3px 6px;
  border: 1px solid color-mix(in srgb, var(--storage-dot) 18%, var(--pulso-border));
  border-left: 3px solid var(--storage-dot);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.82);
  padding: 8px;
}

.mon-phone-status-legend span {
  border-color: color-mix(in srgb, var(--storage-dot) 28%, var(--pulso-border));
  border-left-color: var(--storage-dot);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--storage-dot) 8%, #fff), rgba(255, 255, 255, 0.88)),
    var(--pulso-surface);
}

.mon-phone-storage-legend span::before {
  content: "";
  grid-area: dot;
  width: 8px;
  height: 8px;
  align-self: center;
  border-radius: 50%;
  background: var(--storage-dot);
}

.mon-phone-storage-legend span.is-swept {
  --storage-dot: var(--phone-storage-swept);
}

.mon-phone-storage-legend span.is-unswept {
  --storage-dot: var(--phone-storage-unswept-strong);
}

.mon-phone-storage-legend span.is-total {
  --storage-dot: #94a3b8;
}

.mon-phone-storage-legend span.is-good {
  --storage-dot: #168a55;
}

.mon-phone-storage-legend span.is-warn {
  --storage-dot: #b97611;
}

.mon-phone-storage-legend span.is-risk {
  --storage-dot: #a61d4f;
}

.mon-phone-storage-legend span.is-unswept {
  --storage-dot: #64748b;
}

.mon-phone-storage-legend span.is-muted {
  --storage-dot: #5e7fa5;
}

.mon-phone-storage-legend em {
  grid-area: label;
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-style: normal;
  font-weight: 800;
  line-height: 1.12;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.mon-phone-storage-legend strong {
  grid-area: value;
  color: var(--pulso-text);
  font-size: 18px;
  font-weight: 860;
  line-height: 1.05;
}

.mon-phone-storage-legend small {
  grid-area: hint;
  color: var(--pulso-text-soft);
  font-size: 10.5px;
  font-weight: 680;
  line-height: 1.2;
}

.mon-phone-trend {
  --phone-trend-effective: #168a55;
  --phone-trend-partial: #c47a00;
  --phone-trend-refusal: #a61d4f;
  --phone-trend-cumulative: var(--pulso-text);
  min-width: 0;
  display: grid;
  gap: 14px;
  border: 1px solid color-mix(in srgb, var(--phone-trend-cumulative) 12%, var(--pulso-border));
  border-radius: 14px;
  background:
    radial-gradient(circle at 16% 0%, color-mix(in srgb, var(--phone-trend-effective) 10%, transparent), transparent 28%),
    radial-gradient(circle at 86% 0%, color-mix(in srgb, var(--phone-trend-partial) 9%, transparent), transparent 30%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 253, 0.96)),
    var(--pulso-surface);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.92),
    0 14px 30px rgba(15, 23, 42, 0.055);
  padding: 14px;
}

