  font-weight: 840;
  letter-spacing: 0.06em;
  line-height: 1.1;
  text-transform: uppercase;
}

.mon-phone-trend-head strong {
  color: var(--pulso-text);
  font-size: 16px;
  font-weight: 860;
  line-height: 1.1;
}

.mon-phone-trend-legend {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}

.mon-phone-trend-legend span {
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1px solid var(--pulso-border);
  border-radius: var(--pulso-radius-chip);
  background: rgba(255, 255, 255, 0.82);
  color: var(--pulso-text);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0;
  padding: 3px 8px;
  text-transform: none;
}

.mon-phone-trend-legend span::before {
  width: 18px;
  height: 3px;
  content: "";
  border-radius: var(--pulso-radius-chip);
  background: var(--phone-trend-effective);
}

.mon-phone-trend-legend span.is-partial::before {
