.mon-phone-trend-legend span.is-refusal::before {
  background: var(--phone-trend-refusal);
}

.mon-phone-trend-legend span.is-cumulative::before {
  background: var(--phone-trend-cumulative);
}

.mon-phone-trend-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.mon-phone-trend-metrics span {
  --trend-metric-accent: var(--phone-trend-cumulative);
