}

.mon-phone-trend-metrics span.is-best {
  --trend-metric-accent: var(--phone-trend-effective);
}

.mon-phone-trend-metrics span.is-last {
  --trend-metric-accent: var(--phone-trend-refusal);
}

.mon-phone-trend-metrics em {
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-style: normal;
  font-weight: 820;
  letter-spacing: 0.04em;
  line-height: 1.05;
  text-transform: uppercase;
}

.mon-phone-trend-metrics strong {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 14px;
  font-weight: 860;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-phone-trend-metrics small {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-weight: 680;
