  align-items: center;
  border: 1px solid var(--pulso-border);
  border-radius: var(--pulso-radius-chip);
  background: #fff;
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-weight: 760;
  letter-spacing: 0;
  padding: 2px 7px;
  text-transform: none;
}

.mon-phone-bar-row {
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
}

.mon-phone-bar-row > div {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.mon-phone-bar-row span,
.mon-phone-day strong,
.mon-phone-responsible strong {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 12px;
  font-weight: 820;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-phone-bar-row > div em,
.mon-phone-bar-row small {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-style: normal;
  font-weight: 720;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-phone-bar-row small {
  grid-column: 1 / -1;
}

.mon-phone-bar-row strong,
.mon-phone-day header span,
.mon-phone-responsible header em {
  color: var(--pulso-text);
  font-size: 13px;
  font-style: normal;
  font-weight: 860;
  line-height: 1;
}

.mon-phone-bar-row i,
.mon-phone-day > i {
  grid-column: 1 / -1;
  height: 7px;
  border-radius: var(--pulso-radius-chip);
  background:
    linear-gradient(90deg, var(--phone-row-accent) var(--phone-bar), color-mix(in srgb, var(--pulso-border) 72%, #fff 28%) var(--phone-bar));
}

.mon-phone-bar-row em {
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-style: normal;
  font-weight: 720;
}

.mon-phone-day header,
.mon-phone-responsible header {
  min-width: 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.mon-phone-responsible-title {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.mon-phone-responsible-title span {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-weight: 760;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-phone-responsible-meter {
  min-width: 0;
  height: 10px;
  overflow: hidden;
  display: flex;
  gap: 0;
  border-radius: var(--pulso-radius-chip);
  background: color-mix(in srgb, var(--pulso-border) 70%, #fff 30%);
  box-shadow:
    inset 0 0 0 1px rgba(15, 23, 42, 0.08),
    inset 0 1px 1px rgba(255, 255, 255, 0.58);
}

.mon-phone-responsible-meter span {
  min-width: 0;
  height: 100%;
  flex: 0 0 var(--phone-segment);
  border-radius: 0;
}

.mon-phone-responsible-meter span:first-child {
  border-radius: var(--pulso-radius-chip) 0 0 var(--pulso-radius-chip);
}

.mon-phone-responsible-meter span:last-child {
  border-radius: 0 var(--pulso-radius-chip) var(--pulso-radius-chip) 0;
}

.mon-phone-responsible-meter span.is-effective {
  background: linear-gradient(90deg, #0f8a61, #11a174);
}

.mon-phone-responsible-meter span.is-non-effective {
  background: linear-gradient(90deg, #b8325f, #cf5b80);
}

.mon-phone-responsible-meter span.is-pending {
  background: linear-gradient(90deg, #94a3b8, #cbd5e1);
}

.mon-phone-day footer,
.mon-phone-responsible-chips {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(116px, max-content));
  gap: 6px;
}

.mon-phone-day footer span,
.mon-phone-responsible-chips span {
  min-height: 22px;
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--pulso-border);
  border-radius: var(--pulso-radius-chip);
  background: var(--pulso-surface-2);
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-weight: 720;
  padding: 2px 7px;
}

.mon-phone-responsible-foot {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
}

.mon-phone-responsible-foot span {
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  column-gap: 5px;
  row-gap: 1px;
  border: 1px solid color-mix(in srgb, var(--phone-foot-accent) 18%, var(--pulso-border));
  border-radius: 8px;
  background: color-mix(in srgb, var(--phone-foot-accent) 5%, #fff);
  color: var(--pulso-text);
  padding: 7px 8px;
}

.mon-phone-responsible-foot span.is-effective {
  --phone-foot-accent: #0f8a61;
}

.mon-phone-responsible-foot span.is-non-effective {
  --phone-foot-accent: #b8325f;
}

.mon-phone-responsible-foot span.is-pending {
  --phone-foot-accent: #94a3b8;
}

.mon-phone-responsible-foot i {
  width: 7px;
  height: 7px;
  grid-row: 1 / span 2;
  border-radius: 999px;
  background: var(--phone-foot-accent);
}

.mon-phone-responsible-foot strong,
.mon-phone-responsible-foot em {
  min-width: 0;
  overflow: hidden;
  line-height: 1.05;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-phone-responsible-foot strong {
  font-size: 12px;
  font-weight: 860;
}

.mon-phone-responsible-foot em {
  color: var(--pulso-text-soft);
  font-size: 9.5px;
  font-style: normal;
  font-weight: 740;
}

/* Revamp Calidad + Teléfono: capa de exploración operativa */
.mon-quality-command-metrics {
  grid-template-columns: repeat(auto-fit, minmax(118px, 1fr));
}

.mon-quality-workspace.is-conciliacion {
  overflow-y: auto;
}

.mon-reconciliation-actor-head {
  grid-template-columns: minmax(280px, 1fr) minmax(360px, 0.72fr);
  align-items: start;
}

.mon-reconciliation-rule-actions {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 7px;
}

.mon-reconciliation-rule-actions button,
.mon-reconciliation-open-explorer,
.mon-reconciliation-case-rule button {
  min-height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid color-mix(in srgb, var(--rule-accent, var(--case-accent, var(--pulso-primary))) 22%, var(--pulso-border));
  border-radius: var(--pulso-radius-chip);
  background: color-mix(in srgb, #fff 86%, var(--pulso-surface-2));
  color: var(--pulso-text);
  cursor: pointer;
  font-size: 10.5px;
  font-weight: 820;
  line-height: 1;
  padding: 4px 8px;
  white-space: nowrap;
}

.mon-reconciliation-rule-actions button:hover,
.mon-reconciliation-open-explorer:hover,
.mon-reconciliation-case-rule button:hover {
  border-color: color-mix(in srgb, var(--rule-accent, var(--case-accent, var(--pulso-primary))) 40%, var(--pulso-border));
  box-shadow: var(--pulso-shadow-low);
}

.mon-reconciliation-decision-actions {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 7px;
  align-items: center;
}

.mon-reconciliation-decision-toggle {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 4px;
  border: 1px solid color-mix(in srgb, var(--case-accent) 18%, var(--pulso-border));
  border-radius: 10px;
  background: color-mix(in srgb, var(--pulso-surface-2) 68%, #fff 32%);
  padding: 4px;
}

.mon-reconciliation-decision-toggle button {
  min-width: 0;
  min-height: 30px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--pulso-text-soft);
  cursor: pointer;
  font-size: 11px;
  font-weight: 820;
  line-height: 1.08;
  padding: 5px 8px;
  text-align: center;
}

.mon-reconciliation-decision-toggle button.is-active {
  border-color: color-mix(in srgb, var(--case-accent) 28%, var(--pulso-border));
  background: #fff;
  color: var(--pulso-text);
  box-shadow: var(--pulso-shadow-low);
}

.mon-reconciliation-decision-toggle button.is-include.is-active {
  border-color: color-mix(in srgb, var(--pulso-success-fg) 34%, var(--pulso-border));
  color: var(--pulso-success-fg);
}

.mon-reconciliation-decision-toggle button.is-exclude.is-active {
  border-color: color-mix(in srgb, var(--pulso-danger-fg) 26%, var(--pulso-border));
  color: var(--pulso-danger-fg);
}

.mon-reconciliation-decision-toggle button:disabled,
.mon-reconciliation-open-explorer:disabled {
  cursor: not-allowed;
  opacity: 0.58;
}

.mon-reconciliation-mixed {
  grid-column: 1 / -1;
  justify-self: start;
  border: 1px dashed color-mix(in srgb, var(--case-accent) 26%, var(--pulso-border));
  border-radius: var(--pulso-radius-chip);
  background: color-mix(in srgb, var(--case-accent) 7%, #fff);
  color: var(--case-accent);
  font-size: 10px;
  font-weight: 820;
  letter-spacing: 0;
  padding: 4px 8px;
  text-transform: none;
}

.mon-reconciliation-open-explorer {
  justify-self: end;
}

.mon-reconciliation-case {
  grid-template-columns: minmax(0, 1fr) minmax(170px, 0.28fr);
}

.mon-reconciliation-case-rule {
  align-content: center;
}

.mon-reconciliation-case-rule button {
  justify-self: start;
  min-height: 24px;
  color: var(--case-accent);
  font-size: 10px;
  padding: 3px 7px;
}

.mon-phone-kpis {
  grid-template-columns: repeat(auto-fit, minmax(126px, 1fr));
}

.mon-phone-model-panel {
  --phone-accent: #0f766e;
  --phone-accent-soft: rgba(15, 118, 110, 0.11);
}

.mon-phone-model-hero {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(280px, 0.72fr) minmax(0, 1.28fr);
  gap: 10px;
  align-items: stretch;
  border: 1px solid color-mix(in srgb, var(--phone-accent) 22%, var(--pulso-border));
  border-radius: 12px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--phone-accent-soft) 58%, #fff 42%), rgba(255, 255, 255, 0.96) 48%),
    #fff;
  padding: 10px;
}

.mon-phone-model-grid {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(420px, 0.54fr);
  gap: 10px;
  align-items: start;
}

.mon-phone-model-primary,
.mon-phone-model-secondary {
  min-width: 0;
  display: grid;
  gap: 10px;
  align-content: start;
}

.mon-phone-model-primary > .mon-phone-storage {
  min-height: 0;
}

.mon-phone-model-rules,
.mon-phone-model-responsibles {
  min-width: 0;
  display: grid;
  gap: 8px;
  border: 1px solid color-mix(in srgb, var(--phone-accent) 16%, var(--pulso-border));
  border-radius: 12px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 253, 0.96)),
    var(--pulso-surface);
  padding: 10px;
}

.mon-phone-model-rules {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.mon-phone-model-rules article {
  --model-rule-accent: var(--pulso-primary);
  min-width: 0;
  display: grid;
  gap: 5px;
  border: 1px solid color-mix(in srgb, var(--model-rule-accent) 22%, var(--pulso-border));
  border-radius: 10px;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--model-rule-accent) 8%, transparent), transparent 58%),
    rgba(255, 255, 255, 0.86);
  padding: 9px;
}

.mon-phone-model-rules article.is-ready {
  --model-rule-accent: var(--pulso-success-fg);
}

.mon-phone-model-rules article.is-warning {
  --model-rule-accent: var(--pulso-warn-accent);
}

.mon-phone-model-rules article.is-base {
  --model-rule-accent: var(--phone-accent);
}

.mon-phone-model-rules span,
.mon-phone-model-responsibles article span,
.mon-phone-model-responsibles article em {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text-soft);
  font-size: 10.5px;
  font-style: normal;
  font-weight: 780;
  line-height: 1.12;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-phone-model-rules strong {
  color: var(--pulso-text);
  font-size: 21px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.mon-phone-model-rules p,
.mon-phone-model-responsibles article em {
  margin: 0;
  white-space: normal;
}

.mon-phone-model-responsibles > div {
  min-height: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 7px;
  max-height: 404px;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding-right: 3px;
  scrollbar-gutter: stable;
}

.mon-phone-model-responsibles article {
  min-width: 0;
  display: grid;
  gap: 4px;
  border: 1px solid color-mix(in srgb, var(--phone-accent) 13%, var(--pulso-border));
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.82);
  padding: 8px;
}

.mon-phone-model-responsibles article strong {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 12px;
  font-weight: 850;
  line-height: 1.12;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-phone-model-table,
.mon-phone-model-grid > .mon-phone-ops-insights {
  grid-column: 1 / -1;
}

.mon-phone-ops-insights {
  grid-template-columns: minmax(0, 1fr);
}

.mon-phone-ops-card--compare {
  grid-column: 1 / -1;
}

.mon-phone-compare-list {
  grid-template-columns: repeat(auto-fit, minmax(420px, 1fr));
  max-height: 440px;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding-right: 3px;
  scrollbar-gutter: stable;
}

.mon-phone-status-owner-list {
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  max-height: 420px;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding-right: 3px;
  scrollbar-gutter: stable;
}

.mon-phone-responsibles {
  overflow: visible;
}

.mon-phone-responsibles-head {
  position: sticky;
  z-index: 2;
  top: 0;
  backdrop-filter: blur(12px);
}

.mon-phone-supervision-shell {
  min-width: 0;
  display: grid;
  align-content: start;
  gap: 10px;
}

.mon-phone-supervision-hero {
  --supervision-accent: var(--pulso-success-fg);
  --supervision-soft: var(--pulso-success-bg);
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(220px, 0.62fr) minmax(0, 1.38fr);
  align-items: center;
  gap: 8px;
  border: 1px solid color-mix(in srgb, var(--supervision-accent) 22%, var(--pulso-border));
  border-radius: 10px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--supervision-soft) 52%, #fff 48%), rgba(255, 255, 255, 0.96) 52%),
    var(--pulso-surface);
  box-shadow: var(--pulso-shadow-low);
  padding: 8px 10px;
}

.mon-phone-supervision-hero.is-warning {
  --supervision-accent: var(--pulso-warn-accent);
  --supervision-soft: var(--pulso-warn-bg);
}

.mon-phone-supervision-hero.is-danger {
  --supervision-accent: var(--pulso-danger-fg);
  --supervision-soft: var(--pulso-danger-bg);
}

.mon-phone-supervision-hero.is-info {
  --supervision-accent: var(--pulso-accent-cyan);
  --supervision-soft: rgba(14, 165, 183, 0.1);
}

.mon-phone-supervision-lead {
  min-width: 0;
  display: grid;
  align-content: center;
  gap: 3px;
}

.mon-phone-supervision-lead > span {
  justify-self: start;
  min-height: 20px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border: 1px solid color-mix(in srgb, var(--supervision-accent) 28%, var(--pulso-border));
  border-radius: var(--pulso-radius-chip);
  background: rgba(255, 255, 255, 0.76);
  color: var(--supervision-accent);
  font-size: 9.5px;
  font-weight: 830;
  padding: 2px 7px;
  text-transform: uppercase;
}

.mon-phone-supervision-lead strong {
  color: var(--pulso-text);
  font-size: 14px;
  font-weight: 870;
  line-height: 1.08;
}

.mon-phone-supervision-lead p {
  max-width: 680px;
  margin: 0;
  color: var(--pulso-text-soft);
  font-size: 10.5px;
  line-height: 1.2;
}

.mon-phone-supervision-metrics {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
}

.mon-phone-supervision-metrics span {
  --supervision-metric-accent: var(--pulso-primary);
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: baseline;
  gap: 2px 7px;
  border: 1px solid color-mix(in srgb, var(--supervision-metric-accent) 18%, var(--pulso-border));
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.78);
  padding: 6px 7px;
}

.mon-phone-supervision-metrics span.is-ready {
  --supervision-metric-accent: var(--pulso-success-fg);
}

.mon-phone-supervision-metrics span.is-warning {
  --supervision-metric-accent: var(--pulso-warn-accent);
}

.mon-phone-supervision-metrics span.is-base {
  --supervision-metric-accent: var(--pulso-primary);
}

.mon-phone-supervision-metrics em,
.mon-phone-supervision-metrics small {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text-soft);
  font-size: 9px;
  font-style: normal;
  font-weight: 800;
  line-height: 1.1;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.mon-phone-supervision-metrics strong {
  grid-row: 1 / 3;
  grid-column: 2;
  color: var(--pulso-text);
  font-size: 16px;
  font-weight: 880;
  line-height: 1;
}

.mon-phone-supervision-metrics small {
  font-size: 9.5px;
  font-weight: 680;
  text-transform: none;
}

.mon-phone-supervision-grid {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(340px, 0.42fr);
  gap: 10px;
  align-items: start;
}

.mon-phone-supervision-primary,
.mon-phone-supervision-aside {
  min-width: 0;
  display: grid;
  gap: 10px;
}

.mon-phone-supervision-plan,
.mon-phone-supervision-source,
.mon-phone-supervision-priority,
.mon-phone-time-control {
  min-width: 0;
  display: grid;
  gap: 8px;
  border: 1px solid color-mix(in srgb, var(--phone-accent) 14%, var(--pulso-border));
  border-radius: 12px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 253, 0.96)),
    var(--pulso-surface);
  padding: 10px;
}

.mon-phone-time-control {
  --phone-time-accent: var(--pulso-success-fg);
  border-color: color-mix(in srgb, var(--phone-time-accent) 20%, var(--pulso-border));
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--phone-time-accent) 5%, #fff), rgba(248, 250, 253, 0.96)),
    var(--pulso-surface);
}

.mon-phone-time-control.is-warning {
  --phone-time-accent: var(--pulso-warn-accent);
}

.mon-phone-time-control.is-danger {
  --phone-time-accent: var(--pulso-danger-fg);
}

.mon-phone-time-track {
  min-width: 0;
  height: 14px;
  display: flex;
  gap: 3px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 86%, #fff);
  border-radius: var(--pulso-radius-chip);
  background: color-mix(in srgb, var(--pulso-border) 58%, #fff);
  padding: 3px;
}

.mon-phone-time-track span {
  min-width: 0;
  height: 100%;
  border-radius: inherit;
}

.mon-phone-time-track span.is-under2 {
  background: var(--pulso-danger-fg);
}

.mon-phone-time-track span.is-under5 {
  background: var(--pulso-warn-accent);
}

.mon-phone-time-track span.is-normal {
  background: var(--pulso-success-fg);
}

.mon-phone-time-buckets {
