  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
}

.mon-phone-time-buckets article {
  --phone-time-bucket: var(--pulso-success-fg);
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas:
    "label value"
    "hint hint";
  align-items: baseline;
  gap: 3px 7px;
  border: 1px solid color-mix(in srgb, var(--phone-time-bucket) 20%, var(--pulso-border));
  border-radius: 9px;
  background: color-mix(in srgb, var(--phone-time-bucket) 6%, #fff);
  padding: 8px;
