}

.mon-territorial-route-phase-toggle {
  box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.045);
}

.mon-territorial-route-phase-toggle button {
  transition:
    color var(--motion-dur-fast) var(--motion-ease-standard),
    background var(--motion-dur-fast) var(--motion-ease-standard),
    border-color var(--motion-dur-fast) var(--motion-ease-standard),
    box-shadow var(--motion-dur-fast) var(--motion-ease-standard);
}

.mon-territorial-route-phase-toggle button:not(.is-active):hover {
  background: rgba(255, 255, 255, 0.58);
  color: var(--pulso-text);
}

.mon-territorial-route-table-scroll,
.mon-territorial-asset-list,
.mon-territorial-history-list,
.mon-territorial-select-options,
.mon-territorial-district-grid,
.mon-territorial-enumerator-table,
.mon-territorial-enumerator-mini-table,
.mon-territorial-route-mini-table > div {
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--pulso-border-strong) 70%, #fff) transparent;
}

.mon-territorial-route-table-scroll::-webkit-scrollbar,
.mon-territorial-asset-list::-webkit-scrollbar,
.mon-territorial-history-list::-webkit-scrollbar,
.mon-territorial-select-options::-webkit-scrollbar,
.mon-territorial-district-grid::-webkit-scrollbar,
.mon-territorial-enumerator-table::-webkit-scrollbar,
.mon-territorial-enumerator-mini-table::-webkit-scrollbar,
.mon-territorial-route-mini-table > div::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}

.mon-territorial-route-table-scroll::-webkit-scrollbar-thumb,
.mon-territorial-asset-list::-webkit-scrollbar-thumb,
.mon-territorial-history-list::-webkit-scrollbar-thumb,
.mon-territorial-select-options::-webkit-scrollbar-thumb,
.mon-territorial-district-grid::-webkit-scrollbar-thumb,
.mon-territorial-enumerator-table::-webkit-scrollbar-thumb,
.mon-territorial-enumerator-mini-table::-webkit-scrollbar-thumb,
.mon-territorial-route-mini-table > div::-webkit-scrollbar-thumb {
  border: 2px solid transparent;
  border-radius: 999px;
  background: color-mix(in srgb, var(--pulso-border-strong) 70%, #fff);
  background-clip: padding-box;
}

.mon-territorial-route-table th,
.mon-territorial-route-mini-table th {
  background:
    linear-gradient(180deg, rgba(248, 250, 252, 0.98), rgba(241, 245, 249, 0.96)),
    var(--pulso-surface-2);
  box-shadow: inset 0 -1px 0 var(--pulso-border);
}

.mon-territorial-route-table tbody tr {
  transition:
    background var(--motion-dur-fast) var(--motion-ease-standard),
    box-shadow var(--motion-dur-fast) var(--motion-ease-standard);
}

.mon-territorial-route-table tbody tr:hover {
  background: color-mix(in srgb, var(--pulso-primary-soft) 19%, #fff);
}

.mon-territorial-route-table tbody tr.is-selected {
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--pulso-primary-soft) 42%, #fff) 0%, #fff 74%);
}

.mon-territorial-route-table tbody tr.is-selected td:first-child {
  box-shadow:
    inset 4px 0 0 var(--pulso-primary),
    inset 0 1px 0 rgba(255, 255, 255, 0.68);
}

.mon-territorial-route-map-viewport {
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.82),
    inset 0 0 0 1px rgba(255, 255, 255, 0.5);
}

.mon-territorial-route-map-viewport svg.is-lima-map.is-level-zone .mon-territorial-map-water {
  fill: transparent;
  pointer-events: none;
}

.mon-territorial-route-map-viewport .mon-territorial-map-canvas,
.mon-territorial-route-map-viewport svg.is-lima-map {
  will-change: transform;
}

.mon-territorial-map-tools {
  gap: 4px;
  border-color: color-mix(in srgb, var(--pulso-border-strong) 45%, #fff);
  border-radius: 16px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.94), rgba(248, 250, 252, 0.86)),
    rgba(255, 255, 255, 0.92);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.92),
    0 14px 34px rgba(15, 23, 42, 0.13);
  padding: 5px;
}

.mon-territorial-map-tools button {
  width: 28px;
  height: 28px;
  border-radius: 9px;
}

.mon-territorial-map-tools .mon-territorial-map-zoom-readout {
  min-width: 46px;
  color: var(--pulso-text);
  font-size: 10px;
  font-weight: 900;
}

@keyframes mon-territorial-popover-in {
  from {
    opacity: 0;
    transform: translateY(-2px) scale(0.985);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mon-territorial-source-command,
  .mon-territorial-route-command,
  .mon-territorial-source-card,
  .mon-territorial-route-table-card,
  .mon-territorial-route-map-card,
  .mon-territorial-route-context-card,
  .mon-territorial-source-search input,
	  .mon-territorial-select-search,
	  .mon-territorial-select-trigger,
	  .mon-territorial-route-table-filters select,
	  .mon-territorial-route-search-field,
	  .mon-territorial-route-table-filters button,
	  .mon-territorial-select-options > button,
  .mon-territorial-asset-list article,
  .mon-territorial-history-list article,
  .mon-territorial-district-grid article,
  .mon-territorial-route-kpi,
  .mon-territorial-route-map-footer span,
  .mon-territorial-route-context-metrics span,
  .mon-territorial-route-phase-toggle button,
  .mon-territorial-route-table tbody tr {
    transition: none;
  }

  .mon-territorial-select-popover {
    animation: none;
  }

  .mon-territorial-select-options > button:hover,
  .mon-territorial-asset-list article:hover,
  .mon-territorial-history-list article:hover,
  .mon-territorial-district-grid article:hover,
  .mon-territorial-route-kpi:hover,
  .mon-territorial-route-map-footer span:hover,
  .mon-territorial-route-context-metrics span:hover {
    transform: none;
  }
}

@media (max-width: 1360px) {
  .mon-territorial-route-command {
    grid-template-columns: 1fr;
  }

  .mon-territorial-route-metrics {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .mon-territorial-route-board {
    grid-template-columns: minmax(360px, 0.88fr) minmax(500px, 1.12fr);
    grid-template-rows: var(--route-main-height) auto;
  }

  .mon-territorial-route-context-body {
    grid-template-columns: minmax(0, 1fr);
  }

  .mon-territorial-route-context-overview {
    grid-template-columns: minmax(220px, 0.48fr) minmax(0, 1.52fr);
  }

  .mon-territorial-route-point-summary {
    grid-column: 1 / -1;
  }

  .mon-territorial-route-workbench {
    height: auto;
    min-height: 0;
  }

  .mon-territorial-source-workgrid,
  .mon-territorial-source-bottomgrid {
    grid-template-columns: 1fr;
  }

  .mon-territorial-source-console {
    grid-template-rows: auto auto auto minmax(0, 1fr);
    min-height: 0;
  }

  .mon-stage--sources > .mon-territorial-source-console {
    align-self: stretch;
    height: 100%;
  }

  .mon-territorial-form-picker,
  .mon-territorial-history {
    max-height: none;
  }
}

@media (max-width: 1120px) {
  .mon-territorial-route-workbench {
    --route-main-height: 680px;
  }

  .mon-territorial-route-board {
    grid-template-columns: 1fr;
    grid-template-rows: var(--route-main-height) var(--route-main-height) auto;
    overflow: auto;
  }

  .mon-territorial-route-context-card {
    grid-column: auto;
  }

  .mon-territorial-route-context-body {
    grid-template-columns: 1fr;
    overflow: visible;
  }

  .mon-territorial-route-context-overview,
  .mon-territorial-route-context-tables {
    grid-template-columns: 1fr;
  }

  .mon-territorial-route-mini-table > div {
    max-height: 240px;
  }
}

@media (max-width: 920px) {
  .mon-territorial-form-apply {
    grid-template-columns: 1fr;
  }

  .mon-territorial-form-apply button {
    width: 100%;
  }

  .mon-territorial-route-top-metrics,
  .mon-territorial-route-kpis,
  .mon-territorial-route-metrics,
  .mon-territorial-route-map-footer,
  .mon-territorial-route-context-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .mon-territorial-route-phase {
    grid-template-columns: 1fr;
  }

  .mon-territorial-route-context-body {
    grid-template-columns: 1fr;
  }

  .mon-territorial-route-context-overview,
  .mon-territorial-route-context-tables {
    grid-template-columns: 1fr;
  }

  .mon-territorial-route-command .pulso-button {
    justify-content: center;
  }

  .mon-territorial-source-command {
    grid-template-columns: 1fr;
    align-items: stretch;
  }

  .mon-territorial-source-command .pulso-button {
    justify-content: center;
  }

  .mon-territorial-source-top-metrics,
  .mon-territorial-form-facts,
  .mon-territorial-form-kpi-grid,
  .mon-territorial-form-consistency,
  .mon-territorial-validity-metrics,
  .mon-territorial-district-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .mon-territorial-form-summary-row,
  .mon-territorial-form-diagrams,
  .mon-territorial-form-blueprint,
  .mon-territorial-form-mini-panels,
  .mon-territorial-enumerator-layout {
    grid-template-columns: 1fr;
  }

  .mon-territorial-source-pipeline {
    grid-template-columns: 1fr;
    gap: 7px;
  }

  .mon-territorial-source-pipeline > i {
    width: 1px;
    height: 12px;
    justify-self: center;
  }

  .mon-territorial-validity-editor {
    grid-template-columns: 1fr;
  }

  .mon-territorial-asset-list article {
    grid-template-columns: minmax(0, 1fr);
  }

  .mon-territorial-asset-list article > span {
    width: fit-content;
  }

  .mon-territorial-asset-list button {
    justify-content: center;
  }

  .mon-territorial-history-list article {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .mon-territorial-history-list time {
    grid-column: 1 / -1;
  }
}

/* Rediseño de Manzanas seleccionadas: split view profesional, sin ficha al pie. */
.mon-workbench-content--modelo:has(.mon-territorial-route-workbench) {
  overflow: hidden;
}

.mon-stage--modelo:has(.mon-territorial-route-workbench) {
  height: 100%;
  min-height: 0;
  display: grid;
  overflow: hidden;
}

.mon-stage--modelo:has(.mon-territorial-route-workbench) .mon-territorial-route-panel {
  height: 100%;
  min-height: 0;
  overflow: hidden;
}

.mon-territorial-route-workbench {
  height: 100%;
  min-height: 0;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  gap: 10px;
  overflow: hidden;
}

.mon-territorial-route-panel {
  border-radius: 16px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.94), rgba(248, 250, 252, 0.9)),
    var(--pulso-surface);
  padding: 10px;
}

.mon-territorial-route-command {
  min-height: 66px;
  grid-template-columns: minmax(280px, 0.74fr) minmax(420px, 1fr) auto;
  gap: 10px;
  border-radius: 14px;
  background:
    linear-gradient(180deg, color-mix(in srgb, #fff 96%, var(--pulso-module-monitoring) 4%), rgba(248, 250, 252, 0.92)),
    #fff;
  padding: 10px 12px;
}

.mon-territorial-route-command-facts {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 7px;
}

.mon-territorial-route-command-facts span {
  min-width: 0;
  min-height: 44px;
  display: grid;
  align-content: center;
  gap: 2px;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 82%, #fff);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.74);
  padding: 7px 9px;
}

.mon-territorial-route-command-facts strong {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 15px;
  font-weight: 920;
  line-height: 1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-territorial-route-command-facts em {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text-soft);
  font-size: 8.5px;
  font-style: normal;
  font-weight: 850;
  letter-spacing: 0.04em;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.mon-territorial-route-tabs {
  width: fit-content;
  min-width: 0;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 82%, #fff);
  border-radius: 12px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.78), rgba(246, 248, 252, 0.72)),
    var(--pulso-surface-2);
  box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.045);
  padding: 3px;
}

.mon-territorial-route-tabs button {
  min-width: 0;
  min-height: 31px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid transparent;
  border-radius: 9px;
  background: transparent;
  color: var(--pulso-text-soft);
  cursor: pointer;
  font-size: 11px;
  font-weight: 860;
  padding: 6px 11px;
  transition:
    color var(--motion-dur-fast) var(--motion-ease-standard),
    background var(--motion-dur-fast) var(--motion-ease-standard),
    border-color var(--motion-dur-fast) var(--motion-ease-standard),
    box-shadow var(--motion-dur-fast) var(--motion-ease-standard),
    transform var(--motion-dur-press) var(--motion-ease-standard);
}

.mon-territorial-route-tabs button.is-active {
  border-color: color-mix(in srgb, var(--pulso-primary-border) 54%, var(--pulso-border));
  background: #fff;
  color: var(--pulso-text);
  box-shadow: 0 3px 10px rgba(15, 23, 42, 0.075);
}

.mon-territorial-route-tabs button:not(.is-active):hover {
  background: rgba(255, 255, 255, 0.58);
  color: var(--pulso-text);
}

.mon-territorial-route-summary-tab {
  min-width: 0;
  min-height: 0;
  height: 100%;
  display: grid;
  grid-template-rows: minmax(0, 1fr);
  overflow: hidden;
}

.mon-territorial-route-summary-hero,
.mon-territorial-route-summary-panel {
  min-width: 0;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 86%, #fff);
  border-radius: 13px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.88)),
    #fff;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.86),
    0 12px 28px rgba(15, 23, 42, 0.04);
}

.mon-territorial-route-summary-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 360px);
  align-items: center;
  gap: 14px;
  padding: 15px;
}

.mon-territorial-route-summary-hero > div:first-child,
.mon-territorial-route-summary-progress {
  min-width: 0;
  display: grid;
  gap: 5px;
