.mon-territorial-route-summary-hero span,
.mon-territorial-route-summary-panel header span,
.mon-territorial-route-response-owners header span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--pulso-text-soft);
  font-size: 9.5px;
  font-weight: 880;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.mon-territorial-route-summary-hero strong {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 19px;
  font-weight: 930;
  line-height: 1.12;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-territorial-route-summary-hero em,
.mon-territorial-route-summary-progress small {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text-soft);
  font-size: 11px;
  font-style: normal;
  font-weight: 720;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-territorial-route-summary-progress span {
