  display: block;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--pulso-module-monitoring), color-mix(in srgb, var(--pulso-module-monitoring) 68%, var(--pulso-accent-cyan)));
}

.mon-territorial-route-summary-metrics {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 8px;
}

.mon-territorial-route-summary-metrics .mon-territorial-route-kpi {
  min-height: 70px;
  border-radius: 11px;
}

.mon-territorial-route-summary-grid {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr) minmax(260px, 0.72fr);
  gap: 10px;
  align-items: start;
}

.mon-territorial-route-summary-panel {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 10px;
  padding: 12px;
