.mon-client-trend header {
  display: grid;
  grid-template-columns: minmax(180px, 1fr) minmax(0, auto);
  align-items: start;
  gap: 2px 14px;
  margin-bottom: 4px;
}

.mon-client-trend header strong {
  display: block;
  color: #111827;
  font-size: 16px;
  line-height: 1.1;
}

.mon-client-trend-hint {
  grid-column: 1 / -1;
  display: block;
  color: #64748b;
  font-size: 12px;
  font-style: normal;
  font-weight: 700;
  line-height: 1.25;
}

.mon-client-trend header .mon-client-trend-legend {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: flex-end;
  max-width: 310px;
  padding-top: 2px;
}

.mon-client-trend header .mon-client-trend-legend span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  border: 0;
  background: transparent;
  padding: 0;
  color: #64748b;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.035em;
  line-height: 1.2;
  text-transform: none;
}

.mon-client-trend header .mon-client-trend-legend span::before {
  content: "";
  flex: 0 0 auto;
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: #168a55;
}

.mon-client-trend header .mon-client-trend-legend .is-cumulative::before {
  background: #002f6c;
}

.mon-client-trend header .mon-client-trend-legend .is-partial::before {
  background: #b97611;
}

.mon-client-trend header .mon-client-trend-legend .is-refusals::before {
  background: #a61d4f;
}

.mon-client-report-actors,
.mon-client-report-sources {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.mon-client-report-actor-list,
.mon-client-report-source-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.mon-client-source-quality {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: start;
  gap: 10px;
}

.mon-client-source-quality-summary,
.mon-client-source-quality-map {
  min-width: 0;
  border: 1px solid rgba(15, 61, 99, 0.14);
  background:
    linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
  border-radius: 12px;
  padding: 12px;
}

.mon-client-source-quality-summary {
  display: grid;
  grid-template-columns: auto minmax(150px, 0.62fr) minmax(190px, 1fr) minmax(250px, 1.18fr);
  grid-template-areas:
    "donut copy bar metrics";
  align-items: center;
  justify-items: stretch;
  align-content: center;
  gap: 14px;
  align-self: start;
  min-height: 112px;
}

.mon-client-source-quality-summary span,
.mon-client-source-quality-map header span {
  display: block;
  color: #667389;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.mon-client-source-quality-summary strong,
.mon-client-source-quality-map header strong {
  display: block;
  margin-top: 3px;
  color: #111827;
  font-size: 19px;
  line-height: 1.08;
}

.mon-client-source-quality-copy {
  grid-area: copy;
  min-width: 0;
  text-align: left;
}

.mon-client-source-quality-summary em {
  display: block;
  margin-top: 5px;
  color: #64748b;
  font-size: 11px;
  font-style: normal;
  font-weight: 750;
  line-height: 1.25;
}

.mon-client-source-quality-donut {
  grid-area: donut;
  width: 104px;
  height: 104px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background:
    radial-gradient(circle at center, #fff 0 56%, transparent 57%),
    conic-gradient(
      #168a55 0 var(--source-effective),
      #b97611 var(--source-effective) var(--source-partial),
      #a61d4f var(--source-partial) 100%
    );
  box-shadow:
    inset 0 0 0 1px rgba(15, 61, 99, 0.08),
    0 8px 18px rgba(15, 23, 42, 0.05);
}

.mon-client-source-quality-donut span {
  width: 68px;
  height: 68px;
  border: 1px solid rgba(15, 61, 99, 0.08);
  border-radius: 50%;
  background: #fff;
  display: grid;
  place-items: center;
  color: #111827;
  font-size: 19px;
  font-weight: 900;
  letter-spacing: 0;
  line-height: 1;
  text-transform: none;
}

.mon-client-source-quality-donut em {
  display: block;
  margin: 0;
  color: #667389;
  font-size: 8px;
  font-style: normal;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.mon-client-source-quality-bar {
  grid-area: bar;
  width: 100%;
  max-width: none;
  height: 12px;
  display: flex;
  overflow: hidden;
  border: 1px solid rgba(15, 61, 99, 0.10);
  border-radius: 999px;
  background: #edf2f7;
  box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.07);
}

.mon-client-source-quality-bar i {
  display: block;
  width: var(--source-segment);
  min-width: 0;
}

.mon-client-source-quality-bar .is-effective {
  background: #168a55;
}

.mon-client-source-quality-bar .is-partial {
  background: #b97611;
}

.mon-client-source-quality-bar .is-refusals {
  background: #a61d4f;
}

.mon-client-source-quality-metrics {
  grid-area: metrics;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
  width: 100%;
  max-width: none;
}

.mon-client-source-quality-metrics span {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 8px;
  border: 1px solid rgba(15, 61, 99, 0.12);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.74);
  padding: 7px 8px;
}

.mon-client-source-quality-metrics strong {
  margin: 0;
  color: #111827;
  font-size: 15px;
  line-height: 1;
}

.mon-client-source-quality-metrics em {
  margin-top: 0;
  text-align: center;
  overflow: hidden;
  color: #667389;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.mon-client-source-quality-map {
  display: grid;
  gap: 10px;
}

.mon-client-source-quality-map header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.mon-client-source-actor-list {
  display: grid;
  gap: 9px;
}

.mon-client-source-actor-group {
  min-width: 0;
  display: grid;
  gap: 8px;
  border: 1px solid rgba(15, 61, 99, 0.12);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.78);
  padding: 9px;
}

.mon-client-source-actor-head {
  min-width: 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.mon-client-source-actor-head div {
  min-width: 0;
}

.mon-client-source-actor-head strong {
  display: block;
  overflow: hidden;
  color: #102033;
  font-size: 13px;
  font-weight: 900;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-client-source-actor-head em {
  display: block;
  margin-top: 2px;
  color: #667389;
  font-size: 10px;
  font-style: normal;
  font-weight: 760;
  line-height: 1.1;
}

.mon-client-source-actor-head > span {
  flex: 0 0 auto;
  min-width: 82px;
  text-align: right;
}

.mon-client-source-actor-head > span strong {
  font-size: 16px;
  line-height: 1;
}

.mon-client-source-actor-track {
  width: 100%;
  height: 15px;
  display: flex;
  overflow: hidden;
  border: 1px solid rgba(15, 61, 99, 0.11);
  border-radius: 999px;
  background: #edf2f7;
  box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.07);
}

.mon-client-source-actor-segment {
  --channel-accent: #168a55;
  --channel-soft: rgba(22, 138, 85, 0.12);
  flex: 0 0 var(--source-volume);
  min-width: 1px;
  max-width: 100%;
  height: 100%;
  display: flex;
  position: relative;
  overflow: hidden;
  border-right: 1px solid rgba(255, 255, 255, 0.82);
}

.mon-client-source-actor-segment::after {
  content: "";
  position: absolute;
  inset: auto 0 0;
  height: 2px;
  background: var(--channel-accent);
}

.mon-client-source-actor-segment i {
  display: block;
  width: var(--source-segment);
  min-width: 0;
  height: 100%;
}

.mon-client-source-actor-segment .is-effective {
  background: #168a55;
}

.mon-client-source-actor-segment .is-partial {
  background: #b97611;
}

.mon-client-source-actor-segment .is-refusals {
  background: #a61d4f;
}

.mon-client-source-actor-remainder {
  flex: 1 1 auto;
  min-width: 0;
}

.mon-client-source-actor-contribs {
  position: relative;
  min-height: 0;
  height: 40px;
  margin-top: -2px;
}

.mon-client-source-actor-contrib {
  --channel-accent: #168a55;
  --channel-soft: rgba(22, 138, 85, 0.12);
  position: absolute;
  left: var(--source-start);
  top: 0;
  width: var(--source-width);
  min-width: 1px;
  height: 100%;
  display: grid;
  grid-template-rows: 5px 17px 18px;
  justify-items: center;
  overflow: visible;
}

.mon-client-source-actor-contrib::before {
  content: "";
  width: 100%;
  min-width: 2px;
  height: 2px;
  align-self: center;
  border-radius: 999px;
  background: var(--channel-accent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--channel-accent) 10%, transparent);
}

.mon-client-source-actor-contrib > span {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  border: 1px solid color-mix(in srgb, var(--channel-accent) 20%, var(--pulso-border));
  border-radius: 999px;
  background: color-mix(in srgb, #fff 82%, var(--channel-soft) 18%);
  color: color-mix(in srgb, var(--channel-accent) 58%, #526176);
  font-size: 10px;
  font-weight: 800;
  line-height: 1;
  padding: 4px 7px;
  white-space: nowrap;
}

.mon-client-source-actor-contrib strong {
  color: color-mix(in srgb, var(--channel-accent) 38%, #102033);
  font-size: 11px;
  font-weight: 900;
}

.mon-client-source-actor-contrib em {
  color: #667389;
  font-size: 10px;
  font-style: normal;
  font-weight: 800;
}

.mon-client-source-actor-segment.is-correo,
.mon-client-source-actor-contrib.is-correo {
  --channel-accent: #2563eb;
  --channel-soft: rgba(37, 99, 235, 0.12);
}

.mon-client-source-actor-segment.is-telefono,
.mon-client-source-actor-contrib.is-telefono {
  --channel-accent: var(--pulso-module-monitoring);
  --channel-soft: var(--pulso-module-monitoring-soft);
}

.mon-client-source-actor-segment.is-presencial,
.mon-client-source-actor-contrib.is-presencial {
  --channel-accent: var(--pulso-accent-green);
  --channel-soft: rgba(22, 163, 74, 0.12);
}

.mon-client-source-actor-segment.is-whatsapp,
.mon-client-source-actor-contrib.is-whatsapp {
  --channel-accent: #15803d;
  --channel-soft: rgba(21, 128, 61, 0.12);
}

.mon-client-source-actor-segment.is-sms,
.mon-client-source-actor-contrib.is-sms {
  --channel-accent: var(--pulso-warn-accent);
  --channel-soft: var(--pulso-warn-bg);
}

.mon-client-source-actor-segment.is-mixto,
.mon-client-source-actor-contrib.is-mixto {
  --channel-accent: var(--pulso-text-soft);
  --channel-soft: var(--pulso-surface-3);
}

.mon-client-source-actor-empty {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: -2px;
}

.mon-client-source-actor-empty > span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border: 1px dashed rgba(100, 116, 139, 0.28);
  border-radius: 999px;
  background: rgba(248, 250, 252, 0.86);
  padding: 3px 7px 3px 3px;
}

.mon-client-source-actor-empty em {
  color: #667389;
  font-size: 10px;
  font-style: normal;
  font-weight: 850;
  line-height: 1;
}

.mon-client-source-actor-channels {
  min-width: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.mon-client-source-actor-channels > span {
  min-width: 0;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border: 1px solid rgba(15, 61, 99, 0.12);
  border-radius: 999px;
  background: #fff;
  padding: 3px 7px 3px 3px;
}

.mon-client-source-actor-channels strong {
  color: #102033;
  font-size: 11px;
  font-weight: 900;
  line-height: 1;
}

.mon-client-source-actor-channels em {
  color: #667389;
  font-size: 10px;
  font-style: normal;
  font-weight: 760;
  line-height: 1;
}

.mon-client-source-channel-list {
  display: grid;
  gap: 7px;
}

.mon-client-source-channel-row {
  display: grid;
  grid-template-columns: minmax(180px, 0.72fr) minmax(190px, 1fr) minmax(88px, auto);
  align-items: center;
  gap: 10px;
}

.mon-client-source-channel-name {
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  grid-template-rows: auto auto;
  gap: 2px 7px;
  align-items: center;
}

.mon-client-source-channel-name .mon-channel-badge {
  grid-row: 1 / 3;
}

.mon-client-source-channel-name strong {
  overflow: hidden;
  color: #111827;
  font-size: 12px;
  font-weight: 900;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-client-source-channel-name em,
.mon-client-source-channel-values span,
.mon-client-source-meter-labels span {
  color: #667389;
  font-size: 10px;
  font-style: normal;
  font-weight: 760;
}

.mon-client-source-channel-values {
  min-width: 86px;
  text-align: right;
}

.mon-client-source-channel-values strong {
  display: block;
  color: #111827;
  font-size: 15px;
  line-height: 1;
}

.mon-client-source-meter {
  width: 100%;
  min-width: 0;
  height: 12px;
  border: 1px solid rgba(15, 61, 99, 0.10);
  border-radius: 999px;
  background: #edf2f7;
  overflow: hidden;
  box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.07);
}

.mon-client-source-meter-fill {
  width: var(--source-volume);
  min-width: 1px;
  max-width: 100%;
  height: 100%;
  display: flex;
  border-radius: inherit;
  overflow: hidden;
}

.mon-client-source-meter-fill i {
  display: block;
  width: var(--source-segment);
  min-width: 0;
  height: 100%;
}

.mon-client-source-meter-fill .is-effective {
  background: #168a55;
}

.mon-client-source-meter-fill .is-partial {
  background: #b97611;
}

.mon-client-source-meter-fill .is-refusals {
  background: #a61d4f;
}

.mon-client-report-actor-row {
  display: grid;
  grid-template-columns: minmax(390px, 0.86fr) minmax(500px, 1.22fr);
  align-items: stretch;
  gap: 12px;
  border: 1px solid rgba(15, 61, 99, 0.16);
  background: linear-gradient(180deg, #ffffff 0%, #fbfdff 100%);
  border-radius: 12px;
  padding: 12px;
}

.mon-client-report-actor-summary {
  min-height: 100%;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 11px;
  align-content: stretch;
}

.mon-client-report-actor-summary header {
  display: block;
}

.mon-client-report-actor-summary header strong {
  display: block;
  margin-top: 2px;
  color: #111827;
  font-size: 19px;
  line-height: 1.1;
}

.mon-client-report-actor-meter {
  width: clamp(112px, 30%, 132px);
  aspect-ratio: 1;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background:
    radial-gradient(circle at center, #fff 0 54%, transparent 55%),
    conic-gradient(#168a55 0 var(--client-progress), #e9eef5 var(--client-progress) 100%);
  box-shadow: inset 0 0 0 1px rgba(15, 61, 99, 0.08);
}

.mon-client-report-actor-meter span {
  width: 76px;
  height: 76px;
  border-radius: 50%;
  display: grid;
  align-content: center;
  justify-items: center;
  gap: 4px;
  background: #fff;
  border: 1px solid rgba(15, 61, 99, 0.08);
  text-align: center;
}

.mon-client-report-actor-meter strong {
  display: block;
  color: #111827;
  font-size: 20px;
  line-height: 1;
}

.mon-client-report-actor-meter em {
  display: block;
  color: #667389;
  font-size: 10px;
  font-style: normal;
  font-weight: 900;
  letter-spacing: 0.03em;
  line-height: 1;
  text-transform: uppercase;
}

.mon-client-report-actor-progress {
  min-width: 0;
  min-height: 134px;
  display: grid;
  grid-template-columns: minmax(112px, 0.35fr) minmax(0, 1fr);
  gap: 14px;
  align-items: center;
}

.mon-client-report-actor-bar-wrap {
  min-width: 0;
  display: grid;
  gap: 7px;
}

.mon-client-report-actor-bar {
  display: flex;
  width: 100%;
  height: 16px;
  overflow: hidden;
  border: 1px solid rgba(15, 61, 99, 0.10);
  border-radius: 999px;
  background: #edf2f7;
  box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.08);
}

.mon-client-report-actor-bar i {
  display: block;
  width: var(--client-segment);
  min-width: 0;
}

.mon-client-report-actor-bar .is-effective {
  background: #168a55;
}

.mon-client-report-actor-bar .is-partial {
  background: #b97611;
}

.mon-client-report-actor-bar .is-refusals {
  background: #a61d4f;
}

.mon-client-report-actor-bar .is-unanswered {
  background: #cbd5e1;
}

.mon-client-report-actor-bar-caption {
  min-width: 0;
  display: flex;
  justify-content: space-between;
  gap: 8px;
  color: #667389;
  font-size: 11px;
  font-weight: 780;
  line-height: 1.1;
}

.mon-client-report-actor-bar-caption span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-client-report-actor-stats {
  align-self: end;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 7px;
}

.mon-client-report-actor-stats.has-targets {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.mon-client-report-source-row {
  display: grid;
  grid-template-columns: minmax(230px, 0.72fr) minmax(260px, 1fr) minmax(126px, auto);
  align-items: center;
  gap: 12px;
  border: 1px solid rgba(15, 61, 99, 0.14);
  background: #fff;
  border-radius: 10px;
  padding: 10px 12px;
}

.mon-client-report-source-group {
  min-width: 0;
  display: grid;
  gap: 7px;
  border: 1px solid rgba(15, 61, 99, 0.14);
  border-radius: 12px;
  background:
    linear-gradient(180deg, rgba(248, 251, 255, 0.92) 0%, rgba(255, 255, 255, 0.94) 100%);
  padding: 10px;
}

.mon-client-report-source-group-head {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 10px;
  padding: 0 2px 3px;
}

.mon-client-report-source-group-head div {
  min-width: 0;
}

.mon-client-report-source-group-head span {
  display: block;
  color: #667389;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.08em;
  line-height: 1;
  text-transform: uppercase;
}

.mon-client-report-source-group-head strong {
  display: block;
  overflow: hidden;
  margin-top: 3px;
  color: #102033;
  font-size: 15px;
  font-weight: 900;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-client-report-source-group-head em,
.mon-client-report-source-group-head small {
  min-width: 0;
  border: 1px solid rgba(15, 61, 99, 0.12);
  border-radius: 999px;
  background: #fff;
  color: #526176;
  font-size: 11px;
  font-style: normal;
  font-weight: 800;
  line-height: 1.1;
  padding: 6px 9px;
  white-space: nowrap;
}

.mon-client-report-source-group-head em {
  border-color: rgba(14, 105, 69, 0.18);
  color: #0f7b55;
}

.mon-client-report-source-group-rows {
  display: grid;
  gap: 6px;
}

.mon-client-report-source-group .mon-client-report-source-row {
  border-color: rgba(15, 61, 99, 0.11);
  background: rgba(255, 255, 255, 0.92);
}

.mon-client-report-source-id {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.mon-client-report-source-id .mon-channel-badge {
  align-self: center;
}

.mon-client-report-source-row strong {
  overflow: hidden;
  color: #102033;
