}

.mon-field-occurrences-fieldcheck header span,
.mon-field-occurrences-fieldcheck header em {
  min-width: 0;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  overflow: hidden;
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-style: normal;
  font-weight: 850;
  line-height: 1.1;
  text-overflow: ellipsis;
  text-transform: uppercase;
