}

.mon-field-occurrences-fieldcheck > div span.is-missing {
  border-color: var(--pulso-danger-border);
  color: var(--pulso-danger-fg);
}

.mon-field-occurrences-fieldcheck > div span.is-optional {
  color: var(--pulso-text-soft);
}

.mon-field-occurrences-fieldcheck b,
.mon-field-occurrences-fieldcheck span em {
