}

.mon-field-occurrences-asset span {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.mon-field-occurrences-asset strong,
.mon-field-occurrences-asset em {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-field-occurrences-asset strong {
  font-size: 12px;
  font-weight: 900;
  line-height: 1.1;
}

.mon-field-occurrences-asset em {
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-style: normal;
  font-weight: 760;
