  justify-content: center;
  min-height: 24px;
  border-radius: 999px;
  font-size: 9px;
  font-style: normal;
  font-weight: 850;
  line-height: 1;
  white-space: nowrap;
}

.mon-field-occurrences-asset b {
  border: 1px solid var(--pulso-border);
