  color: var(--pulso-success-fg);
}

.mon-field-occurrences-asset i {
  min-width: 34px;
  color: var(--pulso-primary);
}

.mon-field-occurrences-setup {
  min-width: 0;
  display: grid;
  gap: 11px;
  border: 1px solid color-mix(in srgb, var(--pulso-border-strong) 22%, var(--pulso-border));
  border-radius: 14px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.86)),
