  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.86),
    0 10px 24px rgba(15, 23, 42, 0.04);
  padding: 12px;
}

.mon-field-occurrences-setup > header {
  min-width: 0;
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 12px;
}

.mon-field-occurrences-setup > header div {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.mon-field-occurrences-setup > header span,
.mon-field-occurrences-setup > header em {
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-style: normal;
  font-weight: 900;
  letter-spacing: 0.065em;
  text-transform: uppercase;
}

.mon-field-occurrences-setup > header strong {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 15px;
  font-weight: 920;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-field-occurrences-setup .mon-field-occurrences-flow {
  max-width: none;
  margin-top: 0;
}

.mon-field-occurrences-body.is-table-only {
  grid-template-columns: 1fr;
}

.mon-field-occurrences-body.is-table-only .mon-field-occurrences-table {
  min-height: 380px;
  max-height: 680px;
}

.mon-field-occurrences-body.is-side-only {
  grid-template-columns: 1fr;
}

.mon-field-occurrences-body.is-side-only .mon-field-occurrences-side {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.mon-field-occurrences-body.is-side-only .mon-field-occurrences-side section {
  min-height: 178px;
  align-content: start;
}

@media (max-width: 1180px) {
  .mon-territorial-source-tabbar,
  .mon-field-occurrences-tabbar,
  .mon-field-occurrences-quickstats,
  .mon-field-occurrences-connect-summary,
  .mon-field-occurrences-assets,
  .mon-field-occurrences-body.is-side-only .mon-field-occurrences-side {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .mon-field-occurrences-connect-controls {
    grid-template-columns: 1fr auto;
  }

  .mon-field-occurrences-connect-search {
    grid-column: 1 / -1;
  }
}

@media (max-width: 760px) {
  .mon-territorial-source-tabbar,
  .mon-field-occurrences-tabbar,
  .mon-field-occurrences-quickstats,
  .mon-field-occurrences-connect > header,
  .mon-field-occurrences-connect-summary,
  .mon-field-occurrences-connect-controls,
  .mon-field-occurrences-fieldcheck header,
  .mon-field-occurrences-assets,
  .mon-field-occurrences-body.is-side-only .mon-field-occurrences-side {
    grid-template-columns: 1fr;
  }

  .mon-field-occurrences-connect > header {
    align-items: start;
  }

  .mon-field-occurrences-connect > header .mon-field-occurrences-connect-head-actions {
    justify-content: flex-start;
  }

  .mon-field-occurrences-asset {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .mon-field-occurrences-asset b {
    display: none;
  }

  .mon-field-occurrences-fieldcheck header strong {
    white-space: normal;
  }
}

