  white-space: nowrap;
}

.mon-operational-review-list article.is-ready header em {
  border-color: var(--pulso-success-border);
  background: var(--pulso-success-bg);
  color: var(--pulso-success-fg);
}

.mon-operational-review-list article.is-warning header em {
  border-color: var(--pulso-warn-border);
  background: var(--pulso-warn-bg);
  color: var(--pulso-warn-fg);
}

.mon-operational-review-list article.is-error header em {
  border-color: var(--pulso-danger-border);
  background: var(--pulso-danger-bg);
  color: var(--pulso-danger-fg);
}

.mon-operational-review-list article p,
.mon-operational-review-list article small,
.mon-operational-preview-note,
.mon-operational-ump-note {
