  -webkit-line-clamp: 2;
}

.mon-operational-review-list article small b {
  color: var(--pulso-text);
  font-weight: 820;
}

.mon-operational-review-note {
  color: color-mix(in srgb, var(--pulso-text-soft) 82%, var(--pulso-text));
}

.mon-operational-preview-note {
