}

.mon-operational-ump-kpis {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 6px;
}

.mon-operational-ump-kpis span {
  min-width: 0;
  display: grid;
  gap: 3px;
  border: 1px solid var(--pulso-border);
  border-radius: 9px;
  background: #fff;
  padding: 8px;
}

.mon-operational-ump-kpis strong {
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 14px;
  font-weight: 880;
  line-height: 1;
  text-overflow: ellipsis;
}

.mon-operational-ump-kpis em {
  overflow: hidden;
  color: var(--pulso-text-soft);
  font-size: 9.5px;
  font-style: normal;
  font-weight: 760;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-operational-ump-toolbar {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(190px, 0.48fr) minmax(0, 1fr);
  align-items: center;
  gap: 8px;
}

.mon-operational-ump-search {
  min-width: 0;
  min-height: 30px;
  display: grid;
  grid-template-columns: 16px minmax(0, 1fr);
  align-items: center;
  gap: 6px;
  border: 1px solid var(--pulso-border);
  border-radius: 9px;
  background: #fff;
  color: var(--pulso-text-soft);
  padding: 0 9px;
}

.mon-operational-ump-search input {
  width: 100%;
  min-width: 0;
  border: 0;
  background: transparent;
  color: var(--pulso-text);
  font: inherit;
  font-size: 11px;
  font-weight: 720;
  outline: 0;
}

.mon-operational-ump-search input::placeholder {
  color: var(--pulso-text-faint);
}

.mon-operational-ump-filters {
  min-width: 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 5px;
}

.mon-operational-ump-filters button {
  min-height: 28px;
  border: 1px solid var(--pulso-border);
  border-radius: var(--pulso-radius-chip);
  background: #fff;
  color: var(--pulso-text-soft);
  cursor: pointer;
  font: inherit;
  font-size: 10px;
  font-weight: 820;
  line-height: 1;
  padding: 6px 9px;
  white-space: nowrap;
}

.mon-operational-ump-filters button:hover,
.mon-operational-ump-filters button.is-selected {
  border-color: color-mix(in srgb, var(--pulso-primary-border) 64%, var(--pulso-border));
  background: color-mix(in srgb, var(--pulso-primary-soft) 36%, #fff);
  color: var(--pulso-primary);
}

.mon-operational-ump-note {
  border: 1px dashed var(--pulso-border);
  border-radius: 10px;
  background: var(--pulso-surface-2);
  padding: 10px;
}

.mon-operational-ump-table {
  min-width: 0;
  max-height: 340px;
  overflow: auto;
  border: 1px solid var(--pulso-border);
  border-radius: 10px;
  background: #fff;
}

.mon-operational-ump-table table {
  width: 100%;
  min-width: 720px;
  border-collapse: collapse;
}

.mon-operational-ump-table th,
.mon-operational-ump-table td {
  border-bottom: 1px solid var(--pulso-border);
  color: var(--pulso-text);
  font-size: 11px;
  font-weight: 720;
  padding: 8px 9px;
  text-align: left;
  vertical-align: middle;
  white-space: nowrap;
}

.mon-operational-ump-table th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: var(--pulso-header-row);
  color: var(--pulso-text-soft);
