  text-transform: uppercase;
}

.mon-operational-ump-table tr:last-child td {
  border-bottom: 0;
}

.mon-operational-ump-table tr.is-review td {
  background: color-mix(in srgb, var(--pulso-warn-bg) 16%, #fff);
}

.mon-operational-ump-table tr.is-format td {
  background: color-mix(in srgb, var(--pulso-info-bg) 56%, #fff);
}

.mon-operational-ump-table td strong {
