}

.mon-operational-ump-table td code {
  border: 1px solid color-mix(in srgb, var(--pulso-border) 80%, #fff);
  border-radius: 7px;
  background: var(--pulso-surface-2);
  color: var(--pulso-text);
  font-size: 10.5px;
  font-weight: 760;
  padding: 3px 6px;
}

.mon-operational-ump-responsible,
.mon-operational-ump-district {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.mon-operational-ump-responsible strong,
.mon-operational-ump-district strong {
  max-width: 240px;
  overflow: hidden;
  display: block;
  text-overflow: ellipsis;
}

.mon-operational-ump-responsible small,
.mon-operational-ump-district small,
.mon-operational-ump-empty {
  color: var(--pulso-text-soft);
  font-size: 9.5px;
  font-weight: 720;
}

.mon-operational-ump-status {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  border: 1px solid var(--pulso-border);
  border-radius: var(--pulso-radius-chip);
  background: #fff;
  color: var(--pulso-text-soft);
  font-size: 9px;
  font-weight: 860;
  line-height: 1;
  padding: 4px 7px;
  white-space: nowrap;
}

.mon-operational-ump-status.is-recognized {
  border-color: var(--pulso-success-border);
  background: var(--pulso-success-bg);
  color: var(--pulso-success-fg);
}

.mon-operational-ump-status.is-pending {
  border-color: var(--pulso-primary-border);
  background: var(--pulso-primary-soft);
  color: var(--pulso-primary);
}

.mon-operational-ump-status.is-format {
  border-color: var(--pulso-primary-border);
  background: var(--pulso-primary-soft);
  color: var(--pulso-primary);
}

.mon-operational-ump-status.is-review {
  border-color: var(--pulso-warn-border);
  background: var(--pulso-warn-bg);
  color: var(--pulso-warn-fg);
}

.mon-operational-ump-status.is-missing {
  border-color: var(--pulso-border);
  background: var(--pulso-surface-2);
  color: var(--pulso-text-soft);
}

.mon-operational-ump-status.is-danger {
  border-color: var(--pulso-danger-border);
  background: var(--pulso-danger-bg);
  color: var(--pulso-danger-fg);
}

.mon-operational-ump-empty-cell {
  color: var(--pulso-text-soft);
  font-size: 11px;
  font-weight: 680;
  line-height: 1.35;
  text-align: center;
  white-space: normal;
}

.mon-territorial-operational-actions {
  min-width: 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
  gap: 8px;
}

.mon-territorial-operational-actions button {
  min-height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid var(--pulso-border);
  border-radius: 10px;
  background: #fff;
  color: var(--pulso-text);
