  .mon-territorial-source-console.is-tab-form .mon-territorial-form-summary-row,
  .mon-territorial-source-console.is-tab-form .mon-territorial-form-detail-main,
  .mon-territorial-source-console.is-tab-form .mon-territorial-form-kpi-grid,
  .mon-territorial-source-console.is-tab-form .mon-territorial-form-consistency,
  .mon-territorial-source-console.is-tab-form .mon-territorial-form-blueprint,
  .mon-territorial-source-console.is-tab-form .mon-territorial-form-readiness,
  .mon-territorial-source-console.is-tab-form .mon-territorial-source-coverage-summary,
  .mon-territorial-source-console.is-tab-form .mon-territorial-source-cut-counts,
  .mon-territorial-source-console.is-tab-form .mon-territorial-form-technical dl,
  .mon-territorial-source-console.is-tab-form .mon-territorial-field-start-card,
