  flex-direction: column;
  align-content: stretch;
  gap: 7px;
  padding: 7px;
}

.mon-page .pulso-panel .mon-territorial-route-accordion-item {
  flex: 0 0 auto;
  min-width: 0;
  display: grid;
  overflow: hidden;
}

/* Territorial Manzanas should read as a full workbench list, not a tiny nested scroller. */
.mon-page .mon-territorial-route-table-workspace {
  height: auto;
  min-height: 100%;
  overflow: visible;
  align-content: start;
}

.mon-page .mon-territorial-route-table-workspace .mon-territorial-route-sidebar {
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto auto;
  overflow: visible;
  align-content: start;
}

.mon-page .mon-territorial-route-table-workspace .mon-territorial-route-table-card {
  height: min(680px, calc(100vh - 330px));
  min-height: 440px;
  grid-template-rows: auto auto auto;
  overflow-x: hidden;
  overflow-y: auto;
}

.mon-page .mon-territorial-route-table-workspace .mon-territorial-route-context-card {
  height: auto;
  min-height: 300px;
  max-height: 420px;
  overflow-x: hidden;
  overflow-y: auto;
}

.mon-page .mon-territorial-route-table-workspace .mon-territorial-route-table-scroll {
  height: auto;
  max-height: none;
  overflow: visible;
}

.mon-page .pulso-panel button.mon-territorial-route-accordion-trigger {
  width: 100%;
  min-width: 0;
  min-height: 62px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) minmax(112px, 132px);
  align-items: center;
  justify-content: stretch;
  gap: 8px;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--pulso-text);
  padding: 10px 10px 10px 11px;
  text-align: left;
}

.mon-page .pulso-panel button.mon-territorial-route-accordion-trigger:hover {
  background: color-mix(in srgb, var(--pulso-primary-soft) 18%, transparent);
  color: var(--pulso-text);
}

.mon-page .pulso-panel .mon-territorial-route-accordion-title,
.mon-page .pulso-panel .mon-territorial-route-accordion-meta {
  min-width: 0;
  display: grid;
}

.mon-page .pulso-panel .mon-territorial-route-accordion-title strong,
.mon-page .pulso-panel .mon-territorial-route-accordion-title em,
.mon-page .pulso-panel .mon-territorial-route-accordion-meta b {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.mon-page .pulso-panel button.mon-territorial-route-primary-block,
.mon-page .pulso-panel button.mon-territorial-route-replacement-row {
  width: 100%;
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  justify-content: stretch;
  gap: 2px 7px;
  border-radius: 9px;
  padding: 7px 8px;
  text-align: left;
}

.mon-territorial-view-error {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

@media (max-width: 1080px), (max-height: 640px) {
  .mon-territorial-form-picker {
    min-height: 118px !important;
  }
}

/* Monitoreo desktop modernization: split-view shell, command bars and table actions. */
.mon-page {
  --mon-border: color-mix(in srgb, var(--pulso-border) 82%, rgba(255, 255, 255, 0.9));
  --mon-border-strong: color-mix(in srgb, var(--pulso-border-strong) 66%, #fff);
  --mon-sidebar-bg: color-mix(in srgb, var(--pulso-surface-2) 74%, rgba(255, 255, 255, 0.88));
  --mon-command-bg: color-mix(in srgb, #fff 86%, var(--pulso-surface-2));
  --mon-selected-bg: color-mix(in srgb, var(--pulso-module-monitoring) 8%, #fff);
  --mon-focus-ring: color-mix(in srgb, var(--pulso-module-monitoring) 18%, transparent);
  --pulso-primary-strong: var(--pulso-primary);
  --pulso-success-accent: var(--pulso-accent-green);
  --pulso-muted-surface: var(--pulso-surface-3);
  --pulso-text-muted: var(--pulso-text-soft);
  --pulso-accent: var(--pulso-module-monitoring);
  --pulso-accent-strong: color-mix(in srgb, var(--pulso-module-monitoring) 78%, var(--pulso-text) 22%);
}

.pulso-main:has(.mon-page) {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.52), rgba(255, 255, 255, 0) 240px),
    var(--pulso-bg);
  padding: 8px;
}

.mon-page .pulso-page-frame-body {
  gap: 8px;
}

.mon-workbench {
  border: 1px solid var(--mon-border);
  border-radius: 14px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(248, 250, 253, 0.98)),
    var(--pulso-surface);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.92),
    0 18px 40px rgba(15, 23, 42, 0.08);
  overflow: hidden;
}

.mon-workbench.pulso-split-view {
  grid-template-columns: minmax(204px, 224px) minmax(0, 1fr);
}

.mon-workbench-rail {
  grid-template-rows: auto auto auto minmax(0, 1fr) auto auto auto;
  gap: 6px;
  border-right: 1px solid var(--mon-border);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.62), rgba(255, 255, 255, 0.22)),
    var(--mon-sidebar-bg);
  backdrop-filter: blur(18px) saturate(1.08);
  padding: 7px;
}

.mon-rail-head {
  gap: 2px;
  border-bottom: 1px solid color-mix(in srgb, var(--pulso-border) 74%, transparent);
  padding: 4px 5px 8px;
}

.mon-rail-head strong {
  font-size: 14px;
  line-height: 1.16;
}

.mon-rail-head small {
  font-size: 10px;
  line-height: 1.2;
}

.mon-flow-overview {
  display: grid;
  gap: 6px;
  border: 1px solid color-mix(in srgb, var(--pulso-module-monitoring) 16%, var(--pulso-border));
  border-radius: 10px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.78), rgba(255, 255, 255, 0.54)),
    color-mix(in srgb, var(--pulso-module-monitoring) 5%, #fff);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.82),
    0 1px 2px rgba(15, 23, 42, 0.04);
  padding: 7px;
}

.mon-flow-overview-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.mon-flow-overview-head span {
  overflow: hidden;
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-weight: 800;
  line-height: 1.1;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.mon-flow-overview-head strong {
  flex: 0 0 auto;
  color: var(--pulso-text);
  font-size: 11px;
  line-height: 1.1;
}

.mon-flow-track {
  position: relative;
  overflow: hidden;
  height: 5px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--pulso-border) 64%, #fff);
}

.mon-flow-track span {
  position: absolute;
  inset: 0 auto 0 0;
  width: var(--mon-flow-progress, 0%);
  border-radius: inherit;
  background: linear-gradient(90deg, var(--pulso-module-monitoring), color-mix(in srgb, var(--pulso-module-monitoring) 60%, var(--pulso-accent-green)));
  transition: width var(--motion-dur-base) var(--motion-ease-out);
}

.mon-flow-overview small {
  display: -webkit-box;
  overflow: hidden;
  color: var(--pulso-text-muted);
  font-size: 10.5px;
  font-style: normal;
  line-height: 1.24;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.mon-flow-overview.is-warning,
.mon-flow-overview.is-error {
  border-color: color-mix(in srgb, var(--pulso-warn-accent) 28%, var(--pulso-border));
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.78), rgba(255, 255, 255, 0.56)),
    color-mix(in srgb, var(--pulso-warn-accent) 7%, #fff);
}

.mon-flow-overview.is-warning .mon-flow-track span,
.mon-flow-overview.is-error .mon-flow-track span {
  background: linear-gradient(90deg, var(--pulso-warn-accent), var(--pulso-module-monitoring));
}

.mon-rail-section-label {
  padding: 4px 5px 1px;
}

.mon-rail-section-label span,
.mon-rail-section-label em {
  letter-spacing: 0.04em;
}

.mon-workbench-nav {
  grid-auto-rows: minmax(50px, auto);
  gap: 3px;
  padding: 1px;
  scrollbar-width: thin;
}

.mon-nav-item {
  min-height: 50px;
  grid-template-columns: 28px minmax(0, 1fr) minmax(44px, auto);
  gap: 7px;
  border-color: transparent;
  border-radius: 8px;
  background: transparent;
  box-shadow: none;
  padding: 6px 7px 6px 6px;
  transition:
    background-color var(--motion-dur-fast) var(--motion-ease-out),
    border-color var(--motion-dur-fast) var(--motion-ease-out),
    box-shadow var(--motion-dur-fast) var(--motion-ease-out),
    transform var(--motion-dur-press) var(--motion-ease-out);
}

.mon-nav-item::before {
  inset: 6px auto 6px 0;
  width: 3px;
}

.mon-nav-item:hover {
  border-color: color-mix(in srgb, var(--view-accent) 18%, transparent);
  background: color-mix(in srgb, var(--view-accent) 6%, #fff);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.72);
}

.mon-nav-item:active {
  transform: scale(0.992);
}

.mon-nav-item.is-active,
.mon-nav-item[aria-current="page"] {
  border-color: color-mix(in srgb, var(--view-accent) 26%, transparent);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.74), rgba(255, 255, 255, 0.42)),
    color-mix(in srgb, var(--view-accent) 9%, #fff);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.8),
    0 1px 2px rgba(15, 23, 42, 0.04);
}

.mon-nav-icon {
  width: 28px;
  height: 28px;
  border-color: color-mix(in srgb, var(--view-accent) 18%, var(--pulso-border));
  border-radius: 8px;
  background: color-mix(in srgb, var(--view-accent) 7%, #fff);
}

.mon-nav-item.is-active .mon-nav-icon,
.mon-nav-item[aria-current="page"] .mon-nav-icon {
  background: color-mix(in srgb, var(--view-accent) 14%, #fff);
  color: var(--view-accent);
}

.mon-nav-copy {
  min-width: 0;
  gap: 1px;
}

.mon-nav-copy strong {
  display: -webkit-box;
  overflow: hidden;
  font-size: 12px;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-height: 1.14;
}

.mon-nav-copy span {
  display: -webkit-box;
  overflow: hidden;
  color: var(--pulso-text-muted);
  font-size: 10.5px;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
  line-height: 1.18;
}

.mon-nav-current {
  color: color-mix(in srgb, var(--view-accent) 82%, var(--pulso-text-soft));
  opacity: 0.82;
}

.mon-nav-status {
  min-width: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 3px;
  color: var(--pulso-text-faint);
}

.mon-nav-status svg {
  flex: 0 0 auto;
}

.mon-nav-status small {
  overflow: hidden;
  max-width: 44px;
  font-size: 9.5px;
  font-style: normal;
  font-weight: 800;
  line-height: 1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-nav-status.is-ready {
  color: var(--pulso-success-fg);
}

.mon-nav-status.is-warning {
  color: var(--pulso-warn-fg);
}

.mon-nav-status.is-error {
  color: var(--pulso-danger-fg);
}

.mon-nav-status.is-loading,
.mon-nav-status.is-base {
  color: color-mix(in srgb, var(--view-accent) 80%, var(--pulso-text-soft));
}

.mon-nav-status.is-current {
  color: var(--view-accent);
}

.mon-rail-web-publish-trigger {
  min-height: 52px;
  grid-template-columns: 28px minmax(0, 1fr) auto;
  border-color: color-mix(in srgb, var(--pulso-module-monitoring) 22%, var(--pulso-border));
  border-radius: 9px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.78), rgba(255, 255, 255, 0.56)),
    color-mix(in srgb, var(--pulso-module-monitoring) 5%, #fff);
  padding: 7px;
}

.mon-rail-web-publish-trigger-icon {
  width: 28px;
  height: 28px;
  border-radius: 8px;
}

.mon-rail-phase-switch,
.mon-rail-status {
  border-top-color: color-mix(in srgb, var(--pulso-border) 74%, transparent);
  padding-top: 7px;
}

.mon-rail-phase-switch > div {
  border-radius: 9px;
  background: color-mix(in srgb, var(--pulso-surface-2) 62%, #fff);
  padding: 3px;
}

.mon-rail-phase-switch button {
  min-height: 36px;
  border-radius: 7px;
  padding: 5px 7px;
}

.mon-rail-phase-switch button.is-active {
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.82),
    0 1px 2px rgba(15, 23, 42, 0.08);
}

.mon-rail-sync {
  border-color: color-mix(in srgb, var(--pulso-border) 78%, #fff);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.66);
}

.mon-workbench-main {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.82), rgba(248, 250, 252, 0.94)),
    var(--pulso-surface);
}

.mon-workbench-head {
  min-height: 56px;
  border-bottom: 1px solid var(--mon-border);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(255, 255, 255, 0.74)),
    var(--mon-command-bg);
  backdrop-filter: blur(14px) saturate(1.08);
  padding: 9px 12px;
}

.mon-workbench-head-icon {
  width: 34px;
  height: 34px;
  border-radius: 9px;
  background: color-mix(in srgb, var(--pulso-module-monitoring) 7%, #fff);
}

.mon-workbench-head-copy {
  gap: 1px;
}

.mon-workbench-head-copy h2 {
  font-size: 16px;
  line-height: 1.12;
}

.mon-workbench-head-copy p {
  font-size: 11.5px;
  line-height: 1.26;
}

.mon-workbench-pills {
  gap: 5px;
}

.mon-workbench-pills span {
  min-height: 24px;
  border-color: color-mix(in srgb, var(--pulso-border) 72%, #fff);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.72);
  color: var(--pulso-text-soft);
  font-size: 10px;
  padding: 4px 9px;
}

.mon-territorial-report-status {
  border-bottom: 1px solid var(--mon-border);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.8), rgba(248, 250, 252, 0.78)),
    var(--pulso-surface-2);
  padding: 6px 12px;
}

.mon-territorial-loading {
  --territorial-loading-accent: var(--pulso-module-monitoring);
  position: relative;
  min-height: min(var(--mon-territorial-loading-min-height, 420px), calc(100vh - 310px));
  height: auto;
  display: grid;
  align-items: start;
  border: 1px solid var(--mon-border);
  border-radius: 12px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(248, 250, 253, 0.9)),
    var(--pulso-surface);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.84),
    0 1px 2px rgba(15, 23, 42, 0.04);
  overflow: hidden;
  padding: clamp(16px, 3vh, 28px);
}

.mon-territorial-loading.is-modelo { --territorial-loading-accent: #0f766e; }
.mon-territorial-loading.is-calidad { --territorial-loading-accent: #b45309; }
.mon-territorial-loading.is-consultas,
.mon-territorial-loading.is-ocurrencias { --territorial-loading-accent: var(--pulso-module-monitoring); }
.mon-territorial-loading.is-avance { --territorial-loading-accent: #2563eb; }

.mon-territorial-loading::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 3px;
  background: linear-gradient(90deg, transparent, var(--territorial-loading-accent), transparent);
  opacity: 0.64;
}

.mon-territorial-loading-shell {
  width: min(980px, 100%);
  margin: clamp(2px, 1vh, 12px) auto 0;
  display: grid;
  grid-template-columns: minmax(340px, 1fr) minmax(300px, 0.82fr);
  grid-template-areas:
    "main steps"
    "skeleton skeleton"
    "foot foot";
  gap: 14px;
}

.mon-territorial-loading-main {
  grid-area: main;
  min-width: 0;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  align-items: center;
  gap: 11px;
  border: 1px solid color-mix(in srgb, var(--territorial-loading-accent) 16%, var(--pulso-border));
  border-radius: 11px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--territorial-loading-accent) 5%, #fff), rgba(255, 255, 255, 0.86)),
    #fff;
  padding: 12px;
}

.mon-territorial-loading-icon {
  width: 42px;
  height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid color-mix(in srgb, var(--territorial-loading-accent) 28%, var(--pulso-border));
  border-radius: 10px;
  background: color-mix(in srgb, var(--territorial-loading-accent) 10%, #fff);
  color: var(--territorial-loading-accent);
}

.mon-territorial-loading-main > div {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.mon-territorial-loading-eyebrow,
.mon-territorial-loading-foot {
  color: var(--pulso-text-soft);
  font-size: 10px;
  font-weight: 860;
  line-height: 1.1;
  text-transform: uppercase;
}

.mon-territorial-loading-main strong {
  min-width: 0;
  display: -webkit-box;
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 16px;
  font-weight: 900;
  line-height: 1.12;
  text-overflow: ellipsis;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  white-space: normal;
}

.mon-territorial-loading-main p {
  max-width: 58ch;
  margin: 0;
  color: var(--pulso-text-soft);
  font-size: 12px;
  font-weight: 680;
  line-height: 1.42;
}

.mon-territorial-loading-main em {
  grid-column: 2;
  justify-self: start;
  min-height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid color-mix(in srgb, var(--territorial-loading-accent) 22%, var(--pulso-border));
  border-radius: var(--pulso-radius-chip);
  background: color-mix(in srgb, var(--territorial-loading-accent) 7%, #fff);
  color: color-mix(in srgb, var(--territorial-loading-accent) 84%, var(--pulso-text) 16%);
  font-size: 11px;
  font-style: normal;
  font-weight: 820;
  padding: 5px 9px;
  white-space: nowrap;
}

.mon-territorial-loading-steps {
  grid-area: steps;
  min-width: 0;
  display: grid;
  gap: 7px;
}

.mon-territorial-loading-steps article {
  min-width: 0;
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr);
  align-items: center;
  gap: 9px;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 82%, #fff);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.74);
  padding: 8px;
}

.mon-territorial-loading-steps article > span {
