  grid-template-rows: 22px auto auto;
  gap: 2px;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 88%, #fff);
  border-radius: 9px;
  background: color-mix(in srgb, var(--pulso-surface) 92%, var(--aulas-step-accent) 4%);
  padding: 8px 24px 8px 8px;
}

.mon-aulas-pipeline-step.is-ready { --aulas-step-accent: #257a55; }
.mon-aulas-pipeline-step.is-effective { --aulas-step-accent: #168a55; }
.mon-aulas-pipeline-step.is-warning { --aulas-step-accent: var(--pulso-warn-accent); }
.mon-aulas-pipeline-step.is-base { --aulas-step-accent: var(--pulso-primary); }

.mon-aulas-pipeline-step > i {
  width: 22px;
  height: 22px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 7px;
  background: color-mix(in srgb, var(--aulas-step-accent) 12%, #fff);
  color: var(--aulas-step-accent);
}

.mon-aulas-pipeline-step b,
.mon-aulas-pipeline-step strong,
.mon-aulas-pipeline-step small {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-aulas-pipeline-step b {
  color: var(--pulso-text-soft);
  font-size: 9.5px;
  font-weight: 840;
  text-transform: uppercase;
}

.mon-aulas-pipeline-step strong {
  color: var(--pulso-text);
  font-size: 13px;
  font-weight: 860;
}

.mon-aulas-pipeline-step small {
  color: var(--pulso-text-soft);
  font-size: 10.5px;
}

.mon-aulas-pipeline-step > svg {
  position: absolute;
  top: 12px;
  right: 7px;
  color: var(--pulso-text-faint);
}

.mon-aulas-representativity {
  min-width: 0;
  display: grid;
  gap: 10px;
  border-radius: 12px;
  padding: 10px;
}

.mon-aulas-representativity header {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.mon-aulas-representativity header span {
  min-width: 0;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 12px;
  font-weight: 860;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-aulas-representativity header svg {
  color: var(--pulso-module-monitoring);
}

.mon-aulas-representativity header em {
  flex: 0 0 auto;
  border: 1px solid var(--pulso-border);
  border-radius: var(--pulso-radius-chip);
  background: var(--pulso-surface-2);
  color: var(--pulso-text-soft);
  font-size: 11px;
  font-style: normal;
  font-weight: 830;
  padding: 4px 8px;
  white-space: nowrap;
}

.mon-aulas-representativity header em.is-ready {
  border-color: var(--pulso-success-border);
  background: var(--pulso-success-bg);
  color: var(--pulso-success-fg);
}

.mon-aulas-representativity header em.is-warning {
  border-color: var(--pulso-warn-border);
  background: var(--pulso-warn-bg);
  color: var(--pulso-warn-fg);
}

.mon-aulas-representativity > div {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
}

.mon-aulas-representativity > div span {
  min-width: 0;
  display: grid;
  grid-template-columns: 16px minmax(0, 1fr);
  gap: 2px 7px;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 88%, #fff);
  border-radius: 9px;
  background: color-mix(in srgb, var(--pulso-surface) 92%, var(--pulso-module-monitoring-soft) 8%);
  padding: 8px;
}

.mon-aulas-representativity > div svg {
  grid-row: 1 / span 2;
  margin-top: 1px;
  color: var(--pulso-module-monitoring);
}

.mon-aulas-representativity > div b,
.mon-aulas-representativity > div strong {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-aulas-representativity > div b {
  color: var(--pulso-text-soft);
  font-size: 9.5px;
  font-weight: 850;
  text-transform: uppercase;
}

.mon-aulas-representativity > div strong {
  color: var(--pulso-text);
  font-size: 13px;
  font-weight: 870;
}

.mon-aulas-representativity p {
  margin: 0;
  color: var(--pulso-text-soft);
  font-size: 12px;
  line-height: 1.35;
}

.mon-aulas-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  border-radius: 12px;
  padding: 8px;
}

.mon-aulas-meta span {
  min-height: 26px;
  min-width: 0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 88%, #fff);
  border-radius: var(--pulso-radius-chip);
  background: var(--pulso-surface-2);
  color: var(--pulso-text-soft);
  font-size: 11.5px;
  font-weight: 760;
  padding: 4px 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-aulas-meta svg {
  flex: 0 0 auto;
  color: var(--pulso-primary);
}

.mon-aulas-table-shell {
  min-height: 260px;
  min-width: 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  overflow: hidden;
  border-radius: 12px;
}

.mon-aulas-table-head {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 1px solid var(--pulso-border);
  padding: 10px 12px;
}

.mon-aulas-table-head > div {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.mon-aulas-table-head strong {
  min-width: 0;
  overflow: hidden;
  color: var(--pulso-text);
  font-size: 13px;
  font-weight: 840;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-aulas-table-tools {
  flex: 0 1 430px;
  min-width: 260px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}

.mon-aulas-search {
  flex: 1 1 230px;
  min-width: 190px;
  max-width: 320px;
  height: 30px;
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) auto;
  align-items: center;
  gap: 5px;
  border: 1px solid color-mix(in srgb, var(--pulso-border) 88%, #fff);
  border-radius: 8px;
  background: #fff;
  color: var(--pulso-text-soft);
  padding: 0 6px 0 8px;
  transition:
    border-color var(--motion-dur-fast) var(--motion-ease-out),
    box-shadow var(--motion-dur-fast) var(--motion-ease-out),
    background-color var(--motion-dur-fast) var(--motion-ease-out);
}

.mon-aulas-search:focus-within {
  border-color: color-mix(in srgb, var(--pulso-primary) 34%, var(--pulso-border));
  box-shadow: 0 0 0 3px var(--pulso-primary-focus);
}

.mon-aulas-search input {
  width: 100%;
  min-width: 0;
  border: 0;
  background: transparent;
  color: var(--pulso-text);
  font: inherit;
  font-size: 12px;
  outline: none;
}

.mon-aulas-search input::placeholder {
  color: var(--pulso-text-faint);
}

.mon-aulas-search button {
  width: 20px;
  height: 20px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--pulso-text-soft);
  cursor: pointer;
  padding: 0;
}

.mon-aulas-search button:hover {
  background: var(--pulso-surface-3);
  color: var(--pulso-text);
}

.mon-aulas-table-wrap {
  min-height: 0;
  max-height: min(52vh, 560px);
  overflow: auto;
}

.mon-aulas-table {
  width: 100%;
  min-width: 920px;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 12px;
}

.mon-aulas-table th,
.mon-aulas-table td {
  max-width: 260px;
  padding: 8px 10px;
  border-bottom: 1px solid color-mix(in srgb, var(--pulso-border) 78%, #fff);
  text-align: left;
  vertical-align: middle;
}

.mon-aulas-table th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: var(--pulso-header-row);
  color: var(--pulso-text-soft);
  font-size: 10.5px;
  font-weight: 840;
  letter-spacing: 0.02em;
  line-height: 1.15;
  text-transform: uppercase;
}

.mon-aulas-table td {
  color: var(--pulso-text);
  line-height: 1.32;
  overflow-wrap: anywhere;
}

.mon-aulas-table tbody tr:nth-child(even) td {
  background: rgba(248, 250, 253, 0.52);
}

.mon-aulas-badge {
  --aulas-badge-accent: var(--pulso-primary);
  min-height: 23px;
  display: inline-flex;
  align-items: center;
  border: 1px solid color-mix(in srgb, var(--aulas-badge-accent) 24%, var(--pulso-border));
  border-radius: var(--pulso-radius-chip);
  background: color-mix(in srgb, var(--aulas-badge-accent) 9%, #fff);
  color: var(--aulas-badge-accent);
  font-size: 11px;
  font-weight: 820;
  line-height: 1;
  padding: 3px 8px;
  white-space: nowrap;
}

.mon-aulas-badge.is-effective,
.mon-aulas-badge.is-ready {
  --aulas-badge-accent: #257a55;
}

.mon-aulas-badge.is-partial,
.mon-aulas-badge.is-pending {
  --aulas-badge-accent: #64748b;
}

.mon-aulas-badge.is-warning {
  --aulas-badge-accent: var(--pulso-warn-accent);
}

.mon-aulas-badge.is-refusal {
  --aulas-badge-accent: #b42318;
}

.mon-aulas-table-link {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--pulso-primary);
  font-size: 11.5px;
  font-weight: 820;
  text-decoration: none;
}

.mon-aulas-table-link:hover {
  text-decoration: underline;
}

.mon-production-annulments {
  display: grid;
  gap: 12px;
  min-width: 0;
}

.mon-production-annulments__hero,
.mon-production-annulments__control,
.mon-production-annulments__impact,
.mon-production-annulments__history {
  border: 1px solid color-mix(in srgb, var(--pulso-danger, #be123c) 20%, var(--pulso-border, #d8e0ec));
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(255, 247, 249, 0.82), rgba(255, 255, 255, 0.96));
  box-shadow: var(--pulso-shadow-soft, 0 12px 28px rgba(15, 23, 42, 0.06));
}

.mon-production-annulments__hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 16px;
  align-items: center;
  padding: 18px 20px;
}

.mon-production-annulments__hero span,
.mon-production-annulments__impact header span,
.mon-production-annulments__history header span,
.mon-production-annulments__control label > span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--pulso-danger, #be123c);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.mon-production-annulments__hero strong,
.mon-production-annulments__impact header strong,
.mon-production-annulments__history header strong {
  display: block;
  margin-top: 5px;
  color: var(--pulso-ink, #17212f);
  font-size: 21px;
  font-variant-numeric: tabular-nums;
  line-height: 1.12;
}

.mon-production-annulments__hero p {
  margin: 7px 0 0;
  max-width: 760px;
  color: var(--pulso-muted, #657186);
  font-size: 13.5px;
}

.mon-production-annulments__chips,
.mon-production-annulments__metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(120px, 1fr));
  gap: 8px;
}

.mon-production-annulments__chips span,
.mon-production-annulments__metrics span {
  display: grid;
  gap: 2px;
  min-width: 0;
  border: 1px solid var(--pulso-border, #d8e0ec);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.86);
  padding: 9px 11px;
}

.mon-production-annulments__chips strong,
.mon-production-annulments__metrics strong {
  color: var(--pulso-ink, #17212f);
  font-size: 20px;
  line-height: 1;
}

.mon-production-annulments__chips em,
.mon-production-annulments__metrics em {
  overflow: hidden;
  color: var(--pulso-muted, #657186);
  font-size: 10.5px;
  font-style: normal;
  font-weight: 850;
  letter-spacing: 0.04em;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.mon-production-annulments__chips .is-danger {
  border-color: color-mix(in srgb, var(--pulso-danger, #be123c) 30%, var(--pulso-border, #d8e0ec));
  background: color-mix(in srgb, var(--pulso-danger, #be123c) 7%, #fff);
}

.mon-production-annulments__grid {
  display: grid;
  grid-template-columns: minmax(300px, 0.68fr) minmax(0, 1.32fr);
  gap: 12px;
  min-width: 0;
}

.mon-production-annulments__control,
.mon-production-annulments__impact,
.mon-production-annulments__history {
  min-width: 0;
  padding: 14px;
}

.mon-production-annulments__control {
  display: grid;
  align-content: start;
  gap: 11px;
}

.mon-production-annulments__control label {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.mon-production-annulments__control select,
.mon-production-annulments__control input,
.mon-production-annulments__control textarea {
  width: 100%;
  min-width: 0;
  border: 1px solid var(--pulso-border, #d8e0ec);
  border-radius: 8px;
  background: #fff;
  color: var(--pulso-ink, #17212f);
  font: inherit;
  font-size: 13px;
  padding: 9px 10px;
}

.mon-production-annulments__control textarea {
  min-height: 92px;
  resize: vertical;
}

.mon-production-annulments__responsible-picker {
  border: 1px solid color-mix(in srgb, var(--pulso-danger, #be123c) 16%, var(--pulso-border, #d8e0ec));
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.66);
  padding: 9px;
}

.mon-production-annulments__search {
  position: relative;
  display: grid;
  align-items: center;
  min-width: 0;
}

.mon-production-annulments__search svg {
  position: absolute;
  left: 11px;
  z-index: 1;
  color: var(--pulso-muted, #657186);
  pointer-events: none;
}

.mon-production-annulments__control .mon-production-annulments__search input {
  border-color: color-mix(in srgb, var(--pulso-danger, #be123c) 18%, var(--pulso-border, #d8e0ec));
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(248, 250, 253, 0.88)),
    #fff;
  padding-left: 32px;
}

.mon-production-annulments__control .mon-production-annulments__search input:focus,
.mon-production-annulments__control select:focus,
.mon-production-annulments__control input:focus,
.mon-production-annulments__control textarea:focus {
  border-color: color-mix(in srgb, var(--pulso-danger, #be123c) 48%, var(--pulso-border, #d8e0ec));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--pulso-danger, #be123c) 12%, transparent);
  outline: none;
}

.mon-production-annulments__filter-note {
  color: var(--pulso-muted, #657186);
  font-size: 11.5px;
  font-style: normal;
  font-weight: 760;
}

.mon-production-annulments__responsible {
  display: grid;
  gap: 4px;
  border: 1px solid var(--pulso-border, #d8e0ec);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.72);
  padding: 10px 11px;
}

.mon-production-annulments__responsible strong {
  color: var(--pulso-ink, #17212f);
  font-size: 14px;
}

.mon-production-annulments__responsible span,
.mon-production-annulments__responsible em {
  color: var(--pulso-muted, #657186);
  font-size: 12px;
  font-style: normal;
}

.mon-production-annulments__responsible em {
  color: var(--pulso-danger, #be123c);
  font-weight: 850;
}

.mon-production-annulments__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.mon-production-annulments__actions button,
.mon-production-annulments__history-list button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 34px;
  border: 1px solid var(--pulso-border, #d8e0ec);
  border-radius: 8px;
  background: #fff;
  color: var(--pulso-ink, #17212f);
  font-size: 12px;
  font-weight: 850;
  padding: 0 11px;
}

.mon-production-annulments__actions button.is-danger {
  border-color: color-mix(in srgb, var(--pulso-danger, #be123c) 38%, #fff);
  background: var(--pulso-danger, #be123c);
  color: #fff;
}

.mon-production-annulments__actions button:disabled,
.mon-production-annulments__history-list button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.mon-production-annulments__error {
  margin: 0;
  border: 1px solid #fecaca;
  border-radius: 8px;
  background: #fff1f2;
  color: #991b1b;
  font-size: 12px;
  font-weight: 800;
  padding: 8px 10px;
}

.mon-production-annulments__impact {
  display: grid;
  gap: 12px;
}

.mon-production-annulments__tablewrap {
  overflow: auto;
  border: 1px solid var(--pulso-border, #d8e0ec);
  border-radius: 8px;
  background: #fff;
}

.mon-production-annulments__tablewrap table {
  width: 100%;
  min-width: 760px;
  border-collapse: collapse;
  font-size: 12px;
}

.mon-production-annulments__tablewrap th,
.mon-production-annulments__tablewrap td {
  border-bottom: 1px solid var(--pulso-border, #d8e0ec);
  padding: 9px 10px;
  text-align: left;
  vertical-align: top;
}

.mon-production-annulments__tablewrap th {
  background: #fff7f9;
  color: var(--pulso-muted, #657186);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.mon-production-annulments__tablewrap td strong,
.mon-production-annulments__tablewrap td span {
  display: block;
}

.mon-production-annulments__tablewrap td span {
  color: var(--pulso-muted, #657186);
  font-size: 11px;
}

.mon-production-annulments__history {
  display: grid;
  gap: 11px;
}

.mon-production-annulments__history-list {
  display: grid;
  gap: 8px;
}

.mon-production-annulments__history-list article {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 10px;
  align-items: center;
  border: 1px solid var(--pulso-border, #d8e0ec);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.84);
  padding: 10px 11px;
}

.mon-production-annulments__history-list article.is-active {
  border-color: color-mix(in srgb, var(--pulso-danger, #be123c) 30%, var(--pulso-border, #d8e0ec));
  background: color-mix(in srgb, var(--pulso-danger, #be123c) 5%, #fff);
}

.mon-production-annulments__history-list article > div:first-child {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.mon-production-annulments__history-list article > div:first-child span {
  color: var(--pulso-danger, #be123c);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.mon-production-annulments__history-list article > div:first-child strong {
  overflow: hidden;
  color: var(--pulso-ink, #17212f);
  font-size: 13.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mon-production-annulments__history-list article > div:first-child em,
.mon-production-annulments__reverted,
.mon-production-annulments__history-list p {
  color: var(--pulso-muted, #657186);
  font-size: 12px;
  font-style: normal;
}

.mon-production-annulments__history-list article > div:nth-child(2) {
  display: grid;
  justify-items: end;
  min-width: 86px;
}

.mon-production-annulments__history-list article > div:nth-child(2) strong {
  font-size: 18px;
  line-height: 1;
}

.mon-production-annulments__history-list article > div:nth-child(2) span {
  color: var(--pulso-muted, #657186);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

@media (max-width: 1320px), (max-height: 720px) {
  .mon-workbench.pulso-split-view {
    grid-template-columns: minmax(190px, 208px) minmax(0, 1fr);
  }

  .mon-workbench-rail {
    gap: 5px;
    padding: 6px;
  }

  .mon-workbench-nav {
    grid-auto-rows: minmax(48px, auto);
  }

  .mon-nav-item {
    grid-template-columns: 26px minmax(0, 1fr) 22px;
    min-height: 48px;
    padding: 5px 6px;
  }

  .mon-nav-icon {
    width: 26px;
    height: 26px;
  }

  .mon-nav-status {
    min-width: 22px;
    justify-content: center;
  }

