/* Monitoreo internal chrome standard v2. */
.mon-page {
  --mon-inner-radius: 12px;
  --mon-inner-pill-radius: 999px;
  --mon-inner-control-height: 30px;
  --mon-inner-material:
    linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(248, 250, 253, 0.78)),
    color-mix(in srgb, var(--pulso-material-bg-strong) 78%, #fff 22%);
  --mon-inner-material-soft:
    linear-gradient(180deg, rgba(255, 255, 255, 0.8), rgba(248, 250, 253, 0.66)),
    color-mix(in srgb, var(--pulso-surface-2) 78%, #fff 22%);
  --mon-inner-border: color-mix(in srgb, var(--pulso-module-monitoring-border) 20%, var(--pulso-material-border));
  --mon-inner-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.86),
    0 1px 2px rgba(15, 23, 42, 0.045);
}

.mon-workbench.pulso-split-view:has(> .mon-workbench-rail.is-collapsible),
.mon-page .mon-workbench.pulso-split-view:has(> .mon-workbench-rail.is-collapsible),
.mon-page .mon-workbench.pulso-split-view:has(> .mon-workbench-rail.is-collapsible:hover),
.mon-page .mon-workbench.pulso-split-view:has(> .mon-workbench-rail.is-collapsible:focus-within) {
  --mon-rail-collapsed-size: clamp(60px, 4.8vw, 64px);
  grid-template-columns: var(--mon-rail-collapsed-size) minmax(0, 1fr) !important;
}

.mon-workbench-rail.is-collapsible {
  width: var(--mon-rail-collapsed-size);
  border-right: 1px solid color-mix(in srgb, var(--pulso-module-monitoring-border) 20%, var(--pulso-border));
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.78), rgba(247, 249, 253, 0.72)),
    color-mix(in srgb, var(--pulso-surface-2) 78%, #fff 22%);
  box-shadow:
    inset -1px 0 0 rgba(255, 255, 255, 0.72),
    inset 1px 0 0 rgba(255, 255, 255, 0.54);
}

.mon-workbench-rail.is-collapsible .mon-section-local-tabs {
  --mon-local-tab-size: 38px;
  --mon-local-tab-gap: 6px;
  position: relative;
  display: grid;
  grid-auto-rows: var(--mon-local-tab-size);
  justify-items: center;
  gap: var(--mon-local-tab-gap);
}

.mon-workbench-rail.is-collapsible .mon-section-local-tabs .mon-nav-item {
  inline-size: var(--mon-local-tab-size);
  block-size: var(--mon-local-tab-size);
  min-inline-size: var(--mon-local-tab-size);
  max-inline-size: var(--mon-local-tab-size);
  min-height: var(--mon-local-tab-size);
  max-height: var(--mon-local-tab-size);
  aspect-ratio: 1;
  box-sizing: border-box;
  display: inline-grid;
  place-items: center;
  justify-self: center;
  align-self: center;
  padding: 4px;
  border: 1px solid transparent;
  border-radius: 12px;
  background: color-mix(in srgb, #fff 72%, var(--pulso-surface-2) 28%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.76);
  transition:
    background-color var(--motion-dur-fast) var(--motion-ease-out),
    border-color var(--motion-dur-fast) var(--motion-ease-out),
    box-shadow var(--motion-dur-fast) var(--motion-ease-out),
    transform var(--motion-dur-press) var(--motion-ease-out);
}

.mon-workbench-rail.is-collapsible .mon-section-local-tabs .mon-nav-item:hover,
.mon-workbench-rail.is-collapsible .mon-section-local-tabs .mon-nav-item:focus-visible {
  border-color: color-mix(in srgb, var(--view-accent) 28%, var(--pulso-border));
  background: color-mix(in srgb, var(--view-accent) 8%, #fff);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.9),
    0 8px 18px rgba(15, 23, 42, 0.08);
  transform: translateY(-1px);
}

.mon-workbench-rail.is-collapsible .mon-section-local-tabs .mon-nav-item.is-active,
.mon-workbench-rail.is-collapsible .mon-section-local-tabs .mon-nav-item[aria-current="page"] {
  border-color: color-mix(in srgb, var(--view-accent) 52%, #fff);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--view-accent) 90%, #fff 10%), var(--view-accent));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.28),
    inset 0 -7px 12px rgba(0, 0, 0, 0.075),
    0 7px 14px color-mix(in srgb, var(--view-accent) 18%, transparent);
  color: #fff;
}

.mon-workbench-rail.is-collapsible .mon-section-local-tabs .mon-nav-item.is-active .mon-nav-icon,
.mon-workbench-rail.is-collapsible .mon-section-local-tabs .mon-nav-item[aria-current="page"] .mon-nav-icon {
  border-color: transparent;
  background: transparent;
  box-shadow: none;
  color: #fff;
}

.mon-workbench-rail.is-collapsible .mon-section-local-tabs .mon-nav-icon {
  flex: 0 0 30px;
  inline-size: 30px;
  block-size: 30px;
  width: 30px;
  height: 30px;
  min-width: 30px;
  min-height: 30px;
  max-width: 30px;
  max-height: 30px;
  box-sizing: border-box;
  aspect-ratio: 1;
  border-radius: 10px;
}

.mon-workbench-rail.is-collapsible .mon-section-local-tabs .mon-nav-tip {
  position: absolute;
  z-index: 20;
  top: var(--mon-nav-tip-y, 19px);
  left: calc(100% + 8px);
  max-width: min(280px, 38vw);
  overflow: hidden;
  transform: translate(-4px, -50%);
  border: 1px solid color-mix(in srgb, var(--view-accent) 26%, var(--pulso-border));
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(248, 250, 253, 0.94)),
    var(--pulso-surface);
  box-shadow:
    0 12px 28px rgba(15, 23, 42, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.88);
  color: var(--pulso-text);
  font-size: 11px;
  font-weight: 820;
  line-height: 1.1;
  opacity: 0;
  padding: 7px 9px;
  pointer-events: none;
  text-overflow: ellipsis;
  transition:
    opacity var(--motion-dur-fast) var(--motion-ease-out),
    transform var(--motion-dur-fast) var(--motion-ease-out);
  white-space: nowrap;
}

.mon-workbench-rail.is-collapsible .mon-section-local-tabs .mon-nav-item:hover + .mon-nav-tip,
.mon-workbench-rail.is-collapsible .mon-section-local-tabs .mon-nav-item:focus-visible + .mon-nav-tip {
