  align-content: stretch;
  overflow: hidden;
}

.mon-page .mon-territorial-route-table-workspace .mon-territorial-route-table-card,
.mon-page .mon-territorial-route-table-workspace .mon-territorial-route-context-card {
  height: 100%;
  min-height: 0;
  max-height: none;
  overflow: hidden;
}

.mon-page .mon-territorial-route-table-workspace .mon-territorial-route-table-card {
  grid-column: 1;
  grid-row: 1;
  grid-template-rows: auto auto minmax(0, 1fr);
}

.mon-page .mon-territorial-route-table-workspace .mon-territorial-route-context-card {
  grid-column: 2;
  grid-row: 1;
}

.mon-page .mon-territorial-route-table-workspace .mon-territorial-route-table-scroll,
.mon-page .mon-territorial-route-table-workspace .mon-territorial-route-context-body {
  min-height: 0;
  height: 100%;
  max-height: none;
  overflow: auto;
}

.mon-page .mon-territorial-route-table-workspace .mon-territorial-route-table-filters {
  gap: 5px;
}

.mon-page .mon-territorial-route-table-workspace .mon-territorial-route-accordion-scroll {
  gap: 6px;
  padding: 6px;
}

.mon-page .mon-territorial-route-accordion-item.is-selected {
  border-color: color-mix(in srgb, var(--pulso-module-monitoring) 22%, var(--pulso-border));
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--pulso-module-monitoring) 2%, #fff), rgba(255, 255, 255, 0.97)),
    #fff;
  box-shadow:
    inset 2px 0 0 color-mix(in srgb, var(--pulso-module-monitoring) 58%, var(--pulso-text) 6%),
    0 6px 16px rgba(15, 23, 42, 0.045);
}

.mon-page .pulso-panel button.mon-territorial-route-accordion-trigger {
  min-height: 64px;
  padding: 8px 9px;
}

.mon-page .mon-territorial-route-accordion-title em {
  -webkit-line-clamp: 1;
}

.mon-page .mon-territorial-route-accordion-body {
  gap: 6px;
  padding: 6px 7px 7px 29px;
}

.mon-page .pulso-panel button.mon-territorial-route-primary-block,
.mon-page .pulso-panel button.mon-territorial-route-replacement-row {
  border-radius: 8px;
  padding: 6px 7px;
}

.mon-page .pulso-panel button.mon-territorial-route-primary-block.is-inspected {
  border-color: color-mix(in srgb, var(--pulso-module-monitoring) 18%, var(--pulso-border));
  background: rgba(255, 255, 255, 0.9);
  box-shadow:
    inset 2px 0 0 color-mix(in srgb, var(--pulso-module-monitoring) 42%, transparent),
    0 4px 12px rgba(15, 23, 42, 0.035);
}

.mon-page .pulso-panel button.mon-territorial-route-replacement-row.is-inspected {
  border-color: color-mix(in srgb, var(--pulso-warn-border) 42%, var(--pulso-border));
  background: color-mix(in srgb, var(--pulso-warn-bg) 12%, #fff);
  box-shadow:
    inset 2px 0 0 color-mix(in srgb, var(--pulso-warn-border) 58%, transparent),
    0 4px 12px rgba(15, 23, 42, 0.035);
}

.mon-page .mon-territorial-route-atlas > .mon-territorial-route-summary-hero {
  grid-template-columns: minmax(0, 1fr) minmax(220px, 300px);
  grid-template-rows: auto minmax(0, 1fr);
  align-content: start;
}

.mon-page .mon-territorial-route-atlas > .mon-territorial-route-summary-hero .mon-territorial-route-summary-metrics {
  grid-column: 1 / -1;
  grid-template-columns: repeat(3, minmax(150px, 1fr));
}

.mon-page .mon-territorial-route-atlas > .mon-territorial-route-summary-hero > div:first-child strong,
.mon-page .mon-territorial-route-atlas > .mon-territorial-route-summary-hero > div:first-child em {
  overflow: visible;
  text-overflow: clip;
  white-space: normal;
}

.mon-page .mon-territorial-route-atlas > .mon-territorial-route-summary-hero .mon-territorial-route-kpi {
  min-height: 62px;
  grid-template-columns: auto minmax(0, 1fr);
  padding: 8px 9px;
}

.mon-page .mon-territorial-route-atlas > .mon-territorial-route-summary-hero .mon-territorial-route-kpi span,
.mon-page .mon-territorial-route-atlas > .mon-territorial-route-summary-hero .mon-territorial-route-kpi em {
  white-space: normal;
}

@media (max-width: 1120px) {
  .mon-page .mon-territorial-route-workbench .mon-territorial-route-command,
  .mon-page .mon-territorial-route-table-workspace .mon-territorial-route-sidebar {
    grid-template-columns: minmax(0, 1fr);
  }

  .mon-page .mon-territorial-route-atlas > .mon-territorial-route-summary-hero {
    grid-template-columns: minmax(0, 1fr);
  }

  .mon-page .mon-territorial-route-atlas > .mon-territorial-route-summary-hero .mon-territorial-route-summary-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .mon-page .mon-territorial-route-table-workspace {
    height: auto;
    min-height: 0;
    overflow: visible;
  }

  .mon-page .mon-territorial-route-table-workspace .mon-territorial-route-sidebar,
  .mon-page .mon-territorial-route-table-workspace .mon-territorial-route-table-card,
  .mon-page .mon-territorial-route-table-workspace .mon-territorial-route-context-card {
    grid-column: auto;
    grid-row: auto;
    height: auto;
    overflow: visible;
  }
}
